    [305] = "塔雷爾·石紋要求你到挖掘場裡去找到麥琳·石紋。",
    [306] = "把麥琳的信件交給塔雷爾·石紋覆命。",
    [307] = "到銀泉礦坑去收集4套礦工裝備，然後向巡山人卡爾·雷矛覆命。",
    [309] = "確保把米蘭和貨物送到挖掘場，然後通知勘察員基恩薩·鐵環。",
