    [314] = "山羊農場的魯德拉·凍石要你殺了瓦加什，並且把它的牙齒給她帶回去。",
    [315] = "收集6束微光草，把它們交給烈酒村的雷傑德·麥酒。",
    [317] = "收集4大塊野豬肉和2張厚熊皮，把它們交給鋼架補給站的駕駛員貝隆·風箱。",
    [318] = "從烈酒村的雷傑德·麥酒那里弄到一桶艾沃沙酒。",
    [319] = "殺掉6頭冰爪熊、8隻老峭壁野豬和8隻雪豹，然後回到烈酒村的雷傑德·麥酒那裡。",
    [320] = "把這桶艾沃沙酒交給鋼架補給站的駕駛員貝隆·風箱。",
    [321] = "搜索飛翔魚鷹號的殘骸。",
    [322] = "將這箱光鑄鐵錠交給格瑞曼德·艾爾默。",
    [323] = "殺掉15個骷髏襲擊者、3個骷髏醫師和3個骷髏看守，然後回來見斯溫。",
    [324] = "收集5塊光鑄鐵錠，把它們交給濕地的戈羅林·鋼眉。",
    [325] = "現在你已經得到了強大的武器，去向暮色森林的斯溫覆命吧。",
    [328] = "使用黃銅鑰匙打開書呆子赫羅德的保險箱。",
    [329] = "將沾泥的便箋交給叛軍營地裡的多倫上尉。",
    [330] = "與塞斯曼下士談話。",
    [331] = "與多倫上尉談話。",
    [332] = "到加林納酒店去, 將酒票交給蘇澤塔·加林納以換一瓶免費的酒。",
    [333] = "找到運河裁縫店，並將哈蘭·巴格雷的布料訂單帶給雷瑪·施涅德。",
    [334] = "到暴風城法師區的拉爾森服裝店去，將針線包帶給薩爾曼·斯涅德。",
    [335] = "黑爪加爾德斯要求你從夜色鎮給他摘1朵蒂羅亞之淚，再從濕地給他采一塊麝鼠根。",
    [336] = "將黑爪烈酒帶給祈願廳裡的維沙克公爵。",
    [337] = "把《暴風城的歷史》這本書還給暴風城圖書館。",
    [338] = "收集《荊棘谷的青山》的手稿中丟失的頁面。在集齊四章書之後，將它們還給巴尼爾·石罐。",
    [339] = "將奈辛瓦里的小說《荊棘谷的青山》的第1頁，第4頁，第6頁和第8頁帶給巴尼爾·石罐以湊齊第一章。",
    [340] = "將奈辛瓦里的小說《荊棘谷的青山》的第10頁，第11頁，第14頁和第16頁帶給巴尼爾·石罐以湊齊第二章。",
    [341] = "將奈辛瓦里的小說《荊棘谷的青山》的第18頁，第20頁，第21頁和第24頁帶給巴尼爾·石罐以湊齊第三章。",
    [342] = "將奈辛瓦里的小說《荊棘谷的青山》的第25頁，第26頁和第27頁帶給巴尼爾·石罐以湊齊第四章。",
    [343] = "到暴風城堡的皇家圖書館去與密爾頓·西弗交談，他將會為你找到克里斯多夫修士所需要的關於冶金學的書。",
    [344] = "與北郡修道院的帕克斯頓修士談話。",
    [345] = "與湖畔鎮的工頭奧斯洛交談，並向他要一些瑞斯班鐵礦石。",
    [346] = "回到教堂廣場，將《金屬的延展性》交給克里斯多夫修士。",
    [347] = "收集5袋瑞斯班礦石，把它們帶給北郡圖書館的帕克斯頓修士。",
    [348] = "找到巫醫安巴格瓦並要求他召喚出野人莫克，然後將野人莫克的心臟交給芬·菲茲拉克。",
    [350] = "與暴風城的伊林·提亞斯談話。",
    [351] = "把定位器帶到奧格索普的母體機器人那裡。",
    [353] = "把給卡爾·雷矛的包裹交給洛克莫丹北部哨塔里的巡山人卡爾·雷矛。",
    [354] = "把格里高的遺骸、妮薩的殘骸和薩爾曼的遺骸交給布瑞爾的庫勒曼·法席恩。",
    [355] = "與布瑞爾的執政官塞弗倫談話。",
    [356] = "殺死8個可怕的血殭屍和8個遊蕩的幽靈，然後向亡靈衛兵林奈彙報。",
    [357] = "把巫妖的法術書帶給幽暗城的比索·埃斯沙德。",
    [358] = "殺死腐皮盜墓賊和混血腐皮豺狼人。 給布瑞爾的執政官塞弗倫帶回8瓶防腐劑。",
    [359] = "與亡靈衛兵林奈談話。",
    [360] = "向布瑞爾的執政官塞弗倫報告。",
    [361] = "找到伊維特·法席恩，將薩爾曼·阿加曼德的信交給她。",
    [362] = "殺死代弗林·阿加曼德，然後將代弗林的遺骸交給布瑞爾的庫勒曼·法席恩。",
    [363] = "和暗影牧師薩維斯談話。",
    [364] = "暗影牧師薩維斯讓你殺掉8個無腦的殭屍和8個醜陋的殭屍。",
    [365] = "從位於布瑞爾西邊、喪鐘鎮北邊的農場中偷10顆南瓜來，把它們交給布瑞爾的藥劑師喬漢。",
    [366] = "到岡瑟爾居住的小島去歸還他的法術書。",
    [367] = "布瑞爾鎮裡的藥劑師喬漢要求你收集5瓶黑暗犬的血液。",
    [368] = "布瑞爾鎮裡的藥劑師喬漢要求你收集5片提里斯法林地的邪鰭魚人的鱗片。",
    [369] = "布瑞爾鎮裡的藥劑師喬漢要你去收集4份邪惡的夜行蜘蛛的毒液樣本。",
    [370] = "布瑞爾的執行官塞加德要求你殺掉派瑞恩隊長、3名血色狂熱者和3名血色傳教士。",
    [371] = "布瑞爾的執行官塞加德要求你殺掉瓦松隊長和5名血色苦行修士。",
    [372] = "布瑞爾的執行官塞加德要求你刺殺麥拉其隊長及他的兩名保鏢。",
    [373] = "將艾德溫·范克里夫的信交給巴洛斯·艾力克斯頓。",
    [374] = "給布瑞爾的亡靈衛兵伯吉斯帶回10枚血色十字軍徽記之戒。",
    [375] = "給布瑞爾的格雷森·戴德馬帶回5張夜行蝙蝠的毛皮和一些粗線。",
    [376] = "新兵艾爾雷斯需要6隻食腐狼的爪子和6隻夜行蝙蝠翼。",
    [377] = "夜色鎮的米爾斯迪普議員要你殺死迪克斯特·瓦德，並把他的手帶回來作為證明。",
    [378] = "丹莫德的莫特雷·加瑪森要求你把卡姆·深怒的頭顱交給他。",
    [379] = "給加基森的首席工程師沙克斯·比格維茲帶去五隻廢土水袋。",
    [380] = "執行官阿倫要你去殺掉10隻小夜行蜘蛛和8隻夜行蜘蛛。",
    [381] = "從血色信徒和血色新兵身上收集12枚血色十字軍臂章，把它們交給執行官阿倫。",
    [382] = "到十字軍營地去殺掉信差邁文·考加爾，將你發現的情報交給執行官阿倫。",
    [383] = "把血色十字軍檔案交給布瑞爾的執行官塞加德。",
    [384] = "卡拉諾斯的拉格納·雷酒需要6塊峭壁野豬肋排和1杯狂想麥酒。",
    [385] = "收集5塊鱷魚肉和6張鱷魚皮，把它們交給旅行者營地裡的馬雷克·鐵心。",
    [386] = "把塔高爾的頭顱帶給湖畔鎮的衛兵伯爾頓。",
    [387] = "暴風城的典獄官塞爾沃特要求你殺死監獄中的10名迪菲亞囚犯、8名迪菲亞罪犯和8名迪菲亞叛軍。",
    [388] = "暴風城的尼科瓦·拉斯克要你取得10條紅色毛紡面罩。",
    [389] = "與監獄的典獄官塞爾沃特談話。",
    [391] = "殺死巴基爾·斯瑞德，把他的頭帶給監獄的典獄官塞爾沃特。",
    [392] = "將神秘訪客的資料交給暴風城的巴洛斯·艾力克斯頓。",
    [393] = "與舊城區的馬迪亞斯·肖爾談話。",
    [394] = "與暴風城舊城區的馬迪亞斯·肖爾談話。",
    [395] = "與暴風城的巴洛斯·艾力克斯頓談話。",
    [396] = "將有關迪菲亞兄弟會的報告送給暴風要塞裡的國王瓦里安·烏瑞恩。",
    [397] = "去找黑爪加爾德斯的僕人茲吉談一談，並向他索要你的酬勞。",
    [398] = "殺死蛆眼，並將他的爪子交給布瑞爾的執行官塞加德以換取酬勞。",
    [399] = "到巴洛斯·艾力克斯頓在西部荒野的房子裡找尋他的指南針，並帶回暴風城教堂區給他。",
    [400] = "把貝爾丁的工具交給貝爾丁·鋼架。",
    [401] = "稍等片刻，然後再和希拉·沃寧迪交談。",
    [404] = "給布瑞爾的亡靈衛兵迪林格爾帶回7隻腐爛的爪子。",
    [405] = "將塞弗倫的命令交給幽暗城的比索·埃斯沙德。",
    [407] = "將斑紋南瓜帶給被關在恐懼之末旅店地下室中的血色十字軍俘虜。",
    [408] = "殺死8個哀嚎的鬼魂和8個腐爛的古屍。 消滅達高爾隊長，並將他的顱骨交給布瑞爾的執政官塞弗倫。",
    [409] = "取得一根誘靈蠟燭。 召喚出莉莉絲·奈法拉並殺死她。 然後回去島上找岡瑟爾。",
    [411] = "將虛空寶石交給幽暗城的比索·埃斯沙德。",
    [412] = "收集8個多檔齒輪和8個自適應齒輪，把它們交給卡拉諾斯的拉茲·滑鏈。",
    [413] = "把這一大桶微光酒交給巡山人維拉特·麥酒。",
    [414] = "把這桶微光酒帶給巡山人卡德雷爾。",
    [415] = "和雷傑德·麥酒談話。",
    [416] = "收集12隻坑道鼠的耳朵，把它們帶給塞爾薩瑪的巡山人卡德雷爾。",
    [417] = "殺死癩爪。 把牠的骯髒的爪子和莫里·鐵鑽的日記交給駕駛員塞克·錘足。",
    [418] = "收集3塊熊肉、3根豬大腸和3份蜘蛛的毒液，把它們交給塞爾薩瑪的維德拉·壁爐。",
    [419] = "找到駕駛員莫里·鐵鑽。",
    [420] = "把格瑞林的報告交給卡拉諾斯的森內爾·白鬚。",
    [421] = "瑟伯切爾的達拉爾·道恩維沃爾要求你殺死5隻月怒白頭狼人。",
    [422] = "為瑟伯切爾的達拉爾·道恩維沃爾找回《阿魯高的拯救》。",
    [423] = "給瑟伯切爾的達拉爾·道恩維沃爾帶回6副暴食者鐐銬和3副魔魂鐐銬。",
    [424] = "殺死白毛狼人格瑞姆森，把他的頭帶給瑟伯切爾的達拉爾·道恩維沃爾。",
    [425] = "殺死邪惡的伊瓦，並將伊瓦的頭顱帶給伊瓦農莊的蘭妮·尤瑞克。",
    [426] = "收集5根鋸齒肋骨和3個焦黑的顱骨，然後向布瑞爾的亡靈衛兵迪林格爾回報。",
    [427] = "布瑞爾的執行官塞加德要求你去殺掉10名血色十字軍戰士。",
    [428] = "找到亡靈哨兵蘭妮·尤瑞克和奎恩·尤瑞克。",
    [429] = "收集3顆變色的狼心，把它們交給瑟伯切爾的藥劑師倫弗利爾。",
    [430] = "將奎恩的藥水帶給瑟伯切爾北方伊瓦農場的奎恩·尤瑞克。",
    [432] = "在古博拉採掘場裡替工頭喬尼·石眉殺死6個石齶擊顱者。",
    [433] = "到古博拉採掘場裡替參議員梅爾·聖石殺死10個石齶斷骨者。",
    [434] = "等待葛瑞格·萊斯科瓦公爵和沉默之刃馬爾松在花園裡的對話結束，殺死他們兩個，之後向暴風城的提亞斯回報。",
    [435] = "護送亡靈哨兵埃蘭德避過群狼，直到他找到蘭妮·尤瑞克。",
    [436] = "和麥格瑪爾·落斧談話。",
    [437] = "殺死亡者農場的腐皮豺狼人。 當奈塔拉什出現時，把她也殺了。 將奈塔拉什的靈魂交給瑟伯切爾的高級執行官哈德瑞克。",
    [438] = "到破舊渡口去，找到天譴軍團佔據那裡的理由。",
    [439] = "將黛麗婭的戒指帶給瑟伯切爾的高級執行官哈德瑞克。",
    [440] = "將黛麗婭的戒指帶給布瑞爾的執政官塞弗倫。",
    [441] = "把黛麗婭的戒指交給拉林夫。",
    [442] = "將圖勒的頭顱帶回給瑟伯切爾的高級執行官哈德瑞克。",
    [443] = "給瑟伯切爾的藥劑師倫弗利爾帶去8瓶腐皮豺狼人的膿液。",
    [444] = "將膿液樣本交給幽暗城的比索·埃斯沙德。",
    [445] = "將藥劑師喬漢的研究成果帶給銀松森林的藥劑師倫弗利爾。",
    [446] = "把比索的卷軸交給銀松森林中的藥劑師倫弗利爾。",
    [447] = "收集6個灰熊的心臟和6份粘稠的血液樣本，並將這些東西送給幽暗城的大藥劑師法拉尼爾。",
    [448] = "向瑟伯切爾的高級執行官哈德瑞克覆命。",
    [449] = "將亡靈哨兵的報告的報告交給瑟伯切爾的高級執行官哈德瑞克。",
    [450] = "從焚木村的旅店中找到伯納德的日記，把它交給瑟伯切爾的藥劑師倫弗利爾。",
    [451] = "收集6份湖岸爬行者苔蘚的樣本、6份湖岸潛藏者苔蘚的樣本和1塊硬瘤，把它們交給幽暗城的大藥劑師法拉尼爾。",
    [452] = "幫助亡靈哨兵費雷亞消滅焚木村議會。",
    [453] = "找到那個模糊的人影。你的線索： 他不是夜色鎮的本地人。 他是個緊張而敏感的人。 他離開夜色鎮往西邊去了。",
    [454] = "和米蘭談話。",
    [455] = "翻越丹奧加茲。 殺死8個龍喉斥候和6個龍喉步兵。 向米奈希爾港的瓦斯塔格·鐵齶報到。",
    [456] = "殺死7隻小夜刃豹和4隻小草刺野豬，然後向管理員伊爾薩萊恩覆命。",
    [457] = "管理員伊爾薩萊恩要求你殺死7隻癩皮夜刃豹和7隻草刺野豬。",
    [458] = "找到林精塔琳德拉。",
    [459] = "收集8塊魔苔，把它們交給塔琳德拉。",
    [460] = "將奧拉瑞克的頭顱帶到他的墳墓旁。",
    [461] = "將奧拉瑞克帶到密室去。",
    [463] = "找到綠色守衛者。",
    [464] = "給斯托菲隊長帶回8面龍喉戰旗。",
    [465] = "摧毀所有的龍喉投石車。",
    [466] = "給丹莫洛的駕駛員迪恩·石輪帶回6份火岩礦石。",
    [467] = "和駕駛員迪恩·石輪談話。",
    [468] = "與巡山人羅克加談話。",
    [469] = "將這捆鱷魚皮帶給米奈希爾港的皮匠詹姆士·哈洛倫。",
    [470] = "鐵鬚之墓中的某隻軟泥怪身上有塞達的背包，奪回背包，把它送還給米奈希望港的塞達。",
    [471] = "為米奈希爾港的詹姆士·哈洛倫帶回6張巨型鱷魚的皮。",
    [472] = "在丹莫德鎮附近尋找布萊德·長鬚的蹤跡。",
    [473] = "與斯托菲隊長談話。",
    [474] = "殺掉納克羅什酋長。 將納克羅什的頭顱交給斯托菲隊長。",
    [475] = "在星風村找到蓋洛拉斯·塔文斯倫。",
    [476] = "返回多蘭納爾去見阿斯瑞達斯·熊皮。",
    [477] = "從達拉然法師的木箱中拿出裡面的東西。",
