    [638] = "前往阿拉希高地的落錘鎮，與森谷談話。",
    [639] = "幫落錘村的森古拿回激流堡符印。",
    [640] = "從激流堡的守衛者那裡取回11塊符印碎片，把它們交給落錘村的托爾甘。",
    [641] = "把修復的索拉丁符印交給落錘村的森古。",
    [642] = "收集密斯賴爾之塵。 把它們放在枯鬚峽谷中的虹光水晶碎塊上。",
    [643] = "取回阿拉索符印，把它交給落錘村的森古。",
    [644] = "殺掉加林·托爾貝恩王子，把托爾貝恩符印帶給落錘村的森古。",
    [645] = "從激流堡的托爾貝恩墓室中取回托卡拉爾劍。",
    [646] = "把托卡拉爾劍交給落錘村的森古。",
    [647] = "把馬克里爾的月光酒交給南海鎮的布魯米·比格爾。",
    [648] = "將OOX-17/TN護送到熱砂港，然後向藏寶海灣的奧格索普·奧布諾提斯報告。",
    [649] = "和奧格瑪的瑪爾頓·杜佛斯談話。",
    [650] = "和基沃拉丁·逐日者談一談，他的營地就在辛特蘭區域。",
    [651] = "從西禁錮之石、東禁錮之石和外禁錮之石中搜集烈焰鑰匙、海浪鑰匙和雷霆鑰匙。 把它們帶到內禁錮之石處。",
    [652] = "找到並殺死弗茲魯克，然後把秩序魔棒帶到阿拉希高地的鑰匙之石旁。",
    [653] = "和鐵爐堡的葛利·硬骨談話。",
    [654] = "收集8份蜥蜴樣本、8份土狼樣本和8份蠍子樣本，然後在能量源耗盡之前把野外實驗工具包還給加基森的首席工程師膨嘯。",
    [655] = "和落錘村的托爾甘交談。",
    [656] = "到密斯賴爾水晶裂片去召喚她，然後打敗她。 搜出她身上的怪異鐐銬，將其和密斯賴爾水晶裂片縛在一起。",
    [657] = "和基恩洛談話。",
    [658] = "找到被遺忘者信差，把她的密封的信件交給格沙克農場裡的奎艾。",
    [659] = "到阿拉希高地上的格沙克農場附近找到奎艾和基恩洛。",
    [660] = "保護基恩洛，直到她回到奎艾身邊。",
    [661] = "到南海鎮去找費恩·奧德利克。",
    [662] = "大副尼茲利克斯讓你從處女號和銀松之魂號中取回航海圖和航海日誌。",
    [663] = "和法迪爾海灣的奧布裡船長交談。",
    [664] = "法迪爾海灣的斯迪加特船長要你去殺掉10個刺脊襲擊者和3個刺脊巫師。",
    [665] = "護送菲茲索普教授到洞穴裡去並平安返回。",
    [666] = "法迪爾海灣的德拉克里格博士要你去收集10塊精靈寶石並在完成任務後歸還尋寶潛水鏡。",
    [667] = "在納迦的攻擊中保護沙克斯·奧布裡。",
    [668] = "把精靈寶石交給奧布裡船長。",
    [669] = "把精靈寶石樣本交給藏寶海灣的艦隊指揮官卡拉·海角。",
    [670] = "把海角船長的密信送給阿拉希高地的沙克斯·奧布里。",
    [671] = "幫落錘村的托爾甘找10枚血石護符。",
    [672] = "從高地闊步龍和高地長尾龍身上取得1０個高地迅猛龍的眼睛，把它們交給落錘村的托爾甘。",
    [673] = "取回瑪雷茲·考爾的血石寶珠，把它交給落錘村的托爾甘。",
    [674] = "把迅猛龍利爪護符交給戈莫爾。",
    [675] = "和托爾甘談話。",
    [676] = "殺掉8個石拳巨魔和1０個石拳執行者，然後去阿拉希高地的落錘村哨所找杜拉姆法爾。",
    [677] = "殺死10名枯木擲斧者、10名枯木獵頭者和8個枯木巫醫，然後回到落錘村哨所的杜拉姆法爾那裡。",
    [678] = "殺死10個石拳蠻兵和4個石拳法師，然後向落錘村哨所的杜拉姆法爾覆命。",
    [679] = "殺死15個石拳薩滿和10個石拳領主，然後向落錘村哨所的杜拉姆法爾覆命。",
    [680] = "殺死奧卡拉爾，將他的頭顱帶給落錘村哨所的科林法爾。",
    [681] = "殺掉6個辛迪加雇傭兵和10個辛迪加路霸，然後回到避難谷地去向尼艾絲隊長覆命。",
