    [683] = "把薩拉·巴魯的字條交給鐵爐堡的國王麥格尼·銅鬚。",
    [684] = "把瑪雷茲的頭顱交給避難谷地的尼艾絲隊長。",
    [685] = "把法庫雷斯特和奧圖的頭顱交給避難谷地的尼艾絲隊長。",
    [686] = "國王麥格尼·銅鬚讓你去和大石匠瑪布勒斯坦談話。",
    [687] = "找到迷失者塞爾杜林。",
    [688] = "和落錘村的薩魯克談話。",
    [689] = "鐵爐堡的大石匠瑪布勒斯坦要5塊奧特蘭克花崗岩。",
    [690] = "找到位於阿拉希高地上的避難谷地中的斯奎爾圖。",
    [691] = "幫避難谷地中的學徒克里汀收集10個枯木食人妖的獠牙，4個枯木食人妖的醫藥包和1把暗影獵手的小刀。",
    [692] = "把破損的卷軸碎片、弄皺的卷軸碎片和燒焦的卷軸碎片帶給迷失者塞爾杜林。",
    [693] = "幫避難谷地的斯奎爾圖找到特雷萊恩的符咒魔杖，並把它帶回來。",
    [694] = "找到一塊碧藍瑪瑙石，把它交給避難谷地處的學徒克里汀。",
    [695] = "和斯奎爾圖談話。",
    [696] = "找到特雷萊恩的護符匣、特雷萊恩的寶珠和特雷萊恩的黑瑪瑙，把它們交給避難谷地的斯奎爾圖。",
    [697] = "將給大法師馬林的信交給暴風城法師區裡的大法師馬林。",
    [698] = "給悲傷沼澤的托克卡爾帶去8塊新鮮的鹽齒鱷魚肉。",
    [699] = "給悲傷沼澤的托克卡爾帶去6隻鹽齒鉗嘴鱷的爪子。",
    [700] = "向鐵爐堡的國王麥格尼·銅鬚彙報。",
    [701] = "從高地獵獸龍身上獲取12顆迅猛龍的心臟，把它們交給托爾甘。",
    [702] = "把托爾甘的寶珠交給戈莫爾。",
    [703] = "給里格弗茲帶去4只禿鷲的翅膀。",
    [704] = "收集4個雕紋石罐，把它們交給洛克莫丹的勘察員基恩薩·鐵環。",
    [705] = "收集9枚藍珍珠，把它們交給荒蕪之地的里格弗茲。",
    [706] = "為西格魯·鐵斧拿到一顆黑色幼龍之心。",
    [707] = "和洛克莫丹鐵環挖掘場的勘察員基恩薩·鐵環談話。",
    [709] = "把雷烏納石板帶給迷失者塞爾杜林。",
    [710] = "收集10塊小石頭碎塊，把它們交給荒蕪之地的魯特維爾·沃拉圖斯。",
    [711] = "收集3塊大石片，把它們交給荒蕪之地的魯特維爾·沃拉圖斯。",
    [712] = "收集5個石縛護腕，把它們交給荒蕪之地的魯特維爾·沃拉圖斯。",
    [713] = "找到冰霜之油，把它交給荒蕪之地的魯特維爾·沃拉圖斯。",
