    [715] = "為荒蕪之地的盧希恩·槍穗找到一瓶隱形藥水和一瓶治療藥水。",
    [716] = "給荒蕪之地的盧希恩·槍穗帶去一些青銅花紋護腕。",
    [717] = "用大地印章啟動鑽石柱、蛋白石柱和紫水晶石柱並拿到三顆符石。 把符石放在大地封印上，釋放黑龍布萊克拉席和赫瑪圖斯。 殺了這兩條黑龍，把布萊克拉席的鎖鏈、赫瑪圖斯的鎖鏈和大地印章交給加瑞克。",
    [718] = "幫西格魯·鐵斧找回補給箱。",
    [719] = "找到雷杜爾的好運鋤，把它交給鐵趾挖掘場南邊的勘察員雷杜爾。",
    [720] = "找到勘察員雷杜爾，告訴他鐵趾格雷茲還活著。",
    [721] = "在奧達曼找到鐵趾格雷茲。",
    [722] = "找到鐵趾的護符，把它交給奧達曼的鐵趾。",
    [723] = "把鐵趾的護符交給荒蕪之地的勘察員雷杜恩。",
    [724] = "把鐵趾的護符交給鐵爐堡的史學家卡尼克。",
    [725] = "找到顧問貝爾格拉姆，把便箋交給他。",
    [726] = "和史學家卡尼克談話。",
    [727] = "把戰錘印章交給鐵爐堡的葛利·硬骨。",
    [728] = "把戰錘印章交給幽暗城的看守者貝爾杜加。",
    [729] = "到南邊去一趟，看看勘察員雷姆塔維爾現在處境如何。",
    [730] = "到奧伯丁去尋找矮人挖掘隊的線索。",
    [731] = "在勘察員雷姆塔維爾搜尋神秘化石的時候保護他，然後回到奧伯丁的考古學家霍莉那裡。",
    [732] = "幫加瑞克取回大地印章。",
    [733] = "幫西格魯收集7塊金屬碎片。",
    [734] = "和荒蕪之地的盧希恩·槍穗談話。",
    [735] = "找齊葛利·硬骨的便箋上列出的東西，然後把它們交給鐵爐堡的葛利·硬骨。",
    [736] = "把貝爾杜加的便箋上列出的東西帶給幽暗城的看守者貝爾杜加。",
    [737] = "把雅格因的筆記交給塞爾杜林。",
    [738] = "找到阿戈莫德。",
    [739] = "幹掉殺害阿戈莫德的兇手：莫達洛克。 順便殺掉12個石窟斷骨者。 然後向洛克莫丹的勘察員基恩薩·鐵環報告。",
    [741] = "把神秘的化石交給達納蘇斯的首席考古學家杜瑟·灰鬚。",
    [742] = "與梣谷碎木崗哨的塞娜尼·雷心談話。",
    [743] = "給血蹄村的盧爾·鷹爪帶回8隻風怒鷹身人的爪子。",
    [744] = "收集6根碧藍色的羽毛和6根古銅色的羽毛，把它們交給雷霆崖的伊恩·鷹爪。",
    [745] = "殺死10個白鬃製革工、8個白鬃剝皮工和5個白鬃偷獵者，然後回到血蹄村向貝恩·血蹄覆命。",
    [746] = "收集5個勘察員的鋤頭。 在鐵匠鋪砸碎這些勘察員的鋤頭。 把5件損壞的工具交給血蹄村的貝恩·血蹄。",
    [747] = "納拉其營地的格盧爾·鷹風要求你帶給他7片平原陸行鳥的羽毛和7塊平原陸行鳥肉。",
    [748] = "收集6隻草原狼的爪子和4隻平原陸行鳥的爪子，把它們交給血蹄村的莫爾·雷角。",
    [749] = "摩林·雲行者要你去查看被破壞的貨車附近的儲備箱裡有什麼東西。",
    [750] = "納拉其營地的格盧爾·鷹風要求你帶給他10張山獅皮。",
    [751] = "把風險投資公司文件交給血蹄村附近的摩林·雲行者。",
    [752] = "鷹風酋長要求你去納拉其營地東南方的水井處尋找他的母親。",
