    [754] = "用冬蹄淨化圖騰完成冬蹄水井的淨化，然後回來見莫爾·雷角。",
    [755] = "找到居住在納拉其營地正南方山中的灰舌先知。",
    [756] = "收集6個草原捕食者的爪子和6個平原獅的爪子，把它們帶給莫爾·雷角。",
    [757] = "殺掉刺刃峽谷的刺背野豬人並帶回12條刺背腰帶，把它們交給納拉其營地的鷹風酋長。",
    [758] = "在雷角水井使用雷角淨化圖騰，然後回來見莫爾。",
    [759] = "收集8顆草原狼前鋒的牙齒，把它們交給血蹄村的莫爾·雷角。",
    [760] = "在蠻鬃水井使用蠻鬃淨化圖騰，然後回來見莫爾·雷角。",
    [761] = "收集8根猛鷲的羽毛，把它們帶給血蹄村的哈肯·風之圖騰。",
    [762] = "殺死苦痛堡壘中的因弗努斯大使，把證明他已死亡的信物交給鐵爐堡的顧問貝爾格拉姆。",
    [763] = "順著離開納拉其營地的路將鷹風圖騰帶給血蹄村的貝恩·血蹄。",
