    [766] = "收集草原狼的心臟、平原獅的腿骨、平原陸行鳥的鱗片和猛鷲的胃各一份，把它們交給血蹄村的茂爾·祈雨。",
    [767] = "和血蹄村的札爾曼·雙月談話。",
    [768] = "收集12塊輕皮，把它們交給雷霆崖的維爾倫·陸行者。",
    [769] = "帶去4塊輕皮和4條粗線給雷霆崖的維爾倫·陸行者。",
    [770] = "去打聽打聽誰聽說過鬼嚎。",
    [771] = "收集2塊水井石和2個琥珀顆粒，把它們帶給血蹄村的札爾曼·雙月。",
    [772] = "在血蹄村的部族之火前將先知之水喝下，當幻象出現之後跟隨它。",
    [773] = "到雷霆崖東邊的赤色石去和先祖之魂談話。",
    [775] = "和雷霆崖的凱恩·血蹄談話。",
    [776] = "雷霆崖的凱恩·血蹄要你將阿蘭其亞的角帶給他。",
    [777] = "把5號齒輪交給魯特維爾·沃拉圖斯。",
    [778] = "擊敗法姆雷托守護者，並將魯特維爾的元素禁錮鐐銬交還給魯特維爾。",
