    [788] = "殺掉10隻雜斑野豬，然後向大獸穴裡的高內克報告。",
    [789] = "帶10根工蠍的尾巴給大獸穴中的高內克。",
    [790] = "殺死薩科斯並將它的爪子帶回去交給哈納祖。",
    [791] = "剃刀嶺瞭望塔中的弗恩·凝眉想要8塊帆布腳料。",
