    [973] = "把伊克魯德·瑪格蘇爾之書交給邁斯特拉崗哨的淨化者德爾葛蘭。",
    [974] = "安戈洛環形山的克拉蘭克要你去找到火羽山中溫度最高的地方。 當你找到一個看起來很熱的地方時，就右鍵點擊溫度計來測量當地的溫度。不斷嘗試，直到你找到溫度最高的地方。",
    [975] = "與巫醫瑪艾里再次談話，然後拿到好運符。",
    [976] = "護送費羅·艾隆漢安全地穿越梣谷森林，再與邁斯特拉崗哨的淨化者德爾葛蘭談話。",
    [977] = "為永望鎮的烏米收集2支完美的雪人角。",
    [978] = "從冬泉谷收集10片月光羽毛，然後將它們帶給魯瑟蘭村的艾瑞拉斯·琥珀。",
    [979] = "在冬泉谷找到蘭莎爾拉。",
    [980] = "到冬泉谷去和多諾瓦·雪山談話。",
    [981] = "和邁斯特拉崗哨的淨化者德爾葛蘭談話。",
    [982] = "找到銀色清晨號的帶鎖箱和迷霧之紗號的帶鎖箱，把它們交給奧伯丁的高爾博多‧鋼手。你可以在村莊北部遇難的船隻裡找到這兩個箱子。",
    [983] = "收集6隻蟹腿，把它們放進傳聲盒827號。",
    [984] = "在黑海岸找到一處墮落熊怪的營地，然後向奧伯丁的特倫希斯報告。",
    [985] = "殺掉8個黑木探路者和5個黑木風語者，然後回到奧伯丁向特倫希斯彙報。",
    [986] = "收集5張優質月夜猛虎毛皮，把它們交給奧伯丁的特倫希斯。",
    [990] = "在梣谷中找到萊恩·狼行者。",
    [991] = "在梣谷找到泰洛尼斯。",
    [992] = "用未使用的尋水器在流沙崗哨旁邊的池中採集水樣。一旦你收集到水樣，就儘快將其交給加基森的高級勘探員菲茲杜瑟。",
    [993] = "找到沃科爾。",
    [994] = "保護沃科爾離開，然後去和奧伯丁的特倫希斯談話。",
    [995] = "離開熊怪洞穴，然後去見奧伯丁的特倫希斯。",
    [997] = "把稀土交給奧拉密斯湖畔的德納蘭。",
    [1000] = "與雷霆崖長者高地的大德魯伊哈繆爾·符文圖騰談一談關於議會號召部落成員探索卡林多大陸的事情。",
    [1001] = "從位於傳聲盒411號附近的深海中收集3顆黑海岸蛇頸龍的眼球。",
    [1002] = "收集6顆月夜猛虎的牙齒，把它們放進傳聲盒323號。",
    [1003] = "收集4塊灰色頭皮，然後把它們放在傳聲盒525號中。",
    [1004] = "與雷霆崖長者高地的大德魯伊哈繆爾·符文圖騰談一談關於議會號召部落成員探索卡林多大陸的事情。",
    [1007] = "把遠古雕像交給塔爾倫，他的營地就在左拉姆海岸附近。",
    [1008] = "收集20顆怒尾納迦的頭顱，把它們交給阿斯特蘭納的辛德瑞爾。",
    [1009] = "找到左拉姆之戒，把它交給左拉姆海岸邊的塔爾倫。",
    [1010] = "收集5份巴斯蘭的頭髮，把它們帶給梣谷的奧雷迪爾·闊葉。",
    [1011] = "找到一瓶病毒，把它交給林歌神殿的凱尼斯·靜風。",
    [1012] = "殺死這些德魯伊：坦尼爾·黑木、尤希爾·喚月和瑪沃裡斯·裂雲，然後向林歌神殿的凱尼斯·靜風覆命。",
    [1013] = "把烏爾之書拿給幽暗城鍊金區裡的看守者貝爾杜加。",
    [1014] = "殺死阿魯高，把他的頭帶給瑟伯切爾的達拉爾·道恩維沃爾。",
    [1015] = "與達納蘇斯塞納里奧區的大德魯伊范達爾·鹿盔談談關於議會號召聯盟成員探索卡林多大陸的事情。",
    [1016] = "收集5個完整的元素護腕，並對它們使用占卜卷軸。然後把使用過的占卜卷軸帶給銀風避難所的哨兵維爾莉妮·星墜。",
    [1017] = "殺掉薩瑞魯斯·法伯尼，把他的首級交給銀風避難所的哨兵維爾莉妮·星墜。",
    [1018] = "與雷霆崖長者高地的大德魯伊哈繆爾·符文圖騰談一談關於議會號召部落成員探索卡林多大陸的事情。",
    [1019] = "與達納蘇斯塞納里奧區的大德魯范達爾·鹿盔談一談關於議會號召聯盟成員探索卡林多大陸的事情。",
    [1020] = "把奧雷迪爾的藥劑交給阿斯特蘭納的皮爾圖拉斯·懷特姆恩。",
    [1021] = "到薩維亞去找到安妮莉亞。",
    [1022] = "到狼嚎谷去，研究一下麥爾莎迪絲之書，然後向艾森娜神殿的哨兵梅麗瑞亞·霜影覆命。",
    [1023] = "找到發光的寶石，連同泰洛尼斯的日記一起交給阿斯特蘭納的萊恩·狼行者。",
    [1024] = "在東北方的月井旁找到莎爾蒂恩。",
    [1025] = "殺掉汙林族的1個汙林守衛者、2個汙林巨熊、10個汙林薩滿和12個汙林戰士，然後回去找阿斯特蘭納的萊恩·狼行者。",
    [1026] = "找到木製鑰匙和一段達圖爾的魔棒，然後回到月井的莎爾蒂恩那裡。",
    [1027] = "找到達圖爾的魔棒的最後一段，然後回到月井旁的莎爾蒂恩那裡。",
    [1028] = "找到隱藏的神殿並給達圖爾的魔棒重新注入魔力。",
    [1029] = "回到阿斯特蘭納的萊恩·狼行者那裡。",
    [1030] = "找到一個尚未墮落的熊怪，利用達圖爾的變形魔棒的能力與其交談。",
    [1031] = "殺掉加薩里斯，把塞納留斯的樹枝交給艾森娜神殿的伊莉亞娜。",
    [1032] = "收集16支薩特的角，把它們交給艾森娜神殿的伊莉亞娜。",
    [1033] = "找到月神之淚，把它交給阿斯特蘭納的皮爾圖拉斯·懷特姆恩。",
    [1034] = "收集5份星塵，把它們交給梣谷的皮爾圖拉斯·懷特姆恩。",
    [1035] = "從沼澤獸智者那裡取回一枚隕落的月亮石，並把它帶給阿斯特蘭納的皮爾圖拉斯·懷特姆恩。",
    [1036] = "登上停泊在荊棘谷海岸邊的紅霧號，與船裏的艦隊指揮官菲爾拉倫談壹談。",
    [1037] = "在達納蘇斯的公正之廳與塞恩提爾·刃紋談話。",
    [1038] = "在維琳德的箱子裡搜尋她的日記，把日記連同鑰匙一起交給達納蘇斯的塞恩提爾·刃紋。",
    [1039] = "和棘齒城的碼頭管理員迪茲維格談話。",
    [1040] = "坐船去藏寶海灣，和旅行者拉茲戈特談話。",
    [1041] = "與夜色鎮的書記員達爾塔談話。",
    [1042] = "去和夜色鎮的喬納森·卡爾文談談。",
    [1043] = "去找關於月神鐮刀的消息，然後回到夜色鎮見喬納森·卡爾文。",
    [1044] = "回到達納蘇斯去見塞恩提爾·刃紋。",
    [1045] = "殺死4個血牙保鏢，並為密斯特拉湖附近的克羅格取回蘭恩‧血牙的顱骨。",
    [1046] = "把蘭恩·血牙的顱骨和達圖爾的變形魔棒交給阿斯特蘭納的萊恩·狼行者。",
    [1047] = "與達納蘇斯塞納里奧區的大德魯范達爾·鹿盔談一談關於議會號召聯盟成員探索卡林多大陸的事情。",
    [1048] = "殺掉高階審判官懷特邁恩、血色十字軍指揮官莫格萊尼、血色十字軍勇士赫洛德和馴犬者洛克希，然後向幽暗城的瓦里瑪薩斯回報。",
    [1049] = "從血色修道院裡找到《墮落者綱要》，把它交給雷霆崖的聖者圖希克。",
    [1050] = "從修道院拿回《泰坦神話》，把它交給鐵爐堡的圖書館員麥伊·蒼塵。",
    [1051] = "把沃瑞爾·森加斯的結婚戒指還給塔倫米爾的莫尼卡·森古特斯。",
    [1052] = "將安東修士的表彰信帶給南海鎮的虔誠的萊雷恩。",
    [1053] = "殺死高階審判官懷特邁恩，血色十字軍指揮官莫格萊尼，十字軍的勇士赫洛德和馴犬者洛克希並向南海鎮的萊雷恩覆命。",
    [1054] = "把達爾·血爪的顱骨交給阿斯特蘭納的萊恩·狼行者。",
    [1055] = "回到月井旁的莎爾蒂恩那裡。",
    [1056] = "拜訪石爪峰的看守者奧巴格姆。",
    [1057] = "石爪峰的守衛者奧巴格姆要求你殺死6個血怒鷹身人、6個血怒伏擊者、6個血怒殺戮者和6個血怒遊蕩者。",
    [1058] = "瑪拉卡金的巫醫金吉爾需要5瓶石爪苔液、5根夜行虎鬚、30顆巨角鹿的眼球和1塊靈龍的鱗片。",
    [1059] = "在千針石林與菲拉斯的邊境上找到法芬德爾。",
    [1060] = "把達索克的親筆信交給金吉爾，他住在石爪山的洞穴中。",
    [1061] = "找到石爪山的希雷斯·碎石並和她談話。",
    [1062] = "殺死1５個風險投資公司的伐木工人，然後回去找石爪山與貧瘠之地交界處的希雷斯·碎石。",
    [1063] = "與雷霆崖的瑪加薩談話。",
    [1064] = "和預見之池的藥劑師札瑪談話。",
    [1065] = "把札瑪的便箋帶給塔倫米爾的林度恩。",
    [1066] = "為塔倫米爾的藥劑師林度恩收集5瓶無辜者之血。",
    [1067] = "把林度恩的毒藥交給雷霆崖的藥劑師札瑪。",
    [1068] = "殺死伐木機XT:4和XT:9，然後向石爪山與貧瘠之地交界處的希雷斯·碎石覆命。",
    [1069] = "收集15顆深苔蜘蛛的卵，把它們交給棘齒城的麥伯克·米希瑞克斯。",
    [1070] = "找到位於石爪山脈狂風峭壁旁的山谷中的凱拉·影矛。",
    [1071] = "殺掉10名風險投資公司樵夫和10名風險投資公司砍樹工，然後向石爪山的加克希姆·塵鏈覆命。",
    [1072] = "與鐵爐堡的洛瑪克·鏈帶談話。",
    [1073] = "給鐵爐堡的洛瑪克·鏈帶拿去4瓶初級法力藥水和2瓶初級堅韌藥劑。",
    [1074] = "將硝酸甘油炸藥帶回石爪山，交給加克希姆·塵鏈。",
    [1075] = "找到暴風城的科林·馬倫。",
    [1076] = "將塵魔的殘骸帶回給暴風城的科林·瑪林。",
    [1077] = "將通訊卷軸交給石爪山的加克希姆·塵鏈。",
    [1078] = "給暴風城的科林·瑪倫帶回8片水晶鱗片。",
    [1079] = "將風險投資公司工程計畫書從峭壁湖的伐木場中偷出來。",
    [1080] = "將風險投資公司函件從峭壁湖最東面的狂風礦洞中偷出來。",
    [1081] = "到達納蘇斯去找到泰蘭妲·語風。",
    [1082] = "向梣谷的哨兵塞恩希爾覆命。",
    [1083] = "從焦炭谷中的任意火元素身上收集8個悶燒餘燼，把它們交給石爪山的凱拉·影矛。",
    [1084] = "給石爪山的凱拉·影矛帶回一塊被腐蝕的彈片。",
    [1085] = "與加克希姆談話。",
    [1086] = "把劇毒糧草帶到風險投資公司的空港去，然後向藥劑師札瑪覆命。",
    [1087] = "為石爪峰附近的布萊林·火拳殺死4名塞納留斯的兒子，4名塞納留斯的女兒以及4名塞納里奧植物學家。",
    [1088] = "將奧達努斯的頭顱帶給石爪峰的布萊林·火拳。",
    [1089] = "到石爪峰上的洞穴中去，使用守門人的鑰匙拿到能打開石爪峰頂的猛禽洞穴儲藏室的物品。",
    [1090] = "在匹茲尼克完成開採之後拿到神秘礦石。",
    [1091] = "將風險投資公司函件帶給凱拉·影矛。",
    [1092] = "將未經化驗的礦石送到石爪山的菲茲克斯那裡。",
    [1093] = "為石爪山的菲茲克斯偷來超級收割機6000型的設計圖。",
    [1094] = "將密封的信封交給貧瘠之地的斯布特瓦夫。",
    [1095] = "把新的指令帶給石爪山的菲茲克斯。",
    [1096] = "將格雷蘇的機械臂帶給石爪山脈的菲茲克斯。",
    [1097] = "與格瑞曼德·艾爾默談話。",
    [1098] = "找尋亡靈哨兵阿達曼和亡靈哨兵文森。",
    [1100] = "閱讀亨里格·獨眉的日記。",
    [1101] = "把卡爾加·刺肋的大獎章帶給薩蘭納爾的法芬德爾。",
    [1102] = "把卡爾加·刺肋的心臟交給雷霆崖的奧爾德·石塔。",
    [1103] = "如果妳沒能與水之魂交談，就給銀松森林的提夫·摩杜恩再拿去壹瓶水之靈契。",
    [1104] = "為閃光平原的菲茲爾·銅栓帶去6份含鹽的蠍毒。",
    [1105] = "收集9塊硬化龜殼，把它們交給閃光平原的維茲爾·銅栓。",
    [1106] = "把菲茲爾·銅栓的信帶給荒蕪之地的流放者馬特克。",
    [1107] = "給閃光平原上的瑞茲爾·銅栓帶去10片堅硬的尾鰭。",
    [1108] = "收集10塊精鐵碎片，把它們交給荒蕪之地的流放者馬特克。",
    [1109] = "幫幽暗城的大藥劑師法拉尼爾帶回一堆沼澤蝙蝠的糞便。",
    [1110] = "收集30個火箭車零件，把它們交給閃光平原的克拉維爾·濃須。",
    [1111] = "把克拉維爾的零件訂單交給棘齒城的碼頭管理員迪茲維格。",
    [1112] = "把克拉維爾的零件交給閃光平原的克拉維爾·濃鬚。",
    [1113] = "幽暗城的大藥劑師法拉尼爾需要20顆狂熱之心。",
    [1114] = "把精密的賽車零件交給閃光平原的菲茲爾·銅栓。",
    [1115] = "和藏寶海灣的克拉茲克談話。",
    [1116] = "為藏寶海灣的克拉茲克收集10份夢境之塵。",
    [1117] = "把哥布林的謠言帶給閃光平原的克拉維爾·濃須。",
    [1118] = "把克拉維爾的計畫書交給藏寶海灣的克蘭克·菲茲巴布。",
    [1119] = "把蠢人酒交給閃光平原的克拉維爾。",
    [1120] = "把蠢人酒帶給地精車隊老闆。",
    [1121] = "把蠢人酒交給哥布林車隊老闆。",
    [1122] = "把蠢人酒的試驗報告交給藏寶海灣的克蘭克·菲茲巴布。",
    [1123] = "與月光林地永夜港的拉比恩·薩圖納談一談。月光林地在費伍德森林和冬泉谷之間，可以從木喉要塞中的一條通道抵達那裡。",
    [1124] = "在希利蘇斯的勇士之墓附近找萊耶·星擊談談，把拉比恩的信交給他。",
