    [1787] = "從石碑湖小島上的迪菲亞巫師手中拿到迪菲亞手稿，把它交給暴風城的傑生·坦諾姆。",
    [1788] = "與暴風城的達索瑞恩·拉爾談話。",
    [1791] = "和『觀風者』巴斯拉談話。",
    [1795] = "召喚地獄獵犬並打敗它，然後把陰謀之書交給棘齒城的斯坦哈德·法爾杉。",
    [1796] = "將奧法之袍交給貧瘠之地的梅納拉·沃倫德。",
    [1798] = "與貧瘠之地的斯坦哈德·法爾杉談話。",
    [1799] = "在棘齒城外的塔里與梅納拉的侍僧們談話，選擇自己修行的方式。 然後給塵泥沼澤的塔貝薩帶去一顆地獄火珠。",
    [1801] = "和幽暗城的約拉·安尼森談話。",
    [1802] = "為鐵爐堡的克羅姆·粗臂找回發黴的書籍和破損的手稿。",
    [1803] = "給幽暗城的約拉·安尼森帶回發黴的書籍和破損的手稿。",
    [1804] = "將翻修過的書籍和3根導能魔棒交給棘齒城的斯坦哈德·法爾杉。",
    [1805] = "將翻修過的書籍和3根導能魔棒交給棘齒城的斯坦哈德·法爾杉。",
    [1806] = "等待喬丹·斯迪威爾為你鑄造武器。",
    [1818] = "和布瑞爾的亡靈衛兵迪林格爾談壹談。",
    [1819] = "殺死切割者奧拉格，然後和亡靈衛兵迪林格爾談壹談。",
    [1820] = "和庫勒曼·法席恩談壹談。",
    [1821] = "把阿加曼德家傳長劍、阿加曼德家傳戰斧、阿加曼德家傳釘錘和阿加曼德家傳匕首交給庫勒曼·法席恩。",
    [1823] = "和魯迦·狂暴圖騰談話。",
    [1824] = "收集5根顫抖的觸角，把它們帶給貧瘠之地陶拉祖營地的魯迦。",
    [1825] = "與貧瘠之地的索恩格瑞姆·火眼談話。",
    [1838] = "為索恩格瑞姆收集15根煙霧鐵錠、10份藍銅粉、10塊鐵錠和1瓶燃素。",
    [1839] = "與杜隆塔爾的尤拉萊克談壹談。",
    [1840] = "和雷霆崖的奧姆·石蹄談壹談。",
    [1841] = "與幽暗城的維羅拉·奈特雷談壹談。",
    [1842] = "收集7隻完整的薩特之蹄，把它們交給杜洛塔森金村的尤拉萊克。",
    [1844] = "把光滑的奇美拉角交給雷霆崖的歐姆·石蹄。",
    [1846] = "給幽暗城的維羅拉·奈特雷帶去12根結實的龍喉脛骨。",
    [1858] = "偷來塔贊的鑰匙，用它打開他的背包，然後將裏面的物品交給奧格瑞瑪暗影裂口的瑟祖克。",
    [1859] = "到奧格瑞瑪的暗影裂口和瑟祖克談談。",
    [1860] = "和暴風城的詹妮亞·坎農談壹談。",
    [1861] = "把一份明鏡湖水的樣本交給暴風城的詹妮亞·坎農。",
    [1879] = "和鐵爐堡的彬克談話。",
    [1880] = "幫彬克找回她的法師文檔記憶體。",
    [1881] = "和安娜斯塔西婭·哈特威爾談壹談。",
    [1882] = "將巴尼爾金魚草交給幽暗城法師區的安娜斯塔西婭·哈特威爾。",
    [1883] = "和安蘇瓦談話。",
    [1884] = "摧毀4個魂能骨堆，然後向森金村的安蘇瓦彙報。",
    [1885] = "與幽暗城盜賊區的米奈特·卡加德談話。",
    [1886] = "得到阿斯托的介紹信，並將其交給盜賊區的米奈特·卡加德。",
    [1898] = "與幽暗城的安德隆·甘特交談。",
    [1899] = "將阿斯托的的帳本交給幽暗城盜賊區的米奈特·卡加德。",
    [1918] = "將被污染的水球交給梣谷碎木崗哨的馬斯托克·維爾西斯。",
    [1919] = "和暴風城的詹妮亞·坎農談談。",
    [1920] = "從詹妮亞·坎農身後拿取一根顯形卷軸以及一盒封靈箱。將3個裝滿的封靈箱交給巫師聖殿裡的詹妮亞·坎農。",
    [1921] = "把10匹亞麻布和6顆充能裂隙寶石交給暴風城的威恩·拉爾森。",
    [1938] = "將《烏爾的暗影魔法研究論文》交給暴風城的高階巫師安多瑪斯。",
    [1939] = "和高階巫師安多瑪斯談話。",
    [1940] = "找到8束新鮮的蜘蛛絲，把它們交給暴風城的威恩·拉爾森。",
    [1943] = "和迪諾談壹談。",
    [1944] = "將克薩維亞水樣交給奧格瑪的迪諾。",
    [1945] = "給十字路口的基爾哈拉帶去12縷歡笑姐妹的頭發。",
    [1947] = "和塔貝薩談話。",
    [1948] = "將電能草莓和1顆翡翠交給塵泥沼澤的塔貝薩。",
    [1949] = "和閃光平原的大法師提爾斯談話。",
    [1950] = "找到提爾斯保險箱的解封咒語，然後向提爾斯覆命。",
    [1951] = "將《能量儀祭》交給塵泥沼澤的塔貝薩。",
    [1952] = "等塔貝薩的儀式完成後，和她談話。",
    [1953] = "和塔貝薩談話。",
    [1954] = "將一顆地獄火寶珠交給塵泥沼澤的塔貝薩。",
    [1955] = "殺死寶珠之魔，然後與塔貝薩談話。",
    [1956] = "找到一個黑曜石能量源，將其交給塵泥沼澤的塔貝薩。",
    [1957] = "在限定時間內殺死12只法力怒靈。",
    [1959] = "和安娜斯塔西婭·哈特威爾談話。",
    [1960] = "從安娜斯塔西婭·哈特威爾身後拿取一根顯形卷軸以及一盒封靈箱。將3個裝滿的封靈箱交給幽暗城的安娜斯塔西婭·哈特威爾。",
    [1961] = "把10塊亞麻布和6塊達拉然法力寶石帶給喬瑟夫·格里高利。",
    [1963] = "殺死塔贊，把他的背包帶給奧格瑞瑪暗影裂口的瑟祖克。",
    [1978] = "將安德隆的帳本交給幽暗城黑暗女王大廳裡的瓦里瑪薩斯。",
    [1998] = "殺掉芬維克·薩托斯，把他的頭顱交給幽暗城盜賊區的米奈特·卡加德。",
    [1999] = "找到達拉然形勢報告，把它交給幽暗城盜賊區的米奈特·卡加德。",
    [2038] = "找回賓格斯的裝備： $賓格斯的氣壓炸彈、賓格斯的扳手、賓格斯的榔頭和賓格斯的螺絲起子。",
    [2039] = "去洛克莫丹尋找賓格斯·布拉斯場海默。",
    [2040] = "從死亡礦坑中帶回小型高能發動機，將其帶給暴風城矮人區中的沉默的舒尼。",
    [2041] = "去暴風城和舒尼談話。",
    [2078] = "找到基爾卡克的大副——機械打手4100型，把他帶到基爾卡克那裡。",
    [2098] = "找到基爾卡可鑰匙的3段碎片，把它們交給基爾卡克·旋杆。",
    [2118] = "活捉一隻狂暴薊熊，把它帶到薩納瑞恩那裡。",
    [2138] = "到森林裡去殺掉20隻狂暴薊熊。",
    [2139] = "找到雌薊熊，然後殺掉它。",
    [2158] = "和獅王之傲旅店的旅店老闆法雷談話。",
    [2159] = "把藥草送到旅店老闆凱達米爾手中。",
    [2160] = "給卡拉諾斯的塔諾克·霜錘帶去一箱旅店補給品。",
    [2161] = "把烏克爾的貨物帶給剃刀嶺的旅館主人格羅斯克。",
    [2178] = "給急彎河的奧蘭達利亞·夜歌帶回5塊陸行鳥肉。",
    [2198] = "找到破碎的項鏈的來源，從而瞭解其潛在的價值。",
    [2199] = "給鐵爐堡的塔瓦斯德·基瑟爾帶去五塊銀錠。",
    [2200] = "去奧達曼尋找塔瓦斯的魔法項鏈，被殺的聖騎士是最後一個拿著它的人。",
    [2201] = "在奧達曼尋找紅寶石、藍寶石和黃寶石的下落。找到它們之後，通過塔瓦斯德給你的占卜之瓶和他進行聯繫。",
    [2202] = "收集12顆紫色蘑菇，把它們交給卡加斯的加卡爾。",
    [2203] = "用空的魔瓶吸收荒蕪之地的烈焰守護者的血液。裝滿所有瓶子之後，把它們交給卡加斯的加卡爾。",
    [2204] = "從奧達曼最強大的石人身上獲得能量源，然後將其交給鐵爐堡的塔瓦斯德。",
    [2205] = "把科瑞恩·塞爾留斯的包裹帶給暴風城兵營的馬迪亞斯·肖爾。",
    [2206] = "找到迪菲亞碼頭主管，從他那裡為馬迪亞斯·肖爾拿到迪菲亞船運時間表。",
    [2218] = "和鐵爐堡的霍夫丹·黑鬚談話。",
    [2238] = "在諾姆瑞根附近找到奧寧·雨錘。",
    [2239] = "把奧寧的報告交給鐵爐堡的霍夫丹。",
    [2240] = "閱讀巴爾洛戈的日記，探索密室，然後向鐵爐堡的勘察員塔伯斯·雷矛彙報。",
    [2241] = "把詹諾克的玫瑰帶給達納蘇斯的塞尤娜。",
    [2242] = "找到遠古的塞希爾，帶回任何妳可能發現的線索。",
    [2258] = "前往荒蕪之地取回加卡爾需要的試劑，然後回到卡加斯把試劑交給他。",
    [2259] = "與達那蘇斯的艾瑞安·影語取得聯系。",
    [2260] = "到暴風城去找到「剃刀」雷吉克。",
    [2278] = "和石頭守護者交談，從他那裡瞭解更多古代的知識。一旦你瞭解到了所有的內容之後就啟動諾甘農圓盤。",
    [2279] = "把迷你版的諾甘農圓盤帶到鐵爐堡的探險者協會去。",
    [2280] = "把迷你版的諾甘農圓盤帶到雷霆崖的賢者那裡。",
    [2281] = "到赤脊山的湖畔鎮去和盧修斯談話。",
    [2282] = "打開盧修斯的箱子，拿到偷竊技能證明物，然後把它歸還給湖畔鎮的盧修斯。",
    [2283] = "在奧達曼挖掘場中尋找一條珍貴的項鏈，然後將其交給奧格瑪的德蘭·杜佛斯。項鏈有可能已經損壞。",
    [2284] = "在奧達曼裡找尋寶石的線索。",
    [2298] = "到暴風城裡去找到「剃刀」雷吉克。",
    [2299] = "到鐵爐堡去和霍夫丹·黑須談壹談。",
    [2300] = "到暴風城去找到“剃刀”雷吉克。",
    [2318] = "在荒蕪之地的卡加斯哨所裡尋找一個可以幫你翻譯聖騎士日記的人。",
    [2338] = "將項鏈借給加卡爾。作為交換，他將幫你翻譯日記。",
    [2339] = "從奧達曼找回項鏈上的所有三塊寶石和能量源，然後把它們交給卡加斯的加卡爾。 紅寶石被藏在暗影矮人層層設防的地區。 黃寶石藏在穴居怪活動地區的一個甕中。 藍寶石在格瑞姆洛克手中，他是穴居怪的領袖。 能量源可能在奧達曼的某個最強生物的手中。",
    [2340] = "把項鏈和寶石送到奧格瑪的德蘭·杜佛斯那裡。",
    [2341] = "去卡加斯看看加卡爾是否成功了。",
    [2342] = "從奧達曼南部大廳的箱子中找到加勒特的家族寶藏，然後把它交給幽暗城的派翠克·加瑞特。",
    [2359] = "偷取迪菲亞塔樓鑰匙，進入迪菲亞塔樓，看看暮色森林的箱子裡到底有什麼東西，然後向暴風城的馬迪亞斯·肖爾彙報。",
    [2360] = "去西部荒野和密探吉爾妮談話。",
    [2378] = "前往奧格瑪，和暗影裂口那的申蘇爾談話。",
    [2379] = "與暗影裂口的贊杜沙談話。",
    [2380] = "在奧格瑞瑪城中的暗影裂口和申蘇爾談談。",
    [2381] = "把南海寶藏帶回給棘齒城的卑鄙的維尼克斯。不要忘了從維尼克斯的機械設備中拿取一份大餅乾和盜賊工具，你的任務需要使用這兩件東西。 如果你被任何奇怪的鸚鵡攻擊，就對它使用大餅乾！",
    [2382] = "到棘齒城去，與卑鄙的維尼克斯談話。",
    [2383] = "閱讀簡易羊皮紙，然後和試煉谷的弗郎恩談壹談。",
    [2398] = "在奧達曼找到巴爾洛戈。",
    [2418] = "給荒蕪之地的里格弗茲帶去8塊德提亞姆能量石和8塊安納洛姆能量石。",
    [2438] = "將翡翠攝夢符交給多蘭納爾的塔隆凱·捷根。",
    [2439] = "把你的報酬憑證交給鐵爐堡銀行的丁尼塔·石衣。",
    [2440] = "把報酬憑證交給雷霆崖的貝娜·冰蹄。",
    [2458] = "到淤泥沼澤北邊的風險投資公司塔樓去，聯繫碎手氏族的臥底費蘇勒。 看到塔樓之後，用信號槍發射信號，向工頭費蘇勒示意你已經到達。發出兩個閃光信號，然後使用碎手軍禮和工頭費蘇勒接頭。 注意，這些步驟必須依次進行，因為費蘇勒會攻擊並幹掉任何他無法識別的人。",
    [2459] = "多蘭納爾的塔隆凱·捷根要你殺掉7個瘤背秘法師，並找到遺失的珠寶。",
    [2460] = "對著申蘇爾練習碎手軍禮。",
    [2478] = "從工頭希里克斯那裡偷出希里克斯的塔樓鑰匙，進入塔樓，然後殺掉兩個變異風險投資公司工人、兩個風險投資公司巡邏員、兩個風險投資公司看守。 殺掉大工頭普茲克·加里維克斯，取了他的首級，然後打開加里維克斯的箱子，拿走贊吉爾的改良藥劑。將藥劑和加里維克斯的頭顱交給奧格瑪的申蘇爾，等候進一步的指示。",
    [2479] = "到希爾斯布萊德丘陵的塔倫米爾去，把贊吉爾的藥劑樣品交給瑟爾格·希諾特。 要去塔倫米爾，可以搭乘飛艇到幽暗城，然後沿著大路向南穿過銀松森林，直到希爾斯布萊德丘陵。跟著路標走！",
    [2480] = "等待瑟爾格·希諾特完成解藥。",
    [2498] = "雷利亞·綠樹要你和奧拉密斯湖的德納蘭談一談。",
    [2499] = "奧拉密斯湖的德納蘭要你去拿到奧肯斯古爾身上的巨大的瘤。",
    [2500] = "從荒蕪之地拿到加克所需的材料，然後回到塞爾薩瑪去見他。",
    [2501] = "在荒蕪之地的守護火龍身上使用空的魔瓶。將這些容器都盛滿之後，把它們交給塞爾薩瑪的加克。",
    [2518] = "達納蘇斯月神殿的女祭司艾茉拉讓你把薩絲拉的銀色絲囊交給她。",
    [2519] = "艾奎恩妮讓你和月神殿的女祭司艾茉拉談話。",
    [2520] = "女祭司艾茉拉讓你將薩絲拉的銀色絲囊放在大殿的噴泉處，然後回去見她。",
    [2521] = "在妳探索詛咒之地的旅程中，如果碰巧發現了無暇的德萊尼水晶球，就把它交給收藏家庫米沙。 妳要知道，這種寶石是整個艾澤拉斯最珍稀的水晶。詛咒之地上的任何壹種生物都有可能帶著壹顆無暇的德萊尼水晶球。 每找到壹顆，妳都會得到相應的酬勞。",
    [2522] = "找到壹顆無暇的德萊尼水晶球，把它交給收藏家庫米沙。",
