    [3519] = "與幽影谷的迪蘭妮亞·銀光談話。",
    [3520] = "到菲拉斯捕獲3個尖叫者的靈魂，然後回到熱砂港的葉金亞那裡。",
    [3521] = "在幽影谷中為迪蘭妮亞·月光收集7朵紫藍色蘑菇、4朵月牙百合花和一份樹林蜘蛛的膿液。",
    [3522] = "在5分鐘內將埃沃隆的解藥交給他。你可以從在北邊的洞穴旁找到埃沃隆。",
    [3523] = "要是你願意幫助貝尼斯特拉茲，再跟他談談，並將黑曜石還給他。",
    [3524] = "在奧伯丁南邊的海岸上尋找擱淺生物的駭骨，然後帶著骨頭回來找奧伯丁的溫尼斯·布萊葛。",
    [3525] = "護送貝尼斯特拉茲來到剃刀高地的野豬人神像處。 當他在執行儀式封印石像時保護他。",
    [3526] = "如果妳想要對地精工程學有更多了解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。",
    [3527] = "將第一塊和第二塊摩沙魯石板交給塔納利斯的葉基亞。",
    [3528] = "將裝滿的哈卡之卵交給塔納利斯的葉基亞。",
    [3541] = "將辛耶爾石板交給奧格瑪的傑斯雷蒙。",
    [3542] = "將瑪寇里石板交給幽暗城的安德隆·甘特。",
    [3561] = "將塞爾哈石板交給艾薩拉的大法師克希雷姆。",
    [3562] = "將瑪加薩的便箋交給艾薩拉的傑迪加。",
    [3563] = "將傑斯雷蒙的便箋交給艾薩拉的傑迪加。",
    [3564] = "將安德隆的字條交給艾薩拉的傑迪加。",
    [3565] = "將克希雷姆的便箋交給艾薩拉的傑迪加。",
    [3566] = "殺死黑衣拉索里克和奧比斯頓，帶著黑衣拉索里克的頭顱和奧比斯頓的心臟回到鐵爐堡的索里奧斯那裡。",
    [3568] = "在艾薩拉的埃達拉斯廢墟旁的海潮之池中收集4瓶水，然後回到藥劑師科雷那兒。",
    [3569] = "將科雷的藥劑交給幽暗城的瑟爾薩·風歌。",
    [3601] = "搜索薩拉斯營地，尋找基姆加爾的指南針，望遠鏡，燒雞和花生，然後將它們交還給艾薩拉的基姆加爾。",
    [3602] = "在艾薩拉南部收集20塊艾薩拉晶體。你可以使用地獄犬協助尋找一些隱藏的礦脈。 任務完成之後就回到洛拉姆斯那裡去。",
    [3621] = "把貨物交給荊棘谷的加爾文。",
    [3625] = "等待加爾文為你鍛造武器。",
    [3626] = "回到部落英雄的靈魂那裡。",
    [3627] = "殺掉毀滅者戈洛爾、瑟溫妮，以及大法師奧利斯塔。從他們到屍體上拿到戈洛爾的護符、瑟溫妮的護符和奧利斯塔的護符。 記住使用你的魔化艾薩拉水晶武器<name>削弱他們，否則他們是無法被殺死的——你必須小心謹慎地使用你的武器……",
    [3628] = "消滅汙染者拉瑟萊克，將汙染者之角交給部落英雄的靈魂。另外妳還要把汙染者防護結界交給他，這樣部落英雄的靈魂就可以消滅它，以避免它落入邪惡勢力之手。",
    [3629] = "如果你想要對哥布林工程學有更多瞭解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。",
    [3630] = "如果妳想要對侏儒工程學有更多了解，就把工程學教材交給鐵爐堡的工匠大師歐沃斯巴克。",
    [3631] = "與貧瘠之地棘齒城的斯坦哈德·法爾杉談話。",
    [3632] = "如果妳想要對侏儒工程學有更多了解，就把工程學教材交給鐵爐堡的工匠大師歐沃斯巴克。",
    [3633] = "如果妳想要對地精工程學有更多了解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。",
    [3634] = "如果妳想要對侏儒工程學有更多了解，就把工程學教材交給鐵爐堡的工匠大師歐沃斯巴克。",
    [3635] = "如果妳想要對侏儒工程學有更多了解，就把工程學教材交給藏寶海灣的奧格索普·奧布諾提斯。",
    [3636] = "大主教本尼迪塔斯要你去殺死剃刀高地的『寒冰使者』亞門納爾。",
    [3637] = "如果你想要對地精工程學有更多瞭解，就把工程學教材交給藏寶海灣的奧格索普·奧布諾提斯。",
    [3638] = "如果妳同意成為壹名地精技師，就右鍵點擊保密協議，然後再次和加基森的尼克斯·斯普克斯賓談壹談。",
    [3639] = "將20顆重磅鐵製炸彈、20顆實心炸彈和5隻自爆綿羊交給加基森的尼克斯·斯普克斯賓。",
    [3640] = "如果妳同意成為壹名侏儒技師，就右鍵點擊保密協議，然後再次和鐵爐堡的工匠大師歐沃斯巴克談壹談。",
    [3641] = "將6根秘銀管、1只精確瞄準鏡和2個高級假人交給鐵爐堡的工匠大師歐沃斯巴克。",
    [3642] = "如果妳同意成為壹名侏儒技師，就右鍵點擊保密協議，然後再次和藏寶海灣的奧格索普·奧布諾提斯談壹談。",
    [3643] = "將6根秘銀管、1只精確瞄準鏡和2個高級假人交給藏寶海灣的奧格索普·奧布諾提斯。",
    [3661] = "為魯瑟蘭村的艾瑞拉斯·琥珀收集15支梟獸羽毛。",
    [3681] = "與暴風城的達索瑞恩·拉爾談壹談。",
    [3701] = "到燃燒平原的索瑞森廢墟中去，從索瑞森聖物上搜集資訊。當你收集到足夠的資訊之後，就回到皇家歷史學家阿克瑟努斯那裡。",
    [3702] = "聽皇家歷史學家阿克瑟努斯講述索瑞森的歷史。",
    [3741] = "找到希拉蕊的項鏈，將其還給湖畔鎮的希拉蕊。",
    [3761] = "收集20份安戈洛的泥土，把它們交給雷霆崖的格德。",
    [3762] = "與雷霆崖的大德魯伊哈繆爾·符文圖騰談話。",
    [3763] = "與達納蘇斯的大德魯伊范達爾·鹿盔談話。",
    [3764] = "收集20份安戈洛的泥土，把它們交給達納蘇斯的耶納爾。",
    [3765] = "到奧伯丁的戈沙拉·夜語那兒去。",
    [3781] = "將大德魯伊的草種購買券交給達納蘇斯城塞納里奧區的瑪斯雷·馭熊者。",
    [3782] = "將草種購買券交給雷霆崖的巴珊娜·符文圖騰。",
    [3783] = "為永望鎮的烏米收集10張厚雪人毛皮。",
    [3784] = "與雷霆崖的大德魯伊哈繆爾·符文圖騰談話。",
    [3785] = "用一個常青袋、一包薩倫迪斯種子以及兩份安戈洛的泥土來嘗試種植晨光麥。 將10株晨光麥交給達納蘇斯的瑪斯雷·馭熊者。",
    [3786] = "用一個常青袋、一包薩倫迪斯種子以及兩份安戈洛的泥土來嘗試種植晨光麥。 將10株晨光麥交給雷霆崖的巴珊娜·符文圖騰。",
    [3787] = "與羽月要塞的奎恩提斯談話。",
    [3788] = "與羽月要塞的奎恩提斯談話。",
    [3789] = "與達納蘇斯的大德魯伊范達爾·鹿盔談話。",
    [3790] = "與達納蘇斯的大德魯伊范達爾·鹿盔談話。",
    [3791] = "將10株晨光麥交給羽月要塞的奎恩提斯。",
    [3801] = "如果你想要得到進入這座城市主城區的鑰匙，就去和弗蘭克羅恩·鑄鐵談話。",
    [3802] = "殺掉弗諾斯·達克維爾並拿回戰錘鐵膽。把鐵膽之錘拿到索瑞森神殿去，將其放在弗蘭克羅恩·鑄鐵的雕像上。",
    [3821] = "到燃燒平原去找到沙妮·長齒。",
    [3822] = "從克羅格盧爾手中拿回沙妮的鼻環，把它還給卡加斯的薩特拉克。搜尋巨槌石的每一處山洞和礦坑。",
    [3823] = "殺掉15個火腹巨魔法師、7個火腹巨魔和7個火腹蠻兵，完成任務之後向奧拉留斯報告。",
    [3824] = "找到戈泰什，他應該在巨槌石西面的某處。殺掉戈泰什並把他的頭顱交給燃燒平原的奧拉留斯。",
    [3825] = "把戈泰什的頭顱放在巨槌石的山頂上。找一塊軟土堆把串著頭顱的長矛插上去就可以了。",
    [3841] = "與千針石林的奎恩丁談話。",
    [3842] = "將2份次級堅韌藥劑交給千針石林的奎恩丁。",
    [3843] = "帶著這枚脆弱的小精龍卵去辛特蘭，與阿格納談一談，但是你一定要在它還有生命力的時候趕到，在蛋裡的小生命夭折之前，你只有1小時的時間。",
    [3844] = "在池塘附近查找與擱淺的小艇有關的線索。",
    [3845] = "查看袋子裡的東西，然後將它們交給物主。",
    [3861] = "找一些特殊的雞飼料，把它交給友好的小雞。當你找到小雞的時候，在餵食它之前對它做出高興的表情。（使用/cheer命令）",
    [3881] = "將食物箱和研究設備交給安戈洛環形山的威利德·馬紹爾。",
    [3882] = "將8根恐龍骨頭交給安戈洛環形山的斯巴克·尼米爾。",
    [3883] = "使用採集瓶從安戈洛環形山的某個格里什蟲巢的孵化室中收集一份巢穴側壁的樣本，在有懸掛著的蟲卵的房間裡收集樣本。 將蟲穴內壁樣本交給安戈洛環形山的霍萊伊·馬紹爾。",
    [3884] = "將日記還給安戈洛環形山中的威利德·馬紹爾。",
    [3901] = "殺掉12個斷骨骷髏，然後回到喪鐘鎮的暗影牧師薩維斯那裡。",
    [3902] = "在喪鐘鎮及臨近地區搜尋6件破爛裝備，把它們交給亡靈衛兵薩爾坦。",
    [3903] = "與米莉·奧斯沃斯談話。",
    [3904] = "收集8箱米莉的葡萄，把它們交給北郡修道院的米莉·奧斯沃斯。",
    [3905] = "將葡萄出貨單交給北郡修道院的尼爾斯修士。",
    [3906] = "到黑石山脈的採石場去幹掉征服者派隆，然後向桑德哈特回報。",
    [3907] = "進入黑石深淵並找到伊森迪奧斯。殺掉它，然後把你找到的資訊彙報給桑德哈特。",
    [3908] = "把林克的劍交給冬泉谷的多諾瓦·雪山。",
    [3909] = "去菲拉斯找格雷甘·山酒。從他那裡問到獲取視靈藥劑的方法，然後向冬泉谷的多諾瓦·雪山覆命。",
    [3912] = "在加基森鎮外的墓地中使用視靈藥劑，然後按照多諾瓦的指示找到加里楊。",
    [3913] = "復活，然後尋找加里楊讓你去找的那塊墓碑。",
    [3914] = "把林克的強化之劍交給安戈洛環形山的林克。",
    [3921] = "將損壞的主動式負載平衡器交給維妮·布特巴克。",
    [3922] = "把15個高強度齒輪交給貧瘠之地的維妮·布特巴克。",
    [3923] = "把破碎的主動式負載平衡器交給奧格瑪的雷里·格里斯高布。",
    [3924] = "把主動式負載平衡器說明書交給奧格瑪的雷里·格里斯高布。",
    [3941] = "到馬紹爾營地那裡的山洞中去找科琳。",
    [3942] = "到費伍德森林去找艾瑞丹·藍風。",
    [3961] = "把亞奎門塔斯的銀圖騰交給馬紹爾營地裡的林克。",
    [3962] = "到馬紹爾營地南邊的火羽山去。 找到火焰使者，並使用圖騰除掉它的防護光環。在擊敗它之後從洞中取得金色火焰。",
    [3981] = "在黑石深淵裡找到指揮官哥沙克。 在那幅草圖上畫著的是一個鐵欄後面的獸人，也許你應該到某個類似監獄的地方去找找看。",
    [3982] = "保護哥沙克。",
    [4001] = "與卡蘭·巨錘談一談，收集關於綁架公主鐵爐堡公主茉艾拉·銅鬚這一事件的情報。將情報回饋給奧格瑪城裡的索爾。 哥沙克提到過卡蘭被關在附近的某個牢房中。",
    [4002] = "如果你準備好要接受索爾所安排的任務，就去找他談話。",
    [4003] = "殺掉達格蘭·索瑞森大帝，然後將鐵爐堡公主茉艾拉·銅鬚從他的邪惡詛咒中拯救出來。",
    [4004] = "向索爾報告！",
    [4005] = "把阿奎爾之書、銀爪，還有鐵樹心帶到塔納利斯。 用這本書召喚亞奎門塔斯。 當你完成圖騰之後，把它帶給在馬紹爾營地的科琳。",
    [4021] = "將克羅姆札軍旗的碎片交給十字路口西邊的雷戈薩·死門。",
    [4022] = "向塞勒斯·薩雷芬圖斯展示你從維拉若克·溫布雷那裡得到的黑龍軍團之皮。",
    [4023] = "向塞勒斯·薩雷芬圖斯證明你的價值。 你感覺到塞勒斯似乎對你不屑一顧。",
    [4024] = "到黑石深淵去殺掉貝爾加。 你只知道這個巨型怪物住在黑石深淵的最深處。記住你要使用特殊的黑龍皮從貝爾加的屍體上採集烈焰精華。 將你採集到的烈焰精華交給塞勒斯·薩雷芬圖斯。",
    [4061] = "到燃燒平原去為塞朵拉·穆瓦丹尼收集10塊斷裂的元素碎片。 塞朵拉曾經說過，那裡的機械傀儡和元素生物是這種碎片的主要來源。",
    [4062] = "將元素碎片樣本交給魯特維爾·沃拉圖斯。 塞朵拉說魯特維爾就在東邊的一處營地裡。",
    [4063] = "找到並殺掉傀儡統帥阿格曼奇，將他的頭交給魯特維爾。你還需要從守衛著阿格曼奇的狂怒傀儡和戰鬥傀儡身上收集10塊完整的元素核心。",
    [4081] = "到黑石深淵去消滅那些邪惡的侵略者！ 指揮官高圖斯要你去殺死15個鐵怒衛士、10個鐵怒獄卒和5個鐵怒步兵。完成任務之後回去找他。",
    [4082] = "到黑石深淵去消滅那些邪惡的侵略者！ 高圖斯軍閥要你殺死10個鐵怒醫師,、10個鐵怒士兵和10個鐵怒軍官。完成任務之後回去向他覆命。",
    [4084] = "為費伍德森林的艾瑞丹·藍風收集11隻銀爪和1顆鐵樹之心。",
    [4101] = "收集15顆血琥珀，把它們交給費伍德森林的阿拉珊蒂絲·銀空。",
    [4102] = "收集15顆血琥珀，把它們交給費伍德森林的梅貝絲·河風。",
    [4120] = "菲拉斯莫沙徹營地的塔羅·刺蹄要你去費伍德森林殺掉12頭怒爪灰熊和12頭魔爪掠奪者。",
    [4121] = "押送你的囚犯格拉克·洛克魯布。穿過燃燒平原和黑石山脈，一直走到灼熱峽谷。 雷克斯洛特曾經告訴過你，他會讓他的人等在黑石山脈的另外一邊準備接收格拉克。 另外，你還要把瑟銀鐐銬一併還給雷克斯洛特。",
    [4122] = "到燃燒平原去找到格拉克·洛克魯布。你回憶起雷克斯洛特曾經提起過，格拉克應該是在一座大型的黑石要塞中。 當你找到格拉克·洛克魯布之後，用瑟銀鐐銬把他銬起來，然後將其帶回灼熱峽谷。雷克斯洛特會讓他的部下等在那裡接應你。",
    [4123] = "把山脈之心交給燃燒平原的麥克斯沃特·尤柏格林。",
    [4124] = "和羽月要塞的基恩諾·火花談話。",
    [4125] = "找到信差的小船，你應該在菲拉斯的南部海岸線上展開搜索。",
    [4126] = "把遺失的雷酒秘方帶給卡拉諾斯的拉格納·雷酒。",
    [4127] = "回到羽月要塞，給基恩諾·火花看看你找到的這把被丟棄的小刀。",
    [4128] = "和拉格納·雷酒談談。",
    [4129] = "把被丟棄的小刀交給羽月要塞的奎恩提斯。",
    [4130] = "和羽月要塞的基恩諾·火花談話。",
    [4131] = "在菲拉斯南部地區的木爪豺狼人營地裡尋找信差的下落或者信差的物品。",
    [4132] = "到黑石深淵去殺掉安格弗將軍！當任務完成之後向軍官高圖斯覆命。",
    [4133] = "與卡加斯的暗法師薇薇安·拉格雷談話。",
    [4134] = "把遺失的雷酒秘方交給卡加斯的薇薇安·拉格雷。",
    [4135] = "現在妳已經知道了拉斯卡爾的去向，那麽妳最好到痛苦深淵去尋找他，或者至少是他的屍體。根據便箋上的信息，那個地方應該在木爪豺狼人營地的南邊。",
    [4136] = "把雷布里的頭顱交給燃燒平原的尤卡·斯庫比格特。",
    [4141] = "從安戈洛環形山的血瓣花猛擊者和血瓣花掠奪者身上收集20個血瓣花，然後向莫爾金回復。",
    [4142] = "把血瓣花交給菲拉斯的格雷甘·山酒。",
    [4143] = "收集5份阿塔萊之霧的樣本，然後向安戈洛環形山的莫爾金覆命。",
    [4145] = "為馬紹爾營地裡的拉里安殺掉10個血瓣花鞭笞者和10個血瓣花捕獸者。",
    [4146] = "收集5份阿塔萊之霧的樣本，然後將它們送到馬紹爾營地的拉里安那裡。",
    [4147] = "到棘齒城去，在瑪爾馮·瑞文斯克的工坊裡找到他。",
    [4161] = "為多蘭納爾的札瑞恩收集7條小蜘蛛腿。",
    [4181] = "如果妳想要對地精工程學有更多了解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。",
    [4182] = "殺掉15條黑色小龍、10條黑色龍人和1條黑色幼龍。當你完成任務之後就向赫林迪斯·河角回報。",
    [4183] = "把赫林迪斯·河角的信交給湖畔鎮的所羅門鎮長。",
    [4184] = "到暴風城去把所羅門的求援信交給伯瓦爾·弗塔根公爵。 伯瓦爾在暴風要塞裡。",
    [4185] = "與女伯爵卡特拉娜·普瑞斯托談話，然後再與伯瓦爾·弗塔根公爵談話。",
    [4186] = "把伯瓦爾的命令交給湖畔鎮的所羅門鎮長。",
    [4201] = "將4份格羅姆之血、10塊巨型銀礦和裝滿水的娜瑪拉之瓶交給黑石深淵的娜瑪拉小姐。",
    [4223] = "和燃燒平原的麥克斯韋爾元帥談話。",
    [4224] = "和狼狽不堪的約翰談談來瞭解溫德索爾元帥的命運，然後回到麥克斯韋爾元帥那裡。 你想起麥克斯韋爾元帥說過他在一個北面的洞穴那裡。",
    [4241] = "到西北部的黑石山脈去，在黑石深淵中找到溫德索爾元帥的下落。 狼狽不堪的約翰曾告訴你說溫德索爾被關進了一個監獄。",
    [4242] = "把這個壞消息傳達給麥克斯韋爾元帥。",
    [4243] = "在安戈洛環形山找到A-Me 01。",
    [4244] = "找到一個秘銀外殼，然後回到安戈洛環形山的A-Me 01身邊。",
    [4245] = "將A-Me 01交給安戈洛環形山的卡爾納·雷塔維。",
    [4261] = "護送艾雷到灰谷，然後和灰谷東部的林歌神殿中的凱尼斯·靜風談壹談。",
    [4262] = "殺掉征服者派隆，然後向加琳達覆命。 加琳達告訴過你，派隆守在採礦場中，也許你應該去那裡找找。",
    [4263] = "在黑石深淵裡找到伊森迪奧斯，然後把他幹掉！",
    [4264] = "溫德索爾元帥也許會對妳手中的東西感興趣。畢竟，希望還沒有被完全扼殺。",
    [4265] = "將拉斯卡爾安全護送到祖卡什蟲巢外。 回到羽月要塞的基恩諾·火花那兒，告訴他拉斯卡爾還活著，且狀況良好。",
    [4266] = "與羽月要塞的珊蒂斯·羽月談話。",
    [4267] = "把拉斯卡爾的報告交給達納蘇斯的格拉希娜·靈風。",
    [4281] = "將未遞送的包裹交給薩蘭納爾驛站的法芬德爾。",
    [4282] = "找回溫德索爾元帥遺失的情報。 溫德索爾元帥確信那些情報在安格弗將軍和傀儡元帥阿格曼奇的手裡。",
    [4283] = "奧拉留斯想要50枚黑石徽章。在燃燒平原的獸人身上應該可以找到那些徽章。",
    [4284] = "收集紅色能量水晶、藍色能量水晶、黃色能量水晶和綠色能量水晶各7塊，把它們交給馬紹爾營地裡的科琳。",
    [4285] = "在安戈洛環形山找到北部水晶塔。",
    [4286] = "到黑石深淵去找到20個黑鐵挎包。當你完成任務之後，回到奧拉留斯那裡覆命。你認為黑石深淵裡的黑鐵矮人應該會有這些黑鐵挎包。",
    [4287] = "在安戈洛環形山找到東部水晶塔。",
    [4288] = "在安戈洛環形山找到西部水晶塔。",
    [4289] = "將2塊安戈洛猩猩的皮、2塊安戈洛大猩猩的皮和2塊安戈洛巨猩猩的皮交給安戈洛環形山入口處的托爾瓦·尋路者。",
    [4290] = "找到拉克維剛剛獵殺的動物的屍體，從屍體上偷取一塊蛇頸龍肉塊，然後回到安戈洛環形山的托爾瓦·尋路者那裡。",
    [4291] = "將2份暴掠龍資訊素交給安戈洛環形山入口附近的托爾瓦·尋路者。",
    [4292] = "使用托爾瓦的麻袋中的東西召喚拉克維並打敗它。將拉克維的頭顱交給安戈洛環形山入口處的托爾瓦·尋路者。",
    [4293] = "從費伍德的軟泥怪身上收集費伍德軟泥怪樣本，然後使用幽暗城的化學家弗雷身旁的測試設備來檢測你所收集的樣本中哪一份被腐化的程度最深。給化學家弗雷帶去5個被腐化的費伍德樣本。",
    [4294] = "從安戈洛環形山那裡任何泥漿怪身上收集安戈洛泥漿怪樣本。使用幽暗城的化學家弗雷身旁的測試儀器來檢驗你所採集到的樣本的純度。把5份純淨的安戈洛樣本送到化學家弗雷那裡去。",
    [4296] = "把石板拓文交給燃燒平原的麥克斯沃特·尤柏格林。",
    [4297] = "將5塊銀鬃捕獵者的肉交給辛特蘭的阿格納。",
    [4298] = "與辛特蘭的阿格納談話。",
    [4300] = "將8隻白色暴掠龍爪交給奧格瑪的傑斯雷蒙。",
    [4301] = "把尤爾查的毛皮交給安戈洛環形山入口處的托爾瓦·尋路者。",
    [4321] = "過一會再和科琳說話。",
    [4322] = "幫助溫德索爾元帥拿回他的裝備並救出他的朋友。當妳成功之後就回去向麥克斯韋爾元帥復命。",
    [4324] = "與燃燒平原的尤卡·斯庫比格特談話。",
    [4341] = "去黑石深淵找到卡蘭·巨錘。 國王提到卡蘭在那裡負責看守囚犯——也許你應該在監獄附近尋找他。",
    [4342] = "聽卡蘭·巨錘說他的故事。",
    [4361] = "回到鐵爐堡，把這個壞消息帶給國王麥格尼·銅鬚。",
    [4362] = "回到黑石深淵，從達格蘭·索瑞森大帝的魔掌中救出鐵爐堡公主茉艾拉·銅鬚。",
    [4363] = "回到鐵爐堡去，與國王麥格尼·銅鬚談話。",
    [4402] = "收集10個仙人掌果，把它們交給戈加爾。你記得他說可以在仙人掌上收集到這種果子。",
    [4421] = "殺掉11個碧火魔僕、9個碧火巡影者、9個碧火盜賊和薩瓦瑟拉斯。任務完成之後回到費伍德森林的艾瑞丹·藍風處覆命。",
    [4441] = "到達納蘇斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然後回到艾瑞丹那兒。",
    [4442] = "過一會兒再與艾瑞丹對話。",
    [4449] = "殺掉8個黑鐵地質學家，並將15塊絲綢交給灼熱峽谷裡那個被鎖在廁所中的矮人。",
    [4450] = "把古德斯迪爾的帳本和上面所列的物品交給塔納利斯的克林科·古德斯迪爾。",
    [4451] = "搜尋灼熱峽谷並找到一個可以使用這把格里塞特庫房鑰匙的地方。",
    [4485] = "與暴風城的達索瑞恩·拉爾談壹談。",
    [4486] = "與暴風城的達索瑞恩·拉爾談壹談。",
    [4487] = "與棘齒城的斯坦哈德·法爾杉談話。",
    [4488] = "與棘齒城的斯坦哈德·法爾杉談話。",
    [4489] = "與棘齒城的斯坦哈德·法爾杉談話。",
    [4490] = "與棘齒城的斯坦哈德·法爾杉談話，學習召喚地獄戰馬的能力。",
    [4491] = "把林格帶回馬紹爾營地的斯普拉格·弗勞克身邊。 如果林格暈倒了，就用斯普拉格的水壺讓他恢復。",
    [4492] = "在火羽山找到林格。",
    [4493] = "與加基森的煉金術士匹斯特蘇格談話。",
    [4494] = "與加基森的煉金術士匹斯特蘇格談話。",
    [4495] = "在北邊的洞穴附近找到埃沃隆。",
    [4496] = "帶一個Gorishi Scent Gland和5個安戈洛的泥土樣本給加基森的煉金術士匹斯特蘇格。",
    [4501] = "殺掉10隻翼手龍和15隻狂怒的翼手龍，然後向馬紹爾營地的斯普拉格·弗勞克報告。",
    [4502] = "到安戈洛環形山的火山中去，從那裡的元素身上收集9份安戈洛灰燼，把它們交給棘齒城的莉芙·雷茲菲克斯。",
    [4503] = "替馬紹爾營地的Shizzle收集8片Webbed Dimetrodon Scales和8片Webbed Pterrordax Scales。",
    [4504] = "幫加基森的特蘭雷克收集12塊極度粘稠的瀝青。",
    [4505] = "從碧火薩特的月井中收集一份被腐化的水的樣本，把它交給血毒崗哨的溫娜·哈薩德。",
    [4506] = "把溫娜的小貓帶到墮落的月井旁邊，把貓放出來，然後把它還給溫娜。 當你回到溫娜那裡之後，點擊貓就可以將它還給溫娜。",
    [4507] = "當格里什蜂后被召喚之後擊敗她。 帶格里什皇后的腦袋給加基森的匹斯特蘇格。",
    [4508] = "把匹斯特蘇格的安戈洛報告交給達納蘇斯的格拉希娜·靈風。",
    [4509] = "把匹斯特蘇格的安戈洛報告交給奧格瑪斯的基爾茲賓·鼓眼。",
    [4510] = "把銀行贈券交給達納蘇斯銀行的伊迪瑞娜。",
    [4511] = "把銀行贈券交給奧格瑪銀行的卡魯斯。",
    [4512] = "將6個被詛咒的軟泥怪樣本和6個被污染的軟泥怪樣本交給鐵爐堡的拉里斯·空輪。",
    [4513] = "將10個裝滿的純淨樣品瓶交給鐵爐堡的拉瑞斯·空輪。 如果你無法找到它們的話，試著到拉瑞斯那裡去再打聽一些線索。",
    [4521] = "費伍德森林的特盧爾·法貝恩要你去冬泉谷獵殺15頭狂怒的梟獸和15頭蓬毛梟獸。",
    [4542] = "把緊急信件交給亂風崗的峭壁衛兵圖林·長角。",
    [4581] = "把辛德瑞爾的便箋交給林歌神殿裡的凱尼斯·靜風。",
    [4621] = "殺死藏寶海灣的艦隊指揮官卡拉·海角和大財主裏維加茲，然後回到荊棘谷海邊的紅霧號上去，向艦隊指揮官菲爾拉倫復命。",
    [4641] = "與高內克談一談。卡爾圖克在你的地圖上標出了他的位置，並告訴你高內克居住在西邊的大獸穴中。",
    [4642] = "把一塊融合的軟泥怪樣本交給幽暗城的化學家弗雷。",
    [4681] = "在奧伯丁西面海水中的海龜骸骨那裡取回海龜殘骸，然後與奧伯丁的溫尼斯·布萊葛談話。",
    [4701] = "到黑石塔去摧毀那裡的座狼源頭。當你離開的時候，赫林迪斯喊出了一個名字：哈雷肯。這個詞就是獸人語中「座狼」的意思。",
    [4721] = "費伍德森林的特盧爾·法貝恩要你去冬泉谷獵殺10頭狂暴梟獸。",
    [4722] = "把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。",
    [4723] = "把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。",
    [4724] = "殺死血斧座狼的領袖，哈雷肯。",
    [4725] = "把有奇怪標記的箱子交給奧伯丁的溫尼斯·布萊葛。",
    [4726] = "將龍靈採集器900型和8份雛龍精華交給燃燒平原烈焰峰的丁奇·斯迪波爾。",
    [4727] = "把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。",
    [4728] = "把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。",
    [4729] = "到黑石塔去找到小血斧座狼。使用籠子來捕捉這些兇猛的小野獸，然後把籠中的小座狼交給基布雷爾。",
    [4730] = "把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。",
    [4731] = "把有奇怪標記的箱子交給奧伯丁的溫尼斯·布萊葛。",
    [4732] = "把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。",
    [4733] = "把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。",
    [4734] = "在孵化間對著某顆龍蛋使用龍蛋冷凍器初號機。",
    [4735] = "將電動采集模塊和8顆收集到的龍蛋交給燃燒平原烈焰峰的丁奇·斯迪波爾。",
    [4736] = "與貧瘠之地的梅納拉·沃倫德談壹談。",
    [4737] = "與貧瘠之地的梅納拉·沃倫德談話。",
    [4738] = "與貧瘠之地的梅納拉·沃倫德談話。",
    [4739] = "與貧瘠之地的梅納拉·沃倫德談壹談。",
    [4740] = "找到並殺死名為莫克迪普的魚人。它守護著位於奧伯丁南部海岸的魚人營地。 向奧伯丁的哨兵戈琳達·納希恩報告莫克迪普的死訊。",
    [4741] = "費伍德森林的特盧爾·法貝恩要你去冬泉谷獵殺13頭月光梟獸。",
    [4742] = "找到三塊命令寶石：燃棘寶鑽、尖石寶鑽和血斧寶鑽。把它們和原始晉升印章一起交給維埃蘭。 可能攜帶者三塊寶石的將軍是：燃棘氏族的指揮官沃恩、尖石氏族的歐莫克大王，以及血斧氏族的維姆薩拉克。",
    [4743] = "到塵泥沼澤中的巨龍沼澤去。找到上古老龍埃博斯塔夫，對他發起無情的攻擊，直到他的意誌被摧毀。 此時，妳必須盡快將未鑄造的晉升印章放在這條龍面前，並使用龍力寶珠控制他的軀體，強迫他將黑龍的烈焰噴向未鑄造的晉升印章！",
    [4761] = "與奧伯丁的桑迪斯·織風談話。",
    [4762] = "到奧伯丁的北面去，沿著壁泉河到達第一個瀑布處，從瀑布下的水潭中取出一份水樣。 將壁泉河水樣交給奧伯丁的桑迪斯·織風。",
    [4763] = "在空的淨化碗裡盛滿奧伯丁月井的井水。 在黑木熊怪的北部營地裡收集水果、堅果和榖物各一份。 將水和三種食物混合起來，放置在壁泉河附近的營火邊，這樣就會召來喚引誘熊怪墮落的薩特。 取回墮落護符，將它交給奧伯丁的桑迪斯·織風。",
    [4764] = "將末日扣環交給燃燒平原的瑪亞拉·布萊特文。",
    [4765] = "將瑞治維爾的箱子交給暴風城的雷明頓·瑞治維爾。",
    [4766] = "與燃燒平原的瑪亞拉·布萊特文談壹談。",
    [4767] = "將10顆風巢蠍尾獅的蛋交給亂風崗的艾魯。",
    [4768] = "將黑暗石板交給卡加斯的暗法師薇薇安·拉格雷。",
    [4769] = "與卡加斯的暗法師薇薇安·拉格雷談話。",
    [4770] = "護送波卡·雨山走出風巢，然後和白沙崗哨的莫特加·火鬃談話。",
    [4771] = "將黎明先鋒放在通靈學院的觀察室裡。打敗維克圖斯,然後回到貝蒂娜·比格辛克那裡去。",
    [4781] = "將一塊金錠交給荊棘谷的希茲克·古斯提。",
    [4782] = "回到貧瘠之地的梅納拉·沃倫德那裡。",
    [4783] = "將10瓶怨怒薩特之血和1塊次級地獄火石交給貧瘠之地的梅納拉·沃倫德。",
    [4784] = "將一些優質金線、2塊悶燒煤和一塊靈魂碎片交給貧瘠之地的梅納拉·沃倫德。",
    [4786] = "等待梅納拉·沃倫德織好披風，然後跟她談話。",
    [4787] = "將遠古之卵交給塔納利斯的葉基亞。",
    [4788] = "將第五塊和第六塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。",
    [4808] = "把丁奇的信交給菲諾克。",
    [4809] = "將8支完整的冰風奇美拉角交給菲諾克。",
    [4810] = "把菲諾克的包裹交給燃燒平原的丁奇·斯迪波爾。",
    [4811] = "到奧伯丁的東邊去，沿著黑海岸東部邊界的山脈尋找一顆巨大的紅色水晶，然後向奧伯丁的哨兵戈琳達·納希恩彙報你的發現。",
    [4812] = "在奧伯丁月井中把空水瓶裝滿，然後調查黑海岸東部山脈的紅水晶。",
    [4813] = "向奧伯丁的哨兵哨兵戈琳達·納希恩報告你的發現。",
    [4821] = "把異型卵交給亂風崗的哈加爾·雷蹄。",
    [4841] = "殺掉12個加拉克斥候、10個加拉克爭鬥者和6個加拉克逐風者，然後向亂風崗的峭壁衛兵圖林·長角覆命。",
    [4842] = "根據多諾瓦·雪山的指示行動，然後回到她那裡報告。",
    [4861] = "在冬泉谷的南部尋找加隆·石矛的被破壞的營帳，以及他的補給物資。",
    [4862] = "到黑石塔去為基布雷爾收集15枚尖塔蜘蛛卵。 聽說那些蜘蛛周圍有許多這樣的卵。",
    [4863] = "找到加隆·石矛的馬車。",
    [4864] = "從雪地中拾起加隆的補給物資，然後尋找加隆所說偷走護符的梟獸。 將加隆的補給物資和藍色羽毛護符交給冬泉谷的加隆·石矛。",
    [4865] = "向莫特加·火鬃彙報你的發現。",
    [4866] = "你可以在黑石塔的中心地帶找到煙網蛛后。與她戰鬥，讓她在你體內注入毒汁。如果你有能力的話，就殺死她吧。當你中毒之後，回到狼狽不堪的約翰那兒，他會從你的身體裡抽取這些「蛛后的乳汁」。",
    [4867] = "閱讀瓦羅什的卷軸。將瓦羅什的魔精交給他。",
    [4881] = "將暗殺計畫通知給白沙崗哨的卡納提·灰雲。",
    [4882] = "把藍羽項鏈交給血毒崗哨的特盧爾·法貝恩。",
    [4883] = "把藍羽項鏈交給納拉·蠻鬃。",
    [4901] = "在蘭莎爾拉嘗試激活艾露恩祭壇的過程中保護她。然後將妳的發現報告給魯瑟蘭村的艾瑞拉斯·琥珀。",
    [4902] = "與達納蘇斯的大德魯伊範達爾·鹿盔談壹談。",
    [4903] = "殺死歐莫克大王、指揮官沃恩和維姆薩拉克。找到重要的黑石文件，然後向卡加斯的軍官高圖斯彙報。",
    [4904] = "護送拉克塔·風歌離開恐怖圖騰營地，然後與亂風崗的薩利亞談話。",
    [4906] = "費伍德森林的艾瑞丹·藍風要你去殺掉8個碧火喚魔者、8個碧火背叛者、8個碧火欺詐者和薩瓦里克。任務完成之後回到艾瑞丹那裡覆命。",
    [4907] = "與丁奇·斯迪波爾談話。",
    [4921] = "找到曼寇里克的妻子，然後回到十字路口找他。",
    [4941] = "和奧格瑞瑪的伊崔格談壹談。討論完畢後，咨詢薩爾的意見。 妳回憶起曾在薩爾的大廳中見過伊崔格。",
    [4961] = "殺死寶珠之魔，然後與塔貝薩談話。",
    [4962] = "帶上地獄犬紅寶石到淒涼之地去，用它捕獲一隻地獄犬的靈魂。成功之後，將地獄犬紅寶石和被禁錮的地獄犬靈魂交給貧瘠之地的梅納拉·沃倫德。",
    [4963] = "帶上地獄火綠寶石到淒涼之地去，用它捕獲一個地獄火的靈魂。成功之後，將地獄火綠寶石和被禁錮的地獄火靈魂交給貧瘠之地的梅納拉·沃倫德。",
    [4964] = "等待梅納拉·沃倫德完成達奧拉赫寶珠，然後再與她談一談。",
    [4965] = "與貧瘠之地的梅納拉·沃倫德談壹談。",
    [4966] = "保護卡納提·灰雲免受半人馬的襲擊。",
    [4967] = "與貧瘠之地的梅納拉·沃倫德談壹談。",
    [4968] = "與貧瘠之地的梅納拉·沃倫德談話。",
    [4969] = "與貧瘠之地的梅納拉·沃倫德談話。",
    [4970] = "收集5塊碎齒熊肉和5塊冰風奇美拉肉，把它們交給冬泉谷的雷沃·霜翼。",
    [4971] = "在安多哈爾的一處倉庫附近使用時光置換器，使時光寄生蟲現身。 殺掉15隻時光寄生蟲，然後將時光置換器還給西瘟疫之地安多哈爾旅店的克羅米。",
    [4972] = "在安多哈爾城中四處散落的保險箱裡找到5個安多哈爾懷錶，然後把它們交給西瘟疫之地安多哈爾旅店裡的克羅米。",
    [4973] = "在安多哈爾城的廢墟裏找到5只安多哈爾懷表，然後把它們交給西瘟疫之地安多哈爾旅店裏的克羅米。",
    [4974] = "去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑪。",
    [4975] = "等待梅納拉·沃倫德完成諾奧拉赫寶珠，然後再與她談話。",
    [4976] = "將淨化過的地獄火寶珠交給貧瘠之地的梅納拉·沃倫德。",
    [4981] = "到黑石塔去查明比修的下落。",
    [4982] = "找到比修的裝置並把它們還給她。你記得她說過她把裝置藏在城市的最底層。",
    [4983] = "把比修的偵查報告交給卡加斯的雷克斯洛特。",
    [4984] = "消滅8隻生病的狼，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。",
    [4985] = "消滅8隻生病的灰熊，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。",
    [4986] = "根據這枝刻著文字的橡木樹枝所附加的魔法，這個牛頭人德魯伊本來準備把它交給達納蘇斯的塞納里奧議會。到那裡去找尋求某個德魯伊的幫助吧。",
    [4987] = "根據這枝刻著文字的橡木樹枝所附加的魔法，這個牛頭人德魯伊本來準備把它交給達納蘇斯的塞納里奧議會。到那裡去找尋求某個德魯伊的幫助吧。",
    [5001] = "找到比修的裝置並把它們還給她。祝妳好運！",
    [5002] = "到燃燒平原去，把比修的情報交給麥克斯韋爾元帥。",
    [5021] = "這個女人的幽靈告訴你她要送出一個包裹。她說那個包裹就在她的馬旁邊。至於馬在哪裡或者包裹要送到哪裡去，她卻根本沒有說。",
    [5022] = "向暴風城的皇家代理人確認艾瑪·費爾斯通的下落。通常在市政廳裡都有一個人口普查官。",
    [5023] = "與幽暗城的皇家管理人打聽傑雷米亞·費爾斯通的下落。通常在公會註冊處附近會有一個人口普查官。",
    [5041] = "找到並把十字路口的補給箱還給貧瘠之地的索克。",
    [5047] = "與永望鎮的瑪雷弗斯·暗錘談壹談。",
    [5048] = "找到暴風城的老艾瑪並弄清楚她是否就是艾瑪·菲爾斯通。如果她是,那麼她可能會想要珍妮絲·菲爾斯通為她製作的包裹.",
    [5049] = "在幽暗城找到傑雷米亞·派森並查明他是否真是傑雷米亞·費爾斯通.如果他是，那麼可能他會想要Janice Felstone給他做的包裹。",
    [5050] = "把半個好運護符還給西瘟疫之地的詹妮絲·費爾斯通。",
    [5051] = "在西瘟疫之地的菲爾斯通農場的某個地方找尋另外半個幸運符並組合起來。 把幸運符交給西瘟疫之地菲爾斯通農場的珍妮絲·菲爾斯通。",
    [5052] = "給陶拉祖營地的碎牙帶去一塊血岩碎片。 如果你想要他賜予你阿迦瑪甘的力量，就搜集更多的血岩碎片。",
    [5054] = "費伍德森林血毒崗哨的斯托姆·影蹄想要你去殺死尤西烏斯。",
    [5055] = "費伍德森林血毒崗哨的斯托姆·影蹄想要你去殺死布魯米蘭。",
    [5056] = "費伍德森林血毒崗哨的斯托姆·影蹄想要你去殺死希洛塔姆。",
    [5057] = "把斯托姆·影蹄的徽記交給雷霆崖的梅洛·石蹄。",
    [5061] = "回到達納蘇斯，讓瑪斯雷·馭熊者看看你的海獅墜飾。",
    [5062] = "採集10支火岩龍舌蘭，然後去雷霆崖的長者高地尋找瑪加薩·恐怖圖騰。",
    [5063] = "為了制造血色學者之帽，妳必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，5根磨損的憎惡縫合線，8塊奧術水晶，5根魔化紅線。 另外妳還必須支付50金幣的制作費用。",
    [5064] = "在暗雲峰找出並拿回三封秘密訊息。",
    [5065] = "把第三塊和第四塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。",
    [5066] = "找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。",
    [5067] = "為了制造阿卡納護腿，妳必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，5根磨損的憎惡縫合線，5塊奧金錠，5份萊斯·霜語的防腐液。 另外妳還必須支付50金幣的制作費用。",
    [5068] = "為了制造嗜血胸甲，妳必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，10根磨損的憎惡縫合線，5塊奧金錠，5塊暗影之皮。 另外妳還必須支付50金幣的制作費用。",
    [5081] = "到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處復命。",
    [5082] = "冬泉谷的多諾瓦·雪山要你去殺死8個冬泉探路者、8個冬泉巢穴守衛和8個冬泉圖騰師。",
    [5083] = "將空的火水瓶交給冬泉谷的多諾瓦·雪山。",
    [5084] = "搜尋費伍德森林北部的死木熊怪的營帳，繼續尋找線索。",
    [5085] = "帶著你的發現回去找多諾瓦·雪山。",
    [5086] = "為冬泉谷的多諾瓦·雪山收集3份劇毒水滴。",
    [5087] = "找到冬泉信差，阻止他們向冬泉村運送物品。",
    [5088] = "殺死阿利卡拉。把她的遺體和火岩粉交給白沙崗哨的莫特加‧火鬃作為證明。",
    [5089] = "把達基薩斯將軍的命令交給燃燒平原的麥克斯韋爾元帥。",
    [5090] = "找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。",
    [5091] = "找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。",
    [5092] = "殺掉悔恨嶺中的10個骷髏剝皮者和10個被奴役的食屍鬼。 然後向西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特覆命。",
    [5093] = "找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。",
    [5094] = "找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。",
    [5095] = "找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。",
    [5096] = "到血色十字軍建在費爾斯通農場和達爾松之淚之間的營地去，摧毀他們的指揮帳篷。 將天譴軍團的戰旗插在營地中，然後回到西瘟疫之地亡靈壁壘的高級執行官德靈頓那兒。",
    [5097] = "使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。 在做完了標記之後，將信號火炬還給西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特。",
    [5098] = "使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。 在做完了標記之後，將信號火炬還給西瘟疫之地亡靈壁壘的高級執行官德靈頓。",
    [5102] = "去黑石塔殺掉達基薩斯將軍。當任務完成之後回去找麥斯威爾指揮官。",
    [5103] = "世界上壹定有人知道關於這副手套的事情，祝妳好運！",
    [5121] = "冬泉谷的多諾瓦·雪山要你去擊敗冬泉酋長。",
    [5123] = "把字跡潦草的日誌帶去給冬泉谷的多諾瓦·雪山。",
    [5124] = "將6塊魔化瑟銀錠、2份火焰精華和4顆紅寶石交給瑪雷弗斯·暗錘。另外妳還得把未淬火的板甲護手也交給他。",
    [5126] = "與羅拉克斯談壹談，聽聽他要說什麽。",
    [5127] = "到黑石塔去找到古拉魯克。殺死他，然後用血汙長矛刺入他的屍體。當他的靈魂被吸幹後，這支矛就會成為穿魂長矛。 妳還必須找到未鑄造的符文覆飾胸甲。 將穿魂長矛和未鑄造的符文覆飾胸甲都交給冬泉谷的羅拉克斯。",
    [5128] = "將潦草的日誌交給費伍德森林南部的科雷克·望天。",
    [5141] = "將2套硬化蠍殼胸甲、2套硬化蠍殼手套和10片龍鱗交給艾薩拉的彼得·加林。 完成這項任務之後，妳就可以學到龍鱗制皮技術了。 同時，妳也將永遠無法學習元素制皮技術和部族制皮技術，在決定之前先考慮清楚。",
    [5142] = "找尋潘蜜拉·雷德帕斯。",
    [5143] = "將1件蠻皮外衣和1件蠻皮頭盔交給菲拉斯的凱雷希亞·獵月。 完成這項任務之後，你就可以學到部族製皮技術了。 同時，你也將永遠無法學習元素製皮技術和龍鱗製皮技術，在決定之前先考慮清楚。",
    [5144] = "將2個火焰之心、2個純水之球、2個大地之核和2個風之氣息交給灼熱峽谷的薩拉·坦尼。 壹旦妳完成這項任務，就可以開始學習元素制皮技藝了。 同時，妳也就無法再學習龍鱗制皮和部落制皮了，在妳決定之前要考慮清楚。",
    [5145] = "將2套硬化蠍殼胸甲、2套硬化蠍殼手套和10片龍鱗交給荒蕪之地的索卡夫·龍眼。 完成這項任務之後，妳就可以學到龍鱗制皮技術了。 同時，妳也將永遠無法學習元素制皮技術和部族制皮技術，在決定之前先考慮清楚。",
    [5146] = "將2個火焰之心、2個純水之球、2個大地之核和2個風之氣息交給阿拉希山脈的布魯姆·白蹄。 壹旦妳完成這項任務，就可以開始學習元素制皮技藝了。 同時，妳也就無法再學習龍鱗制皮和部落制皮了，在妳決定之前要考慮清楚。",
    [5147] = "殺死阿納克·恐怖圖騰，並向亂風崗的峭壁衛兵圖林·長角出示證據。",
    [5148] = "將1件蠻皮外衣和1件蠻皮頭盔交給荊棘谷的瑟伊布。 完成這項任務之後，妳就可以學到部族制皮技術了。 同時，妳也將永遠無法學習元素制皮技術和龍鱗制皮技術，在決定之前先考慮清楚。",
    [5149] = "找到帕米拉的洋娃娃。",
    [5151] = "殺了那隻野獸並把超適應齒輪和豹籠鑰匙帶回來交給維茲羅。",
    [5152] = "與安多哈爾廢墟南邊的瑪萊恩談話。",
    [5153] = "把約瑟夫的結婚戒指交給安多哈爾的克羅米。",
    [5154] = "把《達隆郡的歷史》交給安多哈爾的克羅米。",
    [5155] = "到加德納爾去殺掉4個加德納爾惡犬、4個加德納爾守護者、6個加德納爾精兵和6個加德納爾祭司，然後向費伍德森林的格雷塔·苔蹄覆命。",
    [5156] = "殺掉2個熱能野獸和2個熱能恐獸，並探索碎痕谷。然後查看凹坑中是否仍然充滿了墮落的惡臭之水，完成這些任務之後，向費伍德森林中的塔諾恩·紅羽覆命。",
    [5157] = "把空壺拿到加德納爾中心的月井去，裝滿井水之後再回到費伍德森林的格雷塔·苔蹄那裡。",
    [5158] = "把腐化的月井水交給貧瘠之地的水之先知伊斯倫。",
    [5159] = "把淨化過的月井水交給費伍德森林的格雷塔·苔蹄。",
    [5160] = "到冬泉谷去找到哈爾琳，把奧比的鱗片交給她。",
    [5161] = "要是妳想繼續的話，就與哈爾琳談壹談。",
    [5162] = "與瘟疫之地的耶茲巴交談。他居住在安多哈爾。",
    [5163] = "帶著烏米的機械雪人去嚇唬她的朋友： 永望鎮的萊加奇（冬泉谷）、加基森的斯普琳科（塔納利斯），還有馬紹爾營地的奎克希爾（安戈洛環形山）。 當你完成任務之後，把機械雪人還給烏米。",
    [5164] = "閱讀遊蕩者目錄。",
    [5165] = "使用淨化過的月井水熄滅暗影堡內部的四座火盆的火焰，從而破除其保護效果，然後向翡翠聖地的格雷塔·苔蹄覆命。",
    [5166] = "為了鑄造多彩巨龍胸甲，妳必須把以下材料交給雕刻者耶茲巴： 1塊多彩龍鱗。 10塊閃亮的彩色龍鱗。 10份英雄之血。 10塊磨損的憎惡縫合線。",
    [5167] = "為了鑄造多彩挑戰者腿甲，妳必須把以下材料交給雕刻者耶茲巴： 1塊多彩龍鱗。 10塊閃亮的彩色龍鱗。 10份英雄之血。 5塊暗影之皮。",
    [5168] = "把達維的聖契和雷德帕斯之盾交給卡林·雷德帕斯。",
    [5181] = "將霍古斯的顱骨和馬杜克的破碎之劍交給聖光之願禮拜堂的卡林·雷德帕斯。",
    [5201] = "雷沃·霜翼要妳去殺死5個冬泉薩滿祭司和5個冬泉巨熊怪。",
    [5202] = "搜尋加德納爾，找出血紅鑰匙的用途。",
    [5203] = "護送亞科納琳到萊弗治和她的裝備所在的地方，然後保護她逃離暗影堡。之後，在費伍德森林找傑希爾·月弓，並告訴她剛才發生的事情。",
    [5204] = "回到加德納爾殺了魅魔拉凱雅，然後找到特雷·萊弗治的殘骸。",
    [5206] = "把5個共鳴顱骨和神秘水晶交給東瘟疫之地的卡林·雷德帕斯。",
    [5210] = "將《達隆鎮全史》交給東瘟疫之地的卡林·雷德帕斯。",
    [5211] = "釋放15個達隆郡居民的靈魂，然後返回卡林·雷德帕斯身邊。",
    [5212] = "從斯坦索姆找回20個瘟疫肉塊，並把它們交給貝蒂娜·比格辛克。你覺得斯坦索姆中的生物都不大可能長著肉。",
    [5213] = "到斯坦索姆去探索那裡的通靈塔。找到新的天譴軍團檔案，把它交給貝蒂娜·比格辛克。",
    [5214] = "找到艾茲拉‧格里姆在斯坦索姆的煙草店，並從中找回一盒格里姆的特級煙草，把它交給煙鬼拉魯恩。",
    [5215] = "與西瘟疫之地冰風崗的高階牧師瑪多妮爾談話。",
    [5216] = "到西瘟疫之地的費爾斯通農場去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶費爾斯通農場的空瓶來採集瘟疫之鍋中的毒藥樣本。",
    [5217] = "把費爾斯通農場的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。",
    [5219] = "到西瘟疫之地的達爾松之淚去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶達爾松之淚的空瓶來採集瘟疫之鍋中的毒藥樣本。",
    [5220] = "把達爾松之淚的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。",
    [5222] = "到西瘟疫之地的嚎哭鬼屋去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶嚎哭鬼屋的空瓶來採集瘟疫之鍋中的毒藥樣本。",
    [5223] = "把嚎哭鬼屋的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。",
    [5225] = "到西瘟疫之地的蓋羅恩農場去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶蓋羅恩農場的空瓶來採集瘟疫之鍋中的毒藥樣本。",
    [5226] = "把蓋羅恩農場的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。",
    [5228] = "與西瘟疫之地亡靈壁壘的暗影牧師范蒂絲談話。",
    [5229] = "到西瘟疫之地的費爾斯通農場去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶費爾斯通農場的空瓶來採集瘟疫之鍋中的毒藥樣本。",
    [5230] = "把費爾斯通農場的樣本瓶交給西瘟疫之地亡靈壁壘的暗影牧師范蒂絲。",
    [5231] = "到西瘟疫之地的達爾松之淚去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶達爾松之淚的空瓶來採集瘟疫之鍋中的毒藥樣本。",
    [5232] = "把裝滿的達爾松眼淚之瓶交給西瘟疫之地亡靈壁壘的暗影牧師范蒂絲。",
    [5233] = "到西瘟疫之地的嚎哭鬼屋去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶嚎哭鬼屋的空瓶來採集瘟疫之鍋中的毒藥樣本。",
    [5234] = "把裝滿了的瓶子交給西瘟疫之地的亡靈壁壘暗影牧師范蒂絲。",
    [5235] = "到西瘟疫之地的蓋羅恩農場去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶蓋羅恩農場的空瓶來採集瘟疫之鍋中的毒藥樣本。",
    [5236] = "把蓋羅恩農場的樣本瓶交給西瘟疫之地亡靈壁壘的暗影牧師范蒂絲。",
    [5241] = "找到卡林·瑞德巴思。",
    [5242] = "殺掉米萊恩和薩莉亞，並把暗影領主費爾丹的頭顱交給費伍德森林的格雷塔·苔蹄。",
    [5243] = "到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當你找到足夠的聖水之後就回去向萊尼德·巴薩羅梅覆命。",
    [5244] = "與墜星村的加隆·石矛談話。",
    [5245] = "使用加隆的鎬來尋找四塊精靈貴族聖物的碎片，把它們交給東瘟疫之地的奧蘿拉。",
    [5246] = "在艾薩拉的辛瑪洛神殿裡，找到神聖的精靈貴族筆跡。然後交給奧蘿拉，她就靠近東瘟疫之地的北地哨塔。",
    [5247] = "給接近東瘟疫之地的奧蘿拉帶1塊附魔瑟銀錠、5塊恢復水晶，以及1小瓶恐怖之水。",
    [5248] = "把辛瑪洛水晶帶回冬泉谷的凱斯利爾湖，在那裏尋找壹個會與妳講話的上層精靈。",
    [5249] = "找到冬泉谷的墜星村，在那裡與威恩德·夜風談話。",
    [5250] = "找到冬泉谷的墜星村，在那裡與威恩德·夜風談話。",
    [5251] = "在斯坦索姆城中找到血色十字軍的文件管理員加爾福特，殺掉他，然後燒毀血色十字軍文獻。",
    [5252] = "和墜星村的維恩德·夜風談壹談，了解到辛瑪洛水晶所在的位置。",
    [5253] = "將辛瑪洛水晶送到達納蘇斯的大德魯伊範達爾·鹿盔那裏。",
    [5261] = "與伊根·派特斯金納談話。",
    [5262] = "將巴納紮爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。",
    [5263] = "到斯坦索姆去殺掉瑞文戴爾男爵，把他的頭顱交給尼古拉斯·瑟倫霍夫公爵。",
    [5264] = "和瑪克斯韋爾·泰羅索斯男爵談壹談。他就在教堂裏面。",
    [5265] = "打開銀色黎明寶箱，拿取妳應得的獎勵。",
    [5281] = "找到伊根。你只知道他在斯坦索姆附近。",
    [5282] = "對斯坦索姆的鬼魂使用伊根的衝擊器。當那些永不安息的靈魂掙脫他們的外殼時，再次使用伊根的衝擊器——他們就可以獲得自由了！ 解放15個永不安息的靈魂，然後回到伊根那裡去。",
    [5283] = "要想成為一名護甲鑄造師的話，你必須將下列物品交給格魯努斯：4頂華麗秘銀頭盔、2雙華麗秘銀戰靴和1副華麗秘銀胸甲。",
    [5284] = "要想成為一名武器鑄造師的話，你必須將下列物品交給埃隆努斯·冷鋼：4把月鋼寬劍、4把巨型鐵斧、2把秘銀重斧和2把巨型黑色錘。",
    [5301] = "要想成為一名護甲鍛造師的話，你必須將下列物品交給奧克索斯：4頂華麗秘銀頭盔、2雙華麗秘銀戰靴和1副華麗秘銀胸甲。",
    [5302] = "要想成為一名武器鑄造師的話，你必須將下列物品交給伯古什：4把月鋼寬劍、4把巨型鐵斧、2把秘銀重斧和2把巨型黑色錘。",
    [5305] = "到斯坦索姆去殺死紅衣鑄錘師。將紅衣鑄錘師的圍裙交給莉莉絲。",
    [5306] = "到黑石塔去殺死暗影獵手沃什加斯，將沃什加斯的菊石交給基爾拉姆。",
    [5307] = "在斯坦索姆找到黑衣守衛鑄劍師，然後殺死他。將黑色衛士徽記交給亡靈殺手瑟裏爾。",
    [5321] = "護送克羅尼亞‧恒影沿著道路向南前往利拉迪斯‧月河那裡，並在黑海岸尋找他的背包。",
    [5341] = "到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到阿萊克斯·巴羅夫那兒去。",
    [5342] = "到冰風營地——聯盟的領地——去暗殺維爾頓·巴羅夫。把他的腦袋交給阿萊克斯·巴羅夫。 要多加小心，聯盟也許對維爾頓執行了嚴密的保護。",
    [5343] = "到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到維爾頓·巴羅夫那兒去。",
    [5344] = "去亡靈壁壘——部落的領地——去暗殺阿萊克斯·巴羅夫。把他的腦袋交給維爾頓·巴羅夫。 要小心，部落也許對阿萊克斯實施了嚴密的保護。",
    [5361] = "將峭壁衛兵圖林·長角的報告交給淒涼之地鬼旅崗哨的納塔卡·長角。",
    [5381] = "在雷斧堡壘中找到惡魔之盒，把它和惡魔之鋤一起交給葬影村的泰迦·慧鬃。",
    [5382] = "在通靈學院中找到瑟爾林·卡斯迪諾夫教授。殺死他，並燒毀艾瓦·薩克霍夫和盧森·薩克霍夫的遺體。任務完成後就回到艾瓦·薩克霍夫那兒。",
    [5384] = "帶著無辜者之血回到通靈學院，將它放在門廊的火盆下面，基爾圖諾斯會前來吞噬妳的靈魂。 勇敢地戰鬥吧，不要退縮！殺死基爾圖諾斯，然後回到艾瓦·薩克霍夫那兒。",
    [5385] = "將特雷·萊弗治的殘骸交給費伍德森林的傑希爾·月弓。",
    [5386] = "與葬影村的吉納澤林談話，然後將2條血肚魚交給納塔卡·長角。",
    [5441] = "在懶惰的苦工睡覺時，用工頭的木棒敲他們。敲醒5個苦工，然後把工頭的木棒還給試煉谷的工頭塔茲利爾。",
    [5461] = "到阿拉希高地的激流堡遺跡裡面尋找巫妖生前的遺物。如果你能找到這樣的東西，就把它交給馬杜克鎮長。",
    [5462] = "到東瘟疫之地的聖光之願禮拜堂去找到萊尼德·巴薩羅梅，給他看看巫妖生前的遺物，並告訴他妳收集到的情報。",
    [5463] = "到斯坦索姆城裏去找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。",
    [5464] = "把禁錮靈魂的遺物交給東瘟疫之地的萊尼德·巴薩羅梅。",
    [5465] = "回到凱爾達隆的馬杜克鎮長那裏，把禁錮靈魂的遺物交給他。",
    [5466] = "在通靈學院裏找到萊斯·霜語。當妳找到他之後，使用禁錮靈魂的遺物破除其亡靈的外殼。如果妳成功地破除了他的不死之身，就殺掉他並拿到萊斯·霜語的頭顱。把那個頭顱交給馬杜克鎮長。",
    [5481] = "收集3根陰暗草，把它們交給布瑞爾墓地的初級藥劑師霍蘭德。",
    [5482] = "收集10株末日草，把它們交給初級藥劑師霍蘭德。",
    [5501] = "從科多墓地收集10根科多獸骨，把它們交給獸人小屋的比布里·弗斯巴克。",
    [5504] = "把10個銀色黎明勇氣勛章交給西瘟疫之地亡靈壁壘的銀色黎明軍需官哈薩娜。",
    [5507] = "把10個銀色黎明勇氣勛章交給西瘟疫之地冰風營地的銀色黎明軍需官萊斯巴克。",
    [5513] = "把10個銀色黎明勇氣勛章交給東瘟疫之地聖光之願禮拜堂的軍需官米蘭達·布利洛克。",
    [5514] = "把灌魔的骸骨碎片和15枚金幣交給加基森的克林科·古德斯迪爾。",
    [5515] = "在通靈學院找到詹迪斯·巴羅夫並打敗她。從她的屍體上找到卡斯迪諾夫的恐懼之袋，然後將其交給艾瓦·薩克霍夫。",
    [5517] = "把25個銀色黎明勇氣勛章交給東瘟疫之地聖光之願禮拜堂的銀色黎明軍需官米蘭達·布利洛克。",
    [5518] = "把4份符文布卷、8塊硬甲皮、2卷符文線和一份巨魔鞣酸交給諾特·希姆加克。他現在被拴在厄運之槌的戈多克巨魔那邊。",
    [5521] = "把25個銀色黎明勇氣勛章交給西瘟疫之地冰風營地的銀色黎明軍需官萊斯巴克。",
    [5522] = "把冰凍的龍蛋交給東瘟疫之地的萊尼德·巴薩羅梅。",
    [5524] = "把25個銀色黎明勇氣勛章交給西瘟疫之地亡靈壁壘的銀色黎明軍銀色黎明軍需官哈薩娜。",
    [5526] = "在厄運之槌中找到魔藤，然後從它上面采集壹塊碎片。只有幹掉了奧茲恩之後，妳才能進行采集工作。使用凈化之匣安全地封印碎片，然後將其交給月光林地永夜港的拉比恩·薩圖納。",
    [5527] = "到希利蘇斯的南風村去尋找淨化之匣。然後將其交給月光林地永夜港的拉比恩·薩圖納。",
    [5529] = "殺掉20隻瘟疫幼龍，然後向聖光之願禮拜堂的貝蒂娜·比格辛克復命。",
    [5531] = "將冰凍的龍蛋交給貝蒂娜·比格辛克。",
    [5533] = "和西瘟疫之地冰風崗的化學家阿爾比頓談話。",
    [5534] = "尋找埃達拉斯廢墟中的納迦攜帶的那些符石，然後把它們交給艾薩拉的基姆加爾。",
    [5535] = "殺掉6個精靈貴族的幻影和6個精靈貴族鬼巫，然後向艾薩拉的羅哈圖覆命。",
    [5536] = "殺掉6個哈達爾薩特、2個哈達爾欺詐者和2個哈達爾魔僕，然後向梣谷與艾薩拉交界處的羅哈圖覆命。",
    [5537] = "將15塊骷髏碎片交給西瘟疫之地冰風崗的化學家阿爾比頓。",
    [5538] = "把灌魔的骸骨碎片和15枚金幣交給加基森的克林科·古德斯迪爾。",
    [5541] = "把海格納的彈藥交給丹莫洛的海格納·重槍。",
    [5542] = "殺掉20條瘟疫幼犬、5條瘟疫犬和5條狂怒的瘟疫犬。任務完成之後向提里恩·弗丁覆命。",
    [5543] = "殺死30隻瘟疫蝙蝠，然後向提里恩·弗丁覆命。",
    [5544] = "在東瘟疫之地搜索腐肉蟲和腐肉吞噬者。殺了它們並收集它們的肉。當你收集到15塊食腐蟲肉塊之後，就回到提里恩·弗丁那裡。",
    [5545] = "收集8捆木材，把它們交給東谷伐木場的管理員萊琳。",
    [5561] = "將科多獸誘引器和5頭被馴服的科多獸交給瑟卡布斯庫的營地中的斯米德·瑟卡布斯庫。",
    [5581] = "放逐6個瑪諾洛克集會所的傳送門，然後回到葬影村的泰迦·慧鬃那裡。",
    [5582] = "把健康的龍鱗交給東瘟疫之地聖光之願禮拜堂中的貝蒂娜·比格辛克。",
    [5601] = "在達隆郡裡找到帕米拉·雷德帕斯。",
    [5621] = "找到哨兵莎恩雅並使用次級治療術（等級 2）來治療她。然後對她施放真言術：韌，最後向多蘭納爾的勞爾娜·晨光覆命。",
    [5622] = "與泰達希爾的勞爾娜·晨光談話。",
    [5623] = "與艾爾文森林的女牧師潔塞塔談話。",
    [5624] = "找到衛兵羅伯茲並使用次級治療術（等級 2）治療他。然後對他施放真言術：韌，之後回來找閃金鎮的女牧師潔塞塔。",
    [5625] = "找到巡山人多爾夫並使用次級治療術（等級 2）治療他。然後對他施放真言術：韌，之後回去找卡拉諾斯的馬克薩恩·安沃爾。",
    [5626] = "與丹莫洛的馬克薩恩·安沃爾談話。",
    [5628] = "與達納蘇斯的女祭司阿蘭希雅談壹談。",
