    [5643] = "與奧格瑞瑪的烏爾庫談壹談。",
    [5644] = "與幽暗城的艾薩萊斯特談壹談。",
    [5645] = "與鐵爐堡的高階牧師洛漢談壹談。",
    [5646] = "與幽暗城的艾薩萊斯特談話。",
    [5647] = "與鐵爐堡的高階牧師洛漢談壹談。",
    [5648] = "找到步兵科雅，用次級治療術（等級 2）治療她，然後為她加上真言術：韌，最後向剃刀嶺的泰金復命。",
    [5649] = "與杜隆塔爾的泰金談壹談。",
    [5650] = "找到亡靈士兵科爾並使用次級治療術（等級 2）來治療他。然後對他施放真言術：韌，最後向布瑞爾的黑暗牧師貝裏爾復命。",
    [5651] = "與提瑞斯法林地的黑暗牧師貝裏爾談壹談。",
