    [5663] = "與幽暗城的艾薩萊斯特談壹談。",
    [5673] = "與達納蘇斯的女祭司阿蘭希雅談話。",
    [5674] = "與達納蘇斯的女祭司阿蘭希雅談壹談。",
    [5675] = "與達納蘇斯的女祭司阿蘭希雅談壹談。",
    [5677] = "與暴風城的高階牧師勞瑞娜談壹談。",
    [5713] = "保護哨兵阿娜莎，然後向梣谷邁斯特拉崗哨的奧奈雅報告。",
    [5721] = "將聖物包裹放在達隆郡的廣場中。 在霍古斯死亡之前，達維必須存活。 在雷德帕斯隊長墮落之前保證他存活。 擊敗墮落的雷德帕斯。 當約瑟夫·雷德帕斯出現在廣場中時，與他的靈魂進行交談，然後回到帕米拉的家中去找帕米拉。",
    [5722] = "在怒焰裂谷搜尋瑪爾·恐怖圖騰的屍體以及他留下的東西。",
    [5723] = "在奧格瑪找到怒焰裂谷，殺掉8個怒焰穴居怪和8個怒焰薩滿，然後向雷霆崖的拉哈羅覆命。",
    [5724] = "將恐怖圖騰背包交給雷霆崖的拉哈羅。",
    [5725] = "將《暗影法術研究》和《扭曲虛空的魔法》這兩本書交給幽暗城的瓦里瑪薩斯。",
    [5726] = "將軍官的徽章交給奧格瑪的索爾。",
    [5727] = "將軍官的徽章交給尼爾魯·燃刃並與他談話，看看他是否相信你是燃刃氏族中的一員，然後回到奧格瑪的索爾那裡。",
    [5728] = "殺死巴札蘭和祈求者耶戈什，然後回到奧格瑪的索爾那裡。",
    [5729] = "與奧格瑪的尼爾魯·火刃談話。",
    [5730] = "與奧格瑪的索爾談話，告訴他你瞭解到的東西。",
    [5741] = "拿到聖光節杖，並將它交給艾瑟雷索塔里的阿佐爾·奧達蒙特。",
    [5742] = "聽聽提里恩·弗丁要說什麼。",
    [5761] = "進入怒焰裂谷，殺死饑餓者塔拉加曼，然後把他的心臟交給奧格瑪的尼爾魯·火刃。",
    [5762] = "將克拉維爾的箱子送到荊棘谷的赫米特·奈辛瓦里那裡。",
    [5763] = "將魯恩的科多獸角送到荊棘谷的赫米特·奈辛瓦里那裡。",
    [5781] = "到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提里恩·弗丁那裡。",
    [5801] = "把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛環形山地區的火羽山頂部。在熔岩湖旁使用骷髏鑰匙模具，鑄造出一把未完工的骷髏鑰匙。 把未完工的骷髏鑰匙交給西瘟疫之地冰風崗的化學家阿爾比頓。",
    [5802] = "把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛環形山地區的火羽山頂部。在熔岩湖旁使用骷髏鑰匙模具，鑄造出一把未完工的骷髏鑰匙。 把未完工的骷髏鑰匙交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。",
    [5803] = "殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地冰風崗的化學家阿爾比頓。",
    [5804] = "摧毀安多哈爾的4顆天災召喚水晶來召喚阿拉基。殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。",
    [5821] = "護送基澤爾頓商隊通過科卡爾半人馬村，然後與瑟卡布斯庫的營地中的斯米德談話以領取你的獎賞。",
    [5845] = "到東瘟疫之地東北部的北谷去，找到失落榮耀的象徵。完成目標之後向提里恩·弗丁覆命。",
    [5846] = "到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。",
    [5848] = "到瘟疫之地北部的斯坦索姆去。你可以在血色十字軍堡壘中找到「愛與家庭」這幅畫，它被隱藏在另一幅描繪兩個月亮的畫之後。 把這幅畫還給提里恩·弗丁。",
    [5861] = "到瘟疫之地南部的烏瑟之墓去，將提里恩的禮物交給巫女米蘭達。",
    [5862] = "和巫女米蘭達交談以獲得血色幻象的效果。在血色幻象的掩護下深入壁爐谷，將提里恩的禮物交給大領主泰蘭·弗丁。 壁爐谷在北方，泰蘭應該在瑪登霍爾德城堡裡面。",
    [5863] = "加基森的安迪·利恩想要你攻入砂槌營地，殺死10個砂槌蠻兵、10個砂槌執行者，以及掠奪者格瑪洛克。",
    [5881] = "馬格蘭希望你將信送到貧瘠之地升降梯的瑞什·遠行者手中。",
    [5892] = "把10份深鐵礦洞補給品交給丹巴達爾的聯盟軍需官。",
    [5893] = "把10份冷齒礦洞補給品交給霜狼要塞的部落軍需官。",
    [5901] = "在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100隻瘟疫白蟻之後，就回到提里斯法林地的亡靈壁壘去找米克·萊文。",
    [5902] = "到西瘟疫之地的北山伐木場去找個合適的地方，在那裡放下一桶瘟疫白蟻。",
    [5903] = "在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100隻瘟疫白蟻之後，就回到西瘟疫之地的冰風營地去找納薩尼爾·杜馬。",
    [5904] = "到西瘟疫之地的北山伐木場去找個合適的地方，在那裡放下一桶瘟疫白蟻。",
    [5921] = "使用法術「傳送：月光林地」抵達月光林地，在那裡與永夜港的德迪利特·星焰談話。",
    [5922] = "使用法術“傳送：月光林地”抵達月光林地，在那裏與永夜港的德迪利特·星焰談壹談。",
    [5923] = "與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。",
    [5924] = "與達納蘇斯塞納裏奧區的瑪斯雷·馭熊者談壹談。",
    [5925] = "與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。",
    [5926] = "與雷霆崖長者高地上的圖拉克·符文圖騰談壹談。",
    [5927] = "與雷霆崖長者高地上的圖拉克·符文圖騰談壹談。",
    [5928] = "與雷霆崖長者高地上的圖拉克·符文圖騰談壹談。",
    [5929] = "到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。",
    [5930] = "到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。",
    [5931] = "回到達納蘇斯，與塞納里奧區的瑪斯雷·馭熊者談話。",
    [5932] = "回到雷霆崖，與長者高地的圖拉克·符文圖騰談壹談。",
    [5941] = "將一包聖物交給安多哈爾的克羅米。",
    [5942] = "用約瑟夫的鑰匙打開約瑟夫的箱子。",
    [5943] = "護送基澤爾頓車隊通過瑪諾洛克集會所，然後與瑟卡布斯庫的營地的斯米德談一談，領取你的獎勵。",
    [5944] = "護送泰蘭·弗丁走出壁爐谷。",
    [5961] = "與東瘟疫之地的納薩諾斯·凋零者談一談。據說他居住在瑪瑞斯農場。",
    [5981] = "雷沃·霜翼要妳去殺死4個霜槌巨人和4個霜槌保衛者。",
    [6001] = "使用奧伯丁的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。 任務完成之後，與達納蘇斯的瑪斯雷·馭熊者談話。",
    [6002] = "使用莫高雷與貧瘠之地交界處的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。 任務完成之後，與雷霆崖的圖拉克·符文圖騰談話。",
    [6004] = "殺死2個血色醫護員、2個血色獵人、2個血色魔法師和2個血色騎士，然後回到西瘟疫之地的科爾斯塔·迪普沙東那兒。",
    [6021] = "將塞達爾的頭顱交給聖光之願禮拜堂的護理者奧林。",
    [6022] = "到東邊的考林路口去屠殺鎮裡的天譴軍團。在10分鐘內收集7塊生命腐質，使用研缽和搗杵將其研磨成凝固腐質。",
    [6023] = "殺掉獵人萊德雷和騎士杜爾根，然後向西瘟疫之地的科爾斯塔·迪普沙東覆命。",
    [6024] = "殺了滲透者哈米亞，用他的鑰匙開啟墓室後的一堆泥土。",
    [6025] = "進入壁爐谷並找一處高地，你可以在那裡觀察整個城鎮並估算血色十字軍的兵力，然後向西瘟疫之地的科爾斯塔·迪普沙東回報。",
    [6026] = "煙鬼拉魯恩要你拿來2塊瑟銀錠、1根金棒、8顆高爆炸彈和8個不牢固的扳機。 你需要找鐵匠和工程學技師幫忙製作這些東西。",
    [6027] = "拿到上古之書，將其交給艾瑟雷索塔中的阿佐爾·奧達蒙特。",
    [6028] = "把永望鎮報告送給西瘟疫地冰風營地的銀色黎明軍官普爾哈特。",
    [6029] = "把永望鎮報告送給西瘟疫地亡靈壁壘的銀色黎明軍官加魯什。",
    [6030] = "將《靈語研究》這本書交給東瘟疫之地聖光之願禮拜堂的尼古拉斯·瑟倫霍夫公爵。",
    [6031] = "把30塊符文布交給木喉要塞的梅羅什。",
    [6032] = "把2塊月布交給木喉要塞的梅羅什。",
    [6041] = "到聖光之願禮拜堂西北方的病木林去。在那些有爆炸標記的建築物中對爆炸標記使用煙鬼的特殊混合物，以此來摧毀8座天譴軍團建築。煙鬼已經給通靈塔和屠宰房做上了標記。 一旦你放置好炸彈，就離那些建築物遠一些，然後盡情欣賞你的傑作吧。 順便說一句，煙鬼的特殊混合物相當...不穩定。",
    [6042] = "殺掉20隻毒性瘟疫蝙蝠和10隻巨型瘟疫蝙蝠，然後回到納薩諾斯·凋零者那裡。",
    [6061] = "使用馴獸棒馴服成年陸行鳥。練習妳的技能，然後將馴獸棒還給血蹄村的雅文·刺鬃。",
    [6062] = "使用馴獸棒馴服可怕的雜斑野豬。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。",
    [6063] = "使用馴獸棒馴服樹林潛伏者。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。",
    [6064] = "使用馴獸棒馴服大型峭壁野豬。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。",
    [6065] = "與血蹄村的雅文·刺鬃談壹談。",
    [6066] = "與血蹄村的雅文·刺鬃談壹談。",
    [6067] = "與血蹄村的雅文·刺鬃談壹談。",
    [6068] = "與剃刀嶺的索塔爾談話。",
    [6069] = "與剃刀嶺的索塔爾談話。",
    [6070] = "與剃刀嶺的索塔爾談壹談。",
    [6071] = "與多蘭納爾的達札拉談話。",
    [6073] = "與多蘭納爾的達紮拉談壹談。",
    [6074] = "與卡拉諾斯的格瑞夫談壹談。",
    [6075] = "與卡拉諾斯的格瑞夫談話。",
    [6076] = "與卡拉諾斯的格瑞夫談壹談。",
    [6081] = "與奧格瑪的奧瑪克談話。",
    [6082] = "使用馴獸棒馴服硬甲蠍。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。",
    [6083] = "使用馴獸棒馴服海浪蟹。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。",
    [6084] = "使用馴獸棒馴服雪豹。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。",
    [6085] = "使用馴服獸棒馴服一頭冰爪熊。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。",
    [6086] = "與鐵爐堡的貝莉亞·雷岩談話。",
    [6087] = "使用馴獸棒馴服壹只草原捕食者。練習妳的技能，然後將馴獸棒還給血蹄村的雅文·刺鬃。",
    [6088] = "使用馴獸棒馴服壹只猛鷲。練習妳的技能，然後將馴服法杖交還給血蹄村的雅文·刺鬃。",
    [6089] = "與雷霆崖獵人高地的浩特·雷角談壹談。",
    [6101] = "使用馴獸棒馴服一隻夜刃捕食者。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。",
    [6102] = "使用馴獸棒馴服一隻巨翼惡梟。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。",
    [6103] = "與達納蘇斯塞納里奧區的祖卡斯特談話。",
    [6121] = "到月光林地去，與永夜港的德迪利特·星焰談話。",
    [6122] = "使用空的峭壁之泉取樣器在瀑布洞口獲得水樣本。 將盛滿的峭壁之泉取樣器送到黑海岸奧伯丁的奧蘭達利亞·夜歌那裡。",
    [6123] = "收集5個地根草和12個月亮菇，把它們交給奧伯丁的奧蘭達利亞·夜歌，這樣她就可以製作解藥了。",
    [6124] = "對黑海岸的10頭生病的鹿使用動物醫療藥膏，以此來治療它們。從壁泉河到奧伯丁，直到最南端靠近梣谷的地區都有生病的鹿出沒。",
    [6125] = "回到達納蘇斯塞納里奧區的瑪斯雷·馭熊者那裡。",
    [6126] = "到月光林地去，與永夜港的德迪利特·星焰談話。",
    [6127] = "使用空的鬼霧峰取樣器在山頂取水樣。 將盛滿的鬼霧峰取樣器送到貧瘠之地十字路口的圖加·符文圖騰那裡。",
    [6128] = "收集5個地根草和5個科多獸角，把它們交給十字路口的圖加·符文圖騰，這樣他就可以製作解藥了。",
    [6129] = "對貧瘠之地北部的10隻生病的瞪羚使用動物醫療藥膏，以此來治療它們。在穿過十字路口的那條東西走向的大路北面到處都是生病的蹬羚。",
    [6130] = "回到雷霆崖長者高地的圖拉克·符文圖騰那裡。",
    [6132] = "護送梅麗薩，再到淒涼之地和科多獸墳場的霍恩尼茲談談。",
    [6133] = "到東瘟疫之地的北方邊界去找回奎爾薩拉斯名冊，這件物品在奎爾林斯小屋的某處。 另外你還必須殺掉8個遊俠、8個巡路者和8個護林者。",
    [6134] = "把8個幽靈電漿和幽靈磁鐵箱帶給淒涼之地的霍恩尼茲。",
    [6135] = "找到暗翼蝠並殺掉它。從屍體上取下一塊暗翼蝠的皮，並把它交給納薩諾斯·凋零者。 據說暗翼蝠遊蕩在瑪瑞斯農場北面的荒原上。",
    [6136] = "找到東部瘟疫之地的北方荒原中的淤血蟲並消滅它。任務完成後回去找納薩諾斯·凋零者。",
    [6141] = "與淒涼之地的安東修士談話。",
    [6142] = "找到10塊軟殼蚌肉，把它們交給葬影村的麥拉斯。",
    [6143] = "殺死7個滑刃侍從、7個滑刃納迦，以及5個滑刃巫師，然後與葬影村的杜澤加爾談談。",
    [6144] = "到幽暗城去與瓦里瑪薩斯談話。",
    [6145] = "返回東瘟疫之地，找到並殺死紅衣信使，拿到大十字軍的命令。 把命令交給納薩諾斯·雕零者，並等待進壹步的指示。",
    [6146] = "到瑪瑞斯農場東南方的提爾之手去，抵達那裏之後就咬壹口爛蘋果。在血色十字軍偽裝的掩護下，把大十字軍的命令交給十字軍領主瓦德瑪爾。",
    [6147] = "帶著新情報返回納薩諾斯·雕零者那裏。",
    [6148] = "血色十字軍正在從提爾之手到斯坦索姆的路上巡邏，妳可以在巡邏隊中找到聖者德米提雅和她的隨從，找到並殺死她。如果妳成功了，就回到納薩諾斯·雕零者那裏去復命。",
    [6161] = "找到拉克摩爾的銀鑰匙和金鑰匙。找到並打開拉克摩爾的箱子。",
    [6162] = "殺死主宰洛爾，把他的爪子交給費伍德森林血毒崗哨的德雷卡蘇。",
    [6163] = "到斯坦索姆去，殺掉吞咽者拉姆斯登。把他的頭顱交給納薩諾斯。",
    [6164] = "把奧古斯圖斯的帳本交給恐懼谷中精神失常的奧古斯圖斯。",
    [6181] = "將路易斯的便箋交給獅鷲獸管理員索爾。",
    [6182] = "與暴風城的馬迪亞斯·肖爾談一談，他住在舊城區的兵營裡。",
    [6183] = "如果你願意接這個任務，就再和馬迪亞斯·肖爾談話。",
    [6184] = "到西瘟疫之地的冰風營地去跟弗林特·沙多摩爾會面。",
    [6185] = "搜尋東瘟疫之地，尋找「凋零者」的線索以及失蹤的軍情七處密探。如果你找到任何軍情七處徽章，就把它們交給冰風營地的弗林特·沙多摩爾。",
    [6186] = "回到暴風城，將納薩諾斯·瑪瑞斯的下落報告給伯瓦爾·弗塔根公爵。",
    [6187] = "組織一支部隊，然後到東瘟疫之地去。向納薩諾斯·凋零者和任何敢於保護他的部落成員發起攻擊。 你要傾盡全力，<name>。部落會不惜一切代價保護他們的遊俠領主。",
    [6261] = "將奧斯瑞克的箱子交給獅鷲獸管理員杜加爾·朗德瑞克。",
    [6281] = "從獅鷲獸管理員索爾那裡租用一頭獅鷲獸，然後把路易斯的便箋交給暴風城有限防護的奧斯瑞克·斯圖恩。",
    [6282] = "烈日石居的馬格蘭要你去殺掉7個血怒鷹身人、7個血怒伏擊者、7個血怒殺戮者和7個血怒遊蕩者。",
    [6283] = "烈日石居的馬格蘭要你去殺掉血怒撕裂者，然後把她的遺體帶回來作為證據。",
    [6284] = "殺掉貝瑟萊斯，然後把貝瑟萊斯的牙齒交給烈日石居的馬格蘭。",
    [6285] = "從獅鷲獸管理員杜加爾·朗德瑞克那裡租用一頭獅鷲獸飛到哨兵嶺，然後將奧斯瑞克的箱子交給哨兵嶺的路易斯。",
    [6301] = "烈日石居的塔姆拉·荒原要你去收集10枚蓋亞之種。",
    [6321] = "將博迪瑞格的訂單交給卡洛斯·拉佐克。",
    [6322] = "將高頓的箱子交給邁克爾·加勒特。",
    [6323] = "從蝙蝠管理員卡洛斯·拉佐克那裡租一隻蝙蝠飛往幽暗城，然後將博迪瑞格的訂單交給幽暗城裡的高頓·溫德哈姆。",
    [6324] = "從蝙蝠管理員邁克爾·加勒特那兒租一隻蝙蝠飛往瑟伯切爾，然後將高頓的箱子交給瑟伯切爾的亡靈衛兵博迪瑞格。",
    [6341] = "將尼莎的貨物交給維斯派塔斯。",
    [6342] = "從角鷹獸管理員維斯派塔斯那裡乘角鷹獸到奧伯丁，然後將尼莎的貨物交給賴爾德。",
    [6343] = "將賴爾德的回信交給尼莎·影歌。",
    [6344] = "與尼莎·影歌談話。",
    [6361] = "帶著獸皮去找十字路口的雙足飛龍管理員迪弗拉克。",
    [6362] = "從雙足飛龍管理員迪弗拉克那裡租一隻馭風者飛往雷霆崖，然後將這捆獸皮交給雷霆崖的安哈努。",
    [6363] = "將安哈努的皮貨交給雷霆崖的塔爾。",
    [6364] = "從雙足飛龍管理員塔爾那裡租用一頭飛往十字路口的雙足飛龍，並把安哈努的皮貨交給加翰·鷹翼。",
    [6365] = "把札爾夫的肉品交給十字路口的迪弗拉克。",
    [6381] = "將10枚蓋亞之種種植在蓋亞土堆中，然後與烈日石居的塔姆拉談話。",
    [6382] = "與梣谷碎木崗哨的塞娜尼·雷心談話。",
    [6384] = "從雙足飛龍管理員迪弗拉克那裡租一隻雙足飛龍飛往奧格瑪，然後將札爾夫的肉品交給奧格瑪的格雷什卡。",
    [6385] = "將格雷什卡的信交給奧格瑪的朵拉斯。",
    [6386] = "從雙足飛龍管理員朵拉斯那裡雇一隻馭風者前往十字路口，然後將格雷什卡的信交給十字路口的札爾夫。",
    [6387] = "將布洛克的名單交給塞爾薩瑪的索格拉姆·伯雷森。",
    [6388] = "將榮譽鋤交給鐵爐堡的格萊斯·瑟登。",
    [6389] = "使用北山伐木場裏的鐵棍放出那裏的瘟疫白蟻，然後向西瘟疫之地冰風崗的納薩尼爾·杜馬報告。",
    [6390] = "使用北山伐木場裡的鐵棍放出那裡的瘟疫白蟻，然後向提里斯法林地亡靈壁壘的米克·萊文報告。",
    [6391] = "從獅鷲獸管理員索格拉姆·伯雷森那裡租一隻獅鷲獸飛往鐵爐堡，然後將布洛克的名單交給鐵爐堡的高尼爾·石趾。",
    [6392] = "從獅鷲獸管理員格萊斯·瑟登那裡租用一頭飛往塞爾薩瑪的獅鷲獸，然後將榮譽鋤交給塞爾薩瑪的布洛克·尋石者。",
    [6393] = "將10塊焚火餘燼交給烈日石居的蘇納曼。",
    [6394] = "將塔茲利爾的鎬還給塔茲利爾。",
    [6395] = "將山繆·菲普斯的遺骸帶到瑪拉的墳墓去，然後回到新兵艾爾雷斯那裡。",
    [6401] = "告訴烈日石居的塔姆拉·荒原這個好消息。",
    [6402] = "前往暴風城的城門。與侍衛洛文交談，他會通知溫德索爾元帥妳已經到達了。",
    [6403] = "跟隨雷吉納德·溫德索爾元帥在暴風城中前進。保護他，別讓他受到傷害！",
    [6421] = "深入滾岩峽谷的洞穴中，為烈日石居的摩羅加爾取回10塊共鳴水晶以供研究。",
    [6441] = "為碎木崗哨的皮克希爾收集16隻薩特的角。",
    [6442] = "將20顆怒尾納迦的頭顱交給佐拉姆海岸的瑪魯凱。",
    [6461] = "瑪拉卡金的辛吉拉要求你殺死10隻深苔爬行者和7隻深苔毒蜘蛛。",
    [6462] = "將8個食人妖符咒交給左拉姆加前哨站的米蘇瓦。",
    [6481] = "使用魔化共鳴水晶打開共鳴桶，然後殺死高戈羅克。將這個消息告訴摩羅加爾，並把魔化共鳴水晶還給他。",
    [6482] = "護送盧爾，然後與碎木崗哨的雅瑪·雪蹄談話。",
    [6501] = "你必須尋遍世界以找到一種能恢復龍眼碎片的能量的生物。你對這種生物的唯一瞭解就是：他們確實存在。",
    [6502] = "你必須從達基薩斯將軍身上取回黑龍勇士之血。 你可以在黑石塔的晉升大廳後面的房間裡找到達基薩斯。",
    [6503] = "殺掉9個梣谷先驅者，然後回到碎木崗哨的庫萊比那裡。",
    [6504] = "找到丟失的12頁伐木機操作指南，把它們合併為第1、2、3章。然後帶著這些書頁回到碎木崗哨去找古爾達·怒痕。",
    [6521] = "把瑪克林大使的頭顱交給幽暗城的瓦里瑪薩斯。",
    [6522] = "把小卷軸交給幽暗城的瓦里瑪薩斯。",
    [6523] = "護送卡雅·扁蹄回到阿帕拉耶營地，然後到石爪山東南邊界附近的瑪卡巴·扁蹄那裡去覆命。",
    [6541] = "到貧瘠之地北部的卡德拉克那裡報到。",
    [6542] = "到貧瘠之地北部的卡德拉克那裡報到。",
    [6543] = "打開報告集，把戰歌報告交給戰歌斥候、戰歌信差和戰歌偵查騎兵。把他們的最新報告交給貧瘠之地北部哨塔上的卡德拉克。",
    [6544] = "保護在銀翼哨站與杜瑞爾·月火作戰的托雷克，然後向慰籍之林的埃爾托格·怒齒彙報勝利的消息。",
    [6548] = "殺掉8個恐怖圖騰惡徒和6個恐怖圖騰傭兵，然後向石爪山脈東南邊界處的瑪卡巴·扁蹄覆命。",
    [6561] = "把夢遊者克爾里斯的頭顱交給雷霆崖的巴珊娜·符文圖騰。",
    [6562] = "與梣谷的耶努薩克雷談話。",
    [6563] = "收集20顆阿庫麥爾藍寶石，把它們交給梣谷的耶努薩克雷。",
    [6564] = "把潮濕的便箋交給梣谷的耶努薩克雷。",
    [6565] = "殺掉黑澗深淵裡的洛古斯·傑特，然後回來找梣谷的耶努薩克雷。",
    [6566] = "聽薩爾講話。",
    [6567] = "按照酋長的指示找到雷克薩。他在石爪山和菲拉斯之間的淒涼之地遊蕩。",
    [6568] = "把雷克薩的證明交給西瘟疫之地的巫女麥蘭達。",
    [6569] = "到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女米蘭達那裡。",
    [6570] = "去塵泥沼澤中的巨龍沼澤，找到艾博斯塔夫的洞穴。進入洞穴後帶上龍形護符，跟艾博斯塔夫交談。",
    [6571] = "收集戰歌族的補給品：戰歌鋸條、伐木繩、戰歌之油，還有一箱戰歌之斧。",
    [6582] = "找到藍龍斯克利爾並殺掉他。從他的身上取下他的顱骨，然後將其交給艾博斯塔夫。 你可以在冬泉谷找到斯克利爾。",
    [6583] = "殺掉綠龍索姆努斯，把他的顱骨交給艾博斯塔夫。",
    [6584] = "諾茲多姆的孩子克魯納里斯在塔納利斯沙漠守衛著時光之穴。殺了牠，把牠的顱骨交給艾博斯塔夫。",
    [6585] = "到格瑞姆巴托去殺掉紅龍埃克托茲，把他的顱骨交給艾博斯塔夫。",
    [6601] = "看來這場猜謎遊戲就要結束了。你知道米蘭達為你製作的龍形護符在黑石塔裡面無法發揮作用，也許你應該去找雷克薩，將你的困境告訴他。把黯淡的龍火護符給他看看，也許他知道下一步該怎麼做。",
    [6602] = "到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。",
    [6603] = "到冬泉谷的溫泉附近尋找多諾瓦·雪山。",
    [6604] = "與墜星村的加隆·石矛談話。",
    [6605] = "與費伍德森林的溫娜·哈薩德談壹談。",
    [6607] = "納特·帕格要你釣到以下幾種魚： 悲傷沼澤的蘆葦海岸大馬哈魚。 淒涼之地的薩瑟里斯海岸虎魚。 菲拉斯沃丹提斯河的菲拉斯草魚。 荊棘谷的野人海岸藍色叉牙魚。 當你釣到這些魚之後，就可以回去找納特·帕格了！",
    [6608] = "妳認為魯瑪克想要告訴妳，他已經不能幫妳提高釣魚的技能了。也許妳應該去找到他的朋友納特·帕格，他居住在塞拉摩以南的某個島嶼上，他是壹名人類漁夫（至少妳認為魯瑪克是這麽說的）。",
    [6609] = "到卡利姆多大陸的塞拉摩去。從那裏向南方出發，找到壹座島嶼。納特·帕格就在島上等待著妳的到來！",
    [6610] = "迪爾格·奎克里弗想要你收集這些原料： 12顆巨蛋。你可以在塔納利斯的大鵬或是其他大型鳥類那裡獲得這種蛋。 10塊美味的蚌肉。你可以從任何蚌類身上獲得這種原料！ 20塊奧特蘭克冷酪。去買就是了！ 收集好所有原料，然後把它們交給迪爾格。",
    [6611] = "到塔納利斯沙漠的加基森去，與迪爾格·奎克里弗談談你的廚師生涯。",
    [6612] = "到塔納利斯沙漠的加基森去，與迪爾格·奎克里弗談談你的廚師生涯。",
    [6621] = "把卡拉恩的旗子插到汙林圖騰堆中。不要讓熊怪摧毀這面旗子。擊敗穆戈特酋長，將穆戈特的圖騰交給左拉姆加的卡拉恩·阿瑪卡。",
    [6622] = "使用急救繃帶來治療病人。你必須在6個病人死亡之前拯救15個病人。 一定要牢記治療的順序！受致命傷的病人會很快死亡，其次是重傷病人，受普通傷的病人死亡得最慢。所以你最好在治療那些受致命傷和重傷的病人之後再去治療受普通傷的病人。",
    [6623] = "到阿拉希高地的落錘鎮去，與格里高利·維克托醫生談一談關於加入部落外科醫療隊的事宜。",
    [6624] = "使用急救繃帶來治療病人。你必須在6個病人死亡之前拯救15個病人。 一定要牢記治療的順序！受致命傷的病人會很快死亡，其次是重傷病人，受普通傷的病人死亡得最慢。所以你最好在治療那些受致命傷和重傷的病人之後再去治療受普通傷的病人。",
    [6625] = "到塵泥沼澤的塞拉摩去，與古斯塔夫·范沃森醫生談一談關於加入聯盟外科醫療隊的事宜。",
    [6626] = "殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌覆命。",
    [6627] = "成功回答布勞格·幽魂的問題，然後和他再次對話。他會一直在石爪山等你回答問題。",
    [6628] = "成功回答帕科瓦·芬塔拉斯的問題，然後再次和他對話。他會一直在幽暗城等你回答問題。",
    [6629] = "殺掉格魯迪格·暗雲和6個恐怖圖騰蠻兵，然後向石爪山東南面的瑪卡巴·扁蹄覆命。",
    [6641] = "在穆格拉什尋找火盆的過程中保障他的安全，幫助他熄滅火盆，然後在與納迦作戰時保護他。 如果你成功了，就回到左拉姆加前哨站去，把鞭笞者沃爾沙的死訊通知給戰歌傳信者。",
    [6661] = "使用捕鼠者之笛捕獲5隻礦道老鼠，把它們引到蒙提那兒去。別忘了退還笛子。",
    [6662] = "把裝著神秘肉品的紙箱交給在暴風城礦道地鐵倉庫的尼普希。",
    [6681] = "把拉文霍德徽記交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。 你的智慧將在這次旅途中得到考驗。做好準備吧。",
    [6721] = "與多蘭納爾的達紮拉談壹談。",
    [6722] = "與多蘭納爾的達紮拉談壹談。",
    [6761] = "與達納蘇斯的塞納里奧區的瑪斯雷·馭熊者談話。",
    [6762] = "與月光林地永夜港的拉比恩·薩圖納談話。月光林地在費伍德森林和冬泉谷之間，可以從木喉要塞中的一條通道抵達那裡。",
    [6804] = "對東瘟疫之地的被感染的水元素使用海神之水。把12副不諧護腕和海神之水交給艾薩拉的海達克西斯公爵。",
    [6805] = "殺死15個灰塵風暴和15個沙漠奔行者，然後回到艾薩拉的海達克西斯公爵那兒。",
    [6821] = "將艾博希爾之眼交給艾薩拉的海達克西斯公爵。",
    [6822] = "殺死壹個火焰之王、壹個熔巖巨人、壹個上古熔火惡犬和壹個熔巖奔騰者，然後回到艾薩拉的海達克西斯公爵那裏。",
    [6823] = "在海達希亞水元素中達到被尊敬的聲望，然後與艾薩拉的海達克西斯公爵談壹談。",
    [6824] = "將魯西弗隆之手、薩弗隆之手、基赫納斯之手和沙斯拉爾之手交給艾薩拉的海達克西斯公爵。",
    [6844] = "將異種蠍粘液包裹的物體交給月光林地永夜港的阿姆伯爾，他是塞納里奧議會的檔案管理員。",
    [6845] = "與月光林地永夜港的拉比恩·薩圖納談壹談。",
    [6921] = "把深淵之核交給梣谷左拉姆加前哨站裡的耶努薩克雷。",
    [6922] = "把奇怪的水球交給梣谷左拉姆加前哨站的耶努薩克雷。",
    [6981] = "前往棘齒城尋找一個人，他能告訴你更多關於發光碎片的事。 然後，將碎片送往被指示的地方。",
    [6982] = "把10份冷齒礦洞補給品交給丹巴達爾的聯盟軍需官。",
    [6985] = "把10份深鐵礦洞補給品交給霜狼要塞的部落軍需官。",
    [7001] = "找到奧特蘭克山谷中的霜狼。使用霜狼口套來馴服它們。被馴服的霜狼會跟隨妳回到獸欄管理員那裏，然後與獸欄管理員談話以獲得妳的獎勵。",
    [7003] = "使用索爾賓的超級壓縮器來縮小菲拉斯的任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集15份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓‧范達瑟。",
    [7027] = "找到奧特蘭克山谷中的山羊。使用雷矛訓練頸圈來馴服它們。被馴服的山羊會跟隨妳回到獸欄管理員那裏，然後與獸欄管理員談話以獲得妳的獎勵。",
    [7028] = "為淒涼之地的維洛收集25個瑟萊德絲水晶雕像。",
    [7029] = "在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。 在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。 治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕覆命。",
    [7041] = "在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。 在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。 治療8株植物並殺死那些諾克賽恩幼體，然後向尼耶爾前哨站的塔琳德莉亞覆命。",
    [7044] = "找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鑽石。 然後設法和塞雷布拉斯對話。",
    [7046] = "幫助贖罪的塞雷布拉斯製作塞雷布拉斯節杖。 當儀式完成之後再和他談談。",
    [7064] = "殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裡覆命。",
    [7065] = "殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裡覆命。",
    [7066] = "到月光林地去找到雷姆洛斯，將生命之種交給他。",
    [7067] = "閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。",
    [7068] = "從瑪拉頓收集10塊暗影殘片，然後把它們交給奧格瑪的尤塞爾奈。",
    [7070] = "從瑪拉頓收集10塊暗影殘片，然後把它們交給塵泥沼澤塞拉摩島上的大法師特沃許。",
    [7081] = "占領壹座墓地，然後向丹巴達爾的諾雷格·雷矛中尉復命。",
    [7082] = "占領壹座墓地，然後向霜狼村的亞斯拉復命。",
    [7101] = "占領敵方的某座哨塔，然後向霜狼村的提卡·血牙復命。",
    [7102] = "摧毀敵方的某座哨塔或者碉堡中的旗幟，然後向丹巴達爾的杜爾根·雷矛復命。",
    [7121] = "與雷矛軍需管談壹談。",
    [7122] = "占領壹座還沒有被雷矛部族控制的礦洞，然後向丹巴達爾的雷矛軍需官復命。",
    [7123] = "與霜狼軍需官談壹談。",
    [7124] = "占領壹座礦洞，然後向霜狼村的霜狼軍需官報告。",
    [7141] = "進入奧特蘭克山谷並擊敗部落將軍德雷克塔爾。然後，再回去找奧特蘭克山脈的勘查員塔雷·石鎬。",
    [7142] = "進入奧特蘭克山谷，擊敗矮人將軍範達爾·雷矛。然後回到沃加·死爪那裏。",
    [7161] = "到主基地東南邊的蠻爪洞穴中去找到霜狼軍旗，然後把它交給拉格隆德。",
    [7162] = "到奧特蘭克山谷的丹巴達爾西南邊找到冰翼洞穴，並取得雷矛軍旗。然後把軍旗交給奧特蘭克山脈的哈格丁中尉。",
    [7181] = "血怒者科爾拉克躲在冰斧洞穴的深處。據說只有在第1001個冰斧巨魔被幹掉的時候，這個強大的冰斧巨魔領袖才會出現。 到冰斧洞穴中去，殺掉所有擋在妳面前的巨魔，直到科爾拉克出現為止。殺掉科爾拉克，然後向拉格隆德復命。",
    [7201] = "到黑石深淵去取得10份元素精華。你應該在那些作戰傀儡和傀儡製造者身上找找，另外，薇薇安‧拉格雷也提到了一些有關元素生物的話題。",
    [7202] = "血怒者科爾拉克躲在冰斧洞穴的深處。據說只有在第1001個冰斧巨魔被幹掉的時候，這個強大的冰斧巨魔領袖才會出現。 到冰斧洞穴中去，殺掉所有擋在妳面前的巨魔，直到科爾拉克出現為止。殺掉科爾拉克，然後向哈格丁中尉復命。",
    [7223] = "給丹巴達爾的莫高特·深爐帶去20塊護甲碎片。",
    [7224] = "給霜狼村的鐵匠雷格薩帶去20塊護甲碎片。",
    [7241] = "到希爾斯布萊德丘陵地區的奧特蘭克山谷去。找到拉格隆德並和他談談，然後成為霜狼氏族的士兵。",
    [7261] = "到希爾斯布萊德丘陵地區的奧特蘭克山谷去。到那裡之後，和哈格丁中尉談談。 為了銅鬚的榮耀！",
    [7281] = "深入雷矛部族的領地，殺掉指揮官卡爾·菲利普。任務完成之後向指揮官劉易斯·菲利普復命。",
    [7282] = "深入霜狼氏族的領地，殺掉指揮官劉易斯·菲利普。任務完成之後，回到指揮官卡爾·菲利普處復命。",
    [7301] = "到霜狼氏族的領地中去搜尋空軍指揮官斯裏多爾、空軍指揮官維波裏和空軍指揮官艾克曼。任務完成之後向指揮官杜菲復命。",
    [7302] = "找到空軍指揮官古斯、空軍指揮官傑斯托和空軍指揮官穆維裏克。任務完成之後向揮官穆法特復命。",
    [7321] = "給塔倫米爾的克里斯多夫·傑弗寇特帶去10塊海龜肉和一些舒心草。",
    [7366] = "妳被指派去殺死奧特蘭克山谷中的被遺忘者玩家。 殺死壹個被遺忘者，然後把壹枚被遺忘者的精華交給指揮官卡爾·菲利普（他壹般在伐木場和礦井之間徘徊）。",
    [7381] = "如果科爾拉克重新出現在奧特蘭克山谷的冰斧山洞中，就找到並幹掉他。 將科爾拉克的徽記交給霜狼要塞的拉格隆德。",
    [7382] = "如果科爾拉克重新出現在奧特蘭克山谷的冰斧山洞中，就找到並幹掉他。 將科爾拉克的徽記交給丹巴達爾的哈格丁中尉。",
    [7383] = "用月井的水裝滿紫水晶瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。",
    [7441] = "到厄運之槌去找到小鬼普希林。你可以使用任何手段從小鬼那裡得到埃斯托爾迪的咒術之書。 找到咒術之書後，回到拉瑞斯小亭的埃斯托爾迪那裡。",
    [7461] = "妳必須幹掉5座水晶塔周圍的守衛，那5座水晶塔維持著關押伊莫塔爾的監獄。壹旦水晶塔的能量被削弱，伊莫塔爾周圍的能量力場就會消散。 進入伊莫塔爾的監獄，幹掉站在中間的那個惡魔。最後，在圖書館挑戰托塞德林王子。 當任務完成之後，到庭院中去找辛德拉古靈。",
    [7463] = "到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。",
    [7481] = "到厄運之槌去尋找泰謬斯·尋夢者。向莫沙徹營地的先知科魯拉克報告你所找到的資訊。",
    [7482] = "到厄運之槌去尋找泰謬斯·尋夢者。向莫沙徹營地的先知科魯拉克報告你所找到的資訊。",
    [7483] = "將急速聖典、1塊原始黑鉆石、2份大塊魔光碎片和2份英雄之血交給厄運之槌的博學者萊德羅斯，以換取壹份急速秘藥。",
    [7484] = "將專註聖典、1塊原始黑鉆石、4份大塊魔光碎片和2張暗影之皮交給厄運之槌的博學者萊德羅斯，以換取壹份專註秘藥。",
    [7485] = "將防護聖典、1塊原始黑鉆石、2份大塊魔光碎片和1份磨損的憎惡縫合線交給厄運之槌的博學者萊德羅斯，以換取壹份防護秘藥。",
    [7486] = "從海達克西斯的箱子拿取妳的獎勵。",
    [7488] = "把蕾瑟塔蒂絲的網交給菲拉斯羽月要塞的拉托尼庫斯·月矛。",
    [7489] = "把蕾瑟塔蒂絲的網交給非拉斯莫沙徹營地的塔羅·刺蹄。",
    [7490] = "將奧妮克希亞的頭顱交給奧格瑞瑪的薩爾。",
    [7491] = "在力量谷找到倫薩克。",
    [7492] = "和菲拉斯莫沙徹營地的塔羅·刺蹄談話。",
    [7494] = "和菲拉斯羽月要塞的拉托尼庫斯·月矛談話。",
    [7495] = "將奧妮克希亞的頭顱交給暴風城的伯瓦爾·弗塔根公爵。",
    [7496] = "在英雄谷找到瑪丁雷少校。",
    [7498] = "將這本典籍交給它的主人。",
    [7499] = "將這本典籍交給它的主人。",
    [7500] = "將這本典籍交給它的主人。",
    [7501] = "將這本典籍交給它的主人。",
    [7502] = "將這本典籍交給它的主人。",
    [7503] = "將這本典籍交給它的主人。",
    [7504] = "將這本典籍交給它的主人。",
    [7505] = "將這本典籍交給它的主人。",
    [7506] = "將這本典籍交給它的主人。",
    [7507] = "將《弗洛爾的屠龍技術綱要》還回圖書館。",
    [7508] = "把黯淡的精靈劍交給博學者萊德羅斯。",
    [7509] = "妳必須設法讓奧妮克希亞對這把未淬火的的上古之刃噴射火焰。完成之後，撿起加熱過的上古之刃。妳要註意的是，加熱過的上古之刃不會壹直保持被加熱的狀態，時間非常緊迫。 在把它給我拿回來之前的最後壹步是殺掉那條龍，並將加熱過的上古之刃插入她的屍體中。 完成這些之後，奎爾塞拉就是妳的了。",
    [7562] = "與燃燒平原的莫蘇爾·召血者談話。",
    [7563] = "把30瓶狂暴野獸的血交給燃燒平原的莫蘇爾·召血者。",
    [7564] = "把血箱交給燃燒平原的戈瑟奇·邪眼。",
    [7581] = "到菲拉斯的厄運之槌去，從扭木廣場的荒野薩特身上找到15份薩特之血，然後把它們交給腐爛之痕的戴奧。",
    [7582] = "到冬泉谷的暗語峽谷去，從盤踞在峽谷中的赫達琳惡魔身上找到5塊赫達琳之淚。完成任務之後回到腐爛之痕的戴奧那裏。",
    [7583] = "在腐爛之痕中找到壹個末日守衛指揮官。 對其使用光芒水晶監牢。妳要做好承受瘋狂攻擊的準備，那個惡魔會拼命掙紮試圖逃脫。 如果妳成功了，就把被囚禁的末日守衛交給腐爛之痕的戴奧。",
    [7601] = "與費伍德森林的伊普斯談話。",
    [7602] = "費伍德的伊普斯要求你從三個不同的地區收集三塊無暇的惡魔精華，然後把它們交給他。 艾薩拉的雷加斯薩特、費伍德森林的加德納爾軍團士兵和詛咒之地的地獄衛士斥候分別擁有一種無暇的惡魔精華。",
    [7603] = "在費伍德森林的碎痕谷中搜尋克羅蘇斯的屍體。當你找到屍體後，在他身上使用魔火，並等待克羅蘇斯復生。當這個地獄火被喚醒之後，幹掉他，從他的身上拿取克羅蘇斯的惡魔之核。 把克羅蘇斯的惡魔之核交給費伍德森林的尼比。",
    [7604] = "如果妳願意接受薩弗隆的設計圖，請將瑟銀兄弟會契約交給羅克圖斯·暗契。",
    [7622] = "在總計有15個農夫被殺死之前拯救50個農夫。完成任務之後與艾瑞斯·哈文法談談。 妳可以通過瀏覽死亡布告來了解自己拯救了多少農夫。",
    [7623] = "從燃燒平原的戈瑟奇那裡購買暗影藥水。 使用這種藥劑進入加德納爾，然後與魔王貝恩霍勒談話。",
    [7624] = "找到並殺死烏拉泰克，然後把叛徒之心交給加德納爾的魔王貝恩霍勒。",
    [7625] = "從烏爾丹那裏購買克索諾斯星塵，把它交給燃燒平原的戈瑟奇·邪眼。",
    [7626] = "把10瓶暗影之力藥劑交給燃燒平原的戈瑟奇·邪眼。",
    [7627] = "把6份大塊魔光碎片和25塊黑鐵礦石交給燃燒平原的戈瑟奇·邪眼。",
    [7628] = "把35塊黑龍鱗片交給燃燒平原的戈瑟奇·邪眼。",
    [7629] = "把瓶中的小鬼帶到通靈學院的鍊金實驗室中。在小鬼製造出羊皮紙之後，把瓶子還給戈瑟奇·邪眼。",
    [7630] = "把3塊奧金錠交給燃燒平原的戈瑟奇·邪眼。",
    [7631] = "閱讀莫蘇爾的指南，並召喚出一匹克索諾斯恐懼戰馬，擊敗它，然後控制它的靈魂。",
    [7632] = "找到遠古石葉的主人。祝妳好運，<name>。這個世界是很大的。",
    [7634] = "費伍德森林的古樹哈斯塔特要求妳帶回壹塊成年藍龍的肌腱。",
    [7635] = "費伍德森林的古樹斯托瑪要求妳帶給他壹塊成年黑龍的肌腱。",
    [7636] = "妳必須找到並幹掉下列4個惡魔： 迷人的西蒙妮。 瘋狂的克林弗蘭。 S屠殺者索倫諾爾。 摧毀者阿托留斯。 殺掉這些惡魔，然後回到費伍德森林的古樹瓦特魯斯那裏去。 根據妳背包中的石化樹皮來找到它們所在位置的線索。 妳必須獨自完成這個任務。",
    [7637] = "到鐵爐堡去找高階牧師洛漢，從他那裏拿到驅魔香爐。妳需要捐贈150金幣來獲得它。",
    [7638] = "與暴風城教堂區的格雷森·沙東布瑞克公爵談壹談。",
    [7639] = "把驅魔香爐交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
    [7640] = "使用驅魔香爐召喚恐懼谷中的靈魂。當妳殺掉25個恐懼谷的靈魂之後，回到暴風城教堂區的格雷森·沙東布瑞克公爵那裏復命。",
    [7641] = "與暴風城矮人區的格瑞曼德·艾爾默談壹談。",
    [7642] = "把40塊符文布、6塊奧金錠、10棵阿爾薩斯之淚、5瓶斯坦索姆聖水和150枚金幣交給暴風城矮人區的格瑞曼德·艾爾默。",
    [7643] = "妳需要特殊的飼料來餵養靈魂馬。南海鎮的梅麗德絲·卡爾森可以為妳提供這樣的糧草。 到菲拉斯的厄運之槌去，殺掉特迪斯·扭木，釋放上古聖馬之魂。用特殊的糧草餵養它，這樣可以安撫它的靈魂。最後，把奧金馬鎧交給它就可以完成祝福。",
    [7644] = "將被祝福的奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
    [7645] = "把制作魔法糧草所需要的重要材料：20塊可口的魔法點心帶給希爾斯布萊德丘陵的梅麗德絲·卡爾森。據說銀色黎明會出售這種餅幹。 妳還需要給她50金幣來對她進行安撫。",
    [7646] = "把壹塊艾澤拉斯鉆石和壹塊原始黑鉆石交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
    [7647] = "在通靈學院屍骨儲藏所地下室的中心使用預言水晶球。將妳要審判的靈魂引領出來。將這些靈魂擊敗然後死亡騎士達克雷爾就將被召喚出來。將其擊敗然後獲得墮落戰馬的靈魂。 把贖罪的戰馬之魂和被祝福的奧金馬鎧壹起附在達克雷爾的墮落戰馬身上。",
    [7648] = "把奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
    [7649] = "將這本典籍交給它的主人。",
    [7650] = "將這本典籍交給它的主人。",
    [7651] = "將這本典籍交給它的主人。",
    [7667] = "如果妳願意幫助奧格瑞瑪智慧谷的薩格尼，就將壹塊艾澤拉斯鉆石和壹塊原始黑鉆石交給他。",
    [7670] = "與暴風城教堂區的格雷森·沙東布瑞克公爵談壹談。",
    [7701] = "那個叫做工頭瑪托留斯的黑鐵矮人叛徒就藏在大熔爐的熔渣之池深處。 殺死工頭瑪托留斯，將他的頭顱交給灼熱峽谷的偵查隊長洛洛爾以換取你的獎勵。",
    [7703] = "找到戈多克力量護手，並將它交給厄運之槌的克羅卡斯。 根據克羅卡斯所說的，「傳說」自稱是王子的精靈托塞德林從一名戈多克巨魔手中偷走了那件神器。",
    [7721] = "從菲拉斯被遺忘的海岸那裡的海元素和巨型海元素身上獲取10塊水元素核心，把它們交給碼頭附近的索爾賓·范達瑟。",
    [7722] = "在大熔爐的熔渣之池中的某個地方，你可以找到工頭瑪托留斯偷走的秘密設計圖：熾熱助熔劑。找到這些設計圖，把它們還給灼熱峽谷的大鐵匠博恩奈特。",
    [7723] = "漢瑟爾·重拳讓你殺掉20個重型作戰傀儡。 重型作戰傀儡就在灼熱峽谷的大熔爐附近。當你殺死足夠多的傀儡後，就回去找漢瑟爾·重拳。",
    [7724] = "漢瑟爾‧重拳要你殺死灼熱峽谷中的20隻灼熱熔岩蜘蛛。你可以在灼熱峽谷的高地和熔岩池裡找到灼熱熔岩蜘蛛。 當你殺死足夠的灼熱熔岩蜘蛛之後，回到漢瑟爾‧重拳那裡覆命。",
    [7725] = "使用索爾賓的超級壓縮器來縮小菲拉斯裡任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集10份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓·范達瑟。",
    [7726] = "從菲拉斯被遺忘的海岸那裡的海元素和巨型海元素身上獲取6塊水元素核心，把它們交給碼頭附近的索爾賓·范達瑟。",
    [7727] = "漢瑟爾·重拳要你去殺掉20隻燻火龍。 燻火龍侵佔了熔渣之池中的那些岩漿池。熔渣之池就在灼熱峽谷的大熔爐中。 當你殺死足夠數量的燻火龍後，就回到灼熱峽谷找漢瑟爾·重拳。",
    [7728] = "找到冶煉鼓風機和偵查員的望遠鏡，把它們還給灼熱峽谷的監工斯克蘭格。 你所知道的關於這些物品的惟一資訊是：它們肯定是被黑鐵矮人偷走的。冶煉鼓風機是鐵匠用的鍛造工具，偵查員的望遠鏡是偵查員所需的偵查工具。",
    [7729] = "殺死15個黑鐵工頭和15個黑鐵奴隸販子。完成任務之後就回去找監工斯克蘭格。",
    [7730] = "把20塊祖卡什蟲殼交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。",
    [7731] = "擊敗痛苦深淵中的毒刺鞭笞者，把它的腺體交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。",
    [7732] = "把莫沙徹營地祖卡什報告交給奧格瑪暗巷區的基爾茲賓·鼓眼。",
    [7733] = "把10塊怒痕雪人的毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。",
    [7734] = "把10塊怒痕雪人的毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。",
    [7735] = "把原始雪人毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。",
    [7738] = "把完美的雪人毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。",
    [7761] = "真是個愚蠢的獸人。看來妳需要找到那枚烙印並獲得達基薩斯徽記才可以使用命令寶珠。 妳從信中獲知，達基薩斯將軍守衛著烙印。也許妳應該就此進行更深入的調查。",
    [7781] = "將奈法利安的頭顱交給暴風城的伯瓦爾·弗塔根公爵。",
    [7782] = "回到暴風城的英雄谷，與艾法希比元帥談壹談。",
    [7783] = "將奈法利安的頭顱交給奧格瑞瑪的薩爾。",
    [7784] = "和奧格瑞瑪的薩魯法爾大王談談。他在力量谷等妳。",
    [7785] = "查看復生之瓶，然後回到德米提恩那裏去。",
    [7786] = "如果妳想要把逐風者桑德蘭從監牢裏釋放出來，妳就必須找到左右兩塊逐風者禁錮之顱，10塊源質錠，以及火焰之王的精華，把它們交給德米提恩。",
    [7787] = "把風吻之刃交給德米提恩。",
    [7790] = "沿著索多里爾河尋找天裔精靈為何受害的線索。",
    [7810] = "與荊棘競技場的小個子約翰·米斯瑞爾談話。",
    [7815] = "辛特蘭惡齒村的釣魚者卡圖姆要你去殺掉15隻海水鉗嘴龜。完成任務之後回到他那裡去覆命。",
    [7816] = "辛特蘭惡齒村的釣魚者卡圖姆要你去殺掉加莫里塔，並從它的屍體上找到卡圖姆的超級魚餌。 卡圖姆說加莫里塔和其他海龜都在海岸附近活動。",
    [7828] = "辛特蘭惡齒村的獵戶馬克霍爾要求你去殺掉15頭銀鬃捕獵者和15頭銀鬃嗥狼。完成任務之後就回到他那裡覆命。 馬克霍爾說過那些狼都躲在辛特蘭的野外。",
    [7829] = "辛特蘭惡齒村的獵戶馬克霍爾要求你去殺掉20頭野蠻的梟獸。完成任務之後就回到他那裡覆命。 馬克霍爾說過那些野蠻的梟獸都躲在辛特蘭的野外。",
    [7830] = "辛特蘭惡齒村的獵戶馬克霍爾要求你殺掉一頭翱翔的鋒喙獅鷲獸，並將它的獅鷲獸長羽拿回去交給他。 馬克霍爾說過那些翱翔的鋒喙獅鷲獸就躲在辛特蘭的野外。",
    [7839] = "辛特蘭惡齒村的鐵匠斯拉提要你去找到斯拉提的工具。完成任務之後就回到他那裡去。 你記得鐵匠斯拉提說過，你可以在辛特蘭東北部的某個邪枝食人妖神廟中找到它，要不然就是在隱匿石那邊。",
    [7840] = "辛特蘭惡齒村的拉爾德要求你去找到拉爾德的午餐。完成任務之後就回到他那裡去。 拉爾德說他把午餐留在了北面的島上。當心邪枝食人妖。",
    [7841] = "辛特蘭惡齒村的奧索·莫吉克要你去殺掉15個高原前鋒、15個高原斥候、15個高原神射手和15個高原遊俠。任務完成之後回到他那裡去覆命。 你可以在辛特蘭西北部的奎爾丹尼小屋找到那些高原精靈。",
    [7842] = "辛特蘭惡齒村的奧索·莫吉克要你從辛特蘭的獅鷲獸身上收集10根細長的獅鷲獸羽毛。任務完成之後回到他那裡去覆命。 在辛特蘭各處都有獅鷲獸出沒。",
    [7843] = "辛特蘭惡齒村的奧索·莫吉克要你去辛特蘭西部的鷹巢山，把給蠻錘部族的警告插在城鎮中心的水井旁邊。任務完成之後回到他那裡去覆命。 當心那些憤怒的蠻錘矮人以及野蠻的聯盟成員。",
    [7844] = "辛特蘭惡齒村的秘法師雅爾金要你去殺掉30個邪枝割顱者和15個邪枝占卜者。任務完成之後回到他那裡去覆命。 秘法師雅爾金說過，你可以在辛特蘭東北部的沙爾瓦薩和亞戈瓦薩神廟附近找到那些食人妖。",
    [7845] = "辛特蘭惡齒村的斷齒族長要求你到辛薩羅去拯救她的愛人，斷齒長者。 你聽說他被關在辛薩羅頂部，辛薩羅位於辛特蘭的南部地區，那裡是邪枝食人妖的主城。",
    [7846] = "辛薩羅的斷齒長者要求你殺掉守護者希坦亞，並用她身上的鐐銬鑰匙打開他的鐐銬。當你找到鑰匙之後就回到他那裡去。",
    [7847] = "辛薩羅的斷齒長者要求你將他已經被營救的消息帶給惡齒村的斷齒族長。",
    [7848] = "進入黑石深淵，在通往熔火之心的傳送門附近找到壹塊熔火碎片，然後回到黑石山脈的洛索斯·天痕那裏。",
    [7849] = "辛特蘭惡齒村的獵戶馬克霍爾要你去找回他的雙胞胎兄弟的屍體。找到它，然後把獵戶莫克霍爾的頭顱和獵戶莫克霍爾的骨頭交給獵戶馬克霍爾。 馬克霍爾說過，他兄弟的屍體被軟泥怪和邪枝食人妖的狼群分食。他還提到在辛薩羅有個大坑，裡面全都是軟泥怪，那裡還有個狼穴。這兩個地方都在靠近辛薩羅神廟頂部的區域。",
    [7850] = "辛特蘭惡齒村的斷齒族長要你在辛薩羅找到10瓶腐化之血。任務完成之後就回到斷齒族長那裡。",
    [7861] = "你必須殺掉邪惡祭司海克斯和20名邪枝精英守衛。任務完成之後回到辛特蘭的惡齒村，向斷齒族長報告。 你可以在辛特蘭的邪枝食人妖城市辛薩羅的頂部找到他們。",
    [7862] = "你必須消滅20個邪枝狂戰士、20個邪枝暗影獵手、20個邪枝飲血者和20個邪枝噬魂者。 完成任務之後向辛特蘭惡齒村的斷齒族長覆命。",
    [7877] = "返回圖書館去找到辛德拉的寶藏。拿取妳的獎勵吧！",
    [7907] = "當暗月馬戲團來到鎮上的時候，把野獸套牌交給他們。",
    [7927] = "當暗月馬戲團來到鎮上的時候，把入口套牌交給他們。",
    [7928] = "當暗月馬戲團來到鎮上的時候，把督軍套牌交給他們。",
    [7929] = "當暗月馬戲團來到鎮上的時候，把元素套牌交給他們。",
