    [8105] = "進攻礦洞、伐木場、鐵匠鋪和農場，然後向避難谷地的奧斯萊特元帥復命。",
    [8114] = "進入阿拉希盆地，同時占據並控制四座基地，當任務完成之後向避難谷地的奧斯萊特元帥報告。",
    [8115] = "同時控制阿拉希盆地中的5座基地，然後向避難谷地的奧斯萊特元帥覆命。",
