    [8170] = "進攻阿拉希盆地的礦坑、伐木場、鐵匠舖和獸欄，然後向落錘鎮的屠殺者杜維爾覆命。",
    [8171] = "進攻阿拉希盆地的礦坑、伐木場、鐵匠舖和獸欄，然後向落錘鎮的屠殺者杜維爾覆命。",
