    [8235] = "將10片加密的碎片交給艾薩拉的大法師克希雷姆。",
    [8236] = "將碧藍鑰匙交給喬拉齊·拉文霍德公爵。",
    [8240] = "將妳在祖爾格拉布找到的哈卡萊寶石帶往尤亞姆巴島的贊紮祭壇進行銷毀，然後跟祭壇旁邊的溫卡薩談壹談。",
    [8250] = "尋找薩納斯並獲得見到大法師克希雷姆的通路。",
    [8251] = "為大法師克希雷姆收集10份閃光塵埃。",
    [8252] = "收集6塊魔化珊瑚，然後把它們交給大法師克希雷姆。",
    [8253] = "從摩弗拉斯身上取回奧術碎片，然後返回大法師克希雷姆那兒。",
    [8254] = "尋找艾薩拉的奧汀克。",
    [8255] = "收集4份健康的野鹿腺體並把它們帶給艾薩拉的奧汀克。奧汀克住在埃達拉斯廢墟東北部懸崖的頂部。",
    [8256] = "為艾薩拉的奧汀克帶回1份亡靈腐液。奧汀克住在埃達拉斯廢墟東北部懸崖的頂端。",
    [8257] = "前往沉沒的神廟阿塔哈卡，殺死摩弗拉斯，將他的血液交給費伍德森林中的格雷塔·苔蹄。沉沒的神廟的入口就在悲傷沼澤。",
    [8258] = "在通靈學院地下室的屍骨儲藏所的中心使用預言水晶球，然後與被召喚出來的幽靈作戰。擊敗這些幽靈之後，死亡騎士達克雷爾才會出現，妳的任務就是擊敗他。 把死亡騎士達克雷爾的徽記交給奧格瑞瑪智慧谷的薩格尼。",
    [8275] = "和在希利蘇斯塞納里奧城堡裡的喚風者普勞豪恩談話。",
    [8276] = "和在希利蘇斯塞納里奧城堡裡的喚風者普勞豪恩談話。",
    [8277] = "希利蘇斯的塞納里奧城堡的比提克斯·斯巴格要你去收集8只石鞭蠍刺和8只掠沙蜘蛛毒牙。完成任務後回到她那裡。",
    [8278] = "希利蘇斯塞納里奧城堡的比提克斯·斯巴格要你去收集3只石鞭巨鉗蠍刺，3只石鞭掠奪者刺，和3只石行蜘蛛毒牙。",
    [8279] = "將暮光詞典的3章帶給希利蘇斯的隱士奧泰爾。",
    [8280] = "希利蘇斯的塞納里奧城堡的喚風者普勞豪恩要你去殺15個掘泥打擊者。",
    [8281] = "希利蘇斯的塞納里奧城堡的喚風者普勞豪恩要你去殺20個掘泥摧毀者。",
    [8282] = "到希利蘇斯南邊山區找回諾格的背包，並回到塞納里奧城堡交還給他。",
    [8283] = "將死亡彎鉤的刺針帶給守衛隊長維斯·庫魯茲。",
    [8284] = "希利蘇斯的塞納里奧城堡的地理學家拉克斯班要你去收集8個暮光石板碎片。",
    [8285] = "帶著修補的石板去找希利蘇斯的隱士奧泰爾。",
    [8286] = "前往塔納利斯的時光之穴尋找諾茲多姆的子嗣，阿納克洛斯。 完成任務後回到希利蘇斯塞納裏奧要塞的流沙守望者巴裏斯托爾斯那兒。",
    [8287] = "將解譯過的碑文羊皮紙交給指揮官瑪爾利斯。",
    [8288] = "到黑石山中的奈法利安巢穴去，殺死勒什雷爾，並帶回它的徽記。 將勒什雷爾的徽記交給希利蘇斯塞納裏奧要塞的流沙守望者巴裏斯托爾斯。",
    [8301] = "希利蘇斯塞納裏奧要塞的流沙守望者巴裏斯托爾斯想要妳殺死亞什蟲巢、佐拉蟲巢和雷戈蟲巢中的異種蟲類。從死去的蟲子屍體上收集異種蠍殼碎片。當妳收集到200塊異種蠍殼碎片時，回到巴裏斯托爾斯那兒去。 作為壹名諾茲多姆的特使，只有妳和妳的副官可以從異種蟲類的屍體上拾取異種蠍殼碎片。請註意保持妳的包裹空間足夠多。",
    [8302] = "為流沙守望者巴里斯托爾斯收集200塊異種蠍殼碎片。",
    [8303] = "到塔納利斯的時光之穴去尋找阿納克洛斯。",
    [8304] = "希利蘇斯，指揮官瑪爾利斯要你去詢問銅鬚營地的矮人居住者。你可以在塞納里奧城堡南邊找到銅鬚營地。 當你收集到需要的資訊再回去找指揮官瑪爾利斯。",
    [8305] = "希利蘇斯時光之穴的阿納克洛斯想要妳前往位於希利蘇斯南部沙漠的甲蟲之臺。 當妳學習完畢後再回到他那兒去。",
    [8306] = "希利蘇斯，塞納里奧城堡的指揮官瑪爾利斯要你去找尋他摯愛的娜塔莉亞。你所收集到的資訊指出，南方的雷戈蟲巢就是你可以找到娜塔莉亞·瑪爾利斯夫人的地方。 別忘記在進入蟲巢之前先去拜訪銅鬚營地的矮人。他們可能有一些額外的工作和建議要給你。 還有<name>，記得指揮官的話:「做你該做的...」",
    [8307] = "在塞納里奧城堡西方的暮光之錘營地尋找關於烹煮沙蟲肉的資訊。",
    [8308] = "將布拉恩·銅鬚的信帶到希利蘇斯南邊的銅鬚營地去。",
    [8309] = "希利蘇斯銅鬚營地的魯特加爾·雕石想要你前往亞什蟲巢、佐拉蟲巢和雷戈蟲巢，從蟲巢中的雕文水晶上取下拓文。 使用地質學家的抄錄工具包獲取古老雕文的摹本。完成任務後回到魯特加爾·雕石那兒。",
    [8310] = "希利蘇斯銅鬚營地的法蘭克爾·石橋想要你取回一個亞什異種蟲腦、一個佐拉異種蟲腦和一個雷戈異種蟲腦。完成任務後回到法蘭克爾那兒。",
    [8313] = "將破碎的食譜交給塞納里奧城堡旅店中的卡蘭德拉斯。",
    [8314] = "銅須營地的魯特加爾·雕石想讓妳將雕文水晶棱柱交給希利蘇斯塞納裏奧要塞的地質學家拉克斯班。",
    [8315] = "希利蘇斯塞納裏奧要塞的地質學家拉克斯班想讓妳從其拉蟲人使者那裏取回水晶分解裝置。 妳已經奉命將召喚雕文帶往塞納裏奧要塞以南的格拉卡洛之骨處，將它們從沙中引出。壹旦其拉蟲人使者露面，就殺死它，獲得水晶分解裝置。成功之後回到地質學家拉克斯班那兒去。 妳必須召集壹支強大的軍隊來完成這項任務，<name>！",
    [8317] = "塞納里奧城堡的卡蘭德拉斯需要製作10個沙漠肉丸子的麵團。",
