    [93160] = "在影風森林收集8個影風橡實。",
    [93161] = "找找看有沒有人對你在班奈薩爾廢墟發現的遠古劍柄感興趣。",
    [93165] = "在影風森林、奧基爾聖殿和風莓低地收集5個奧拉凱斯教徒的耳朵。",
    [93172] = "在影風森林消滅10個風之空靈。",
    [93176] = "使用昆蟲學入門套件裡的物品來尋找和捕捉喬木狼蛛、乾草象鼻蟲樣本和剔肉蠍。",
    [93188] = "繼續和瑪格拉姆部族保持良好的關係，之後向白骨之谷北方入口附近的歐魯爾回報。",
    [93196] = "繼續和瑪格拉姆部族保持良好的關係，進行死靈儀式復活傑恩可汗。儀式地點在瑪格拉姆村中央湖泊的帳篷。",
    [93197] = "在海加爾山的山頂營地向塞貝莉雅拿取郵件包裹，帶去給永望鎮的旅店老闆維茲奇。",
    [93224] = "殺死淒涼之地任何氏族的半人馬，取得5個雕刻半人馬圖騰，然後將其帶回去給尼耶爾前哨站的潘迪加斯上尉。",
    [93225] = "殺死淒涼之地任何氏族的半人馬，取得5個雕刻半人馬圖騰，然後將其帶回去給鬼旅崗哨的古爾達‧蠻鬃。",
    [93226] = "前往淒涼之地的瑪格拉姆村，將圖騰手提包交給瑪格拉姆軍需官，大幅提高你在該部族的聲望。你的瑪格拉姆半人馬聲望必須至少是中立。",
    [93227] = "前往淒涼之地的吉爾吉斯村，將圖騰手提包交給吉爾吉斯軍需官，大幅提高你在該部族的聲望。你的吉爾吉斯半人馬聲望必須至少是中立。",
    [93269] = "將永望鎮的郵件帶去給海加爾山山頂的旅店老闆塞貝莉雅。",
    [93317] = "收集6塊風歌蟹肉。",
    [93318] = "在申德高地殺死『貪食者』弗加拉，並將她的頭顱帶給達納里‧吼幕。",
    [93319] = "從申德高地的高地強盜身上收集10個被偷走的風石。",
    [93320] = "到風莓低地的東部瞭望塔向優菈娜‧風葦回報。",
    [93341] = "調查申德拉斯附近的淒涼花園，接著再回到附近的神殿和蜜瑟菈回報。",
    [93362] = "剷除淒涼花園裡的植物，接著再回去申德拉斯找蜜瑟菈。",
    [93383] = "等到你可以安全開啟個人求生包",
    [93394] = "在申德拉斯神殿中尋找博學者奇蘭迪斯。",
    [93404] = "前往瑪拉頓並取回一瓶大地之歌水，然後回去淒涼之地的淒涼花園找森詭。",
    [93406] = "在永望鎮北邊的山丘上尋找4封遺失的郵件，將其帶回去給旅店老闆維茲奇。",
    [93407] = "在海加爾山山頂的森林裡尋找荊棘種子，將它們帶回去給提雅拉‧白鬃。",
    [93422] = "殺死黑荊信差，並劫走她帶的消息。",
    [93429] = "到農田避難所殺死10個失落者。",
    [93430] = "找到偷走佩魯克誘餌的失落者漁夫，並取回誘餌。",
    [93443] = "前往大河林地的火線港，將遺失的貨箱交給佛利茲‧焦炫。",
    [93444] = "擊殺夜刃豹守護者，然後再到山頂的北方山脊，用夜刃豹守護者的腰肉引出並殺死剛蘇羅克。 帶著奇美拉的心臟返回。",
    [93450] = "找到把范戴爾未完成的劍送到靈魂國度的辦法，接著再把幻魅之刃帶回申德拉斯，然後交給他。",
    [93461] = "在申德村與拉斯里爾‧日槍和珂瑞菈‧靜風交談。",
    [93464] = "到淒涼之地找到了解德萊尼水晶之力的法師。",
    [93465] = "拿走吉瑪席關於德萊尼水晶的筆記，然後帶回去給阿佐爾‧奧達蒙特。",
    [93510] = "在止水湖尋找戰爭老兵兒時回憶中的錨。",
    [93521] = "將維漢的研究報告帶去給提雅拉‧白鬃。",
    [93546] = "在申德拉斯附近尋找鬼靈鐵礦床，並收集10個鬼靈鐵礦石。收集夠了之後，再回到申德拉斯找范戴爾。",
    [93547] = "在旅店、儲藏塔和忠誠派德魯伊營地的樹叢附近種下荊棘種子。",
    [93551] = "前往海加爾山，在哀悼之眠的壞掉的火砲附近使用鑲邊劍鞘，與第三次大戰的精兵碰面。",
    [93552] = "在坦德爾林地從原始風石身上收集15個風石簇。",
    [93567] = "在哀悼之眠的壞掉的火砲旁，讓第三次大戰的精兵訴說他的故事。",
    [93568] = "把部分消化的項圈交給知道的人。你應該可以在淒涼之地的申德拉斯找到他。",
    [93574] = "尋找對食屍者的甲殼感興趣的人。",
    [93584] = "擊殺10個黑荊精兵和10個荒烙教徒",
    [93585] = "護送塔托神父到避難營。",
    [93594] = "到淒涼之地，在申德拉斯的淒涼花園中尋找森詭。",
    [93601] = "在刺背居所尋找關鍵的野豬人。",
    [93604] = "前往剃刀高地並取得惡性阿迦瑪甘之血，然後將它帶回去淒涼之地給刺背居所的『勇者』柯薩。柯薩認為有必要提醒你，剃刀沼澤的阿迦瑪甘之血無法讓他滿意。",
    [93606] = "把慈愛花束和惡性阿迦瑪甘之血交給闊兒佳來彌補野豬人的關係。用來製作花束的花卉可以到淒涼之地，在申德拉斯附近的淒涼花園採摘。",
    [93609] = "到淒涼之地的申德拉斯神殿，把遭棄的項鍊交給蜜瑟菈。",
    [93615] = "在海加爾山的荒野尋找夏拉卡的小貓。",
    [93617] = "勸阻雄鹿不要扮演掠食者。",
    [93644] = "上頭的文字顯示，這本日誌的作者就在申德拉斯某處。",
    [93663] = "找到失蹤的信差，並確保達爾的貨物送達避難營。",
    [93678] = "將阿佐爾改寫的筆記帶回悲傷沼澤，交給避難營的瑪格圖爾。",
    [93679] = "與瑪格圖爾一同觀看歐庫的幻象。",
    [93680] = "為塔倫米爾的魔導師沃迪恩‧虛無之光取得達拉然下水道鑰匙。",
    [93684] = "找到在詛咒之地搜尋德萊尼水晶的德萊尼。",
    [93735] = "到瓦拉納爾西邊找里安尼‧夜風。",
    [93736] = "在影風森林從風之空靈身上收集10個風之空靈精華。",
    [93737] = "與里安尼‧夜風談話，聽聽他說了什麼。",
    [93738] = "到瓦拉納爾向阿雅莎‧曦詠回報。",
    [93739] = "在葛羅瑪許堡與納茲格雷爾交談，接收進一步的指示。利用收到的指示尋找沃金、凱恩‧血蹄，和希瓦娜斯‧風行者女士，並與其交談。",
    [93740] = "在風莓低地從奧拉凱斯教徒的遺體上收集10個奧拉凱斯風石符咒。",
    [93746] = "在前往奧基爾聖殿的路上面對貝拉桑‧亮願。",
    [93747] = "在毀壞的弩砲、毀壞的投石車以及毀壞的飛行器附近種植附魔種子。",
    [93759] = "從未受污染的海加爾雄鹿身上收集2片海加爾鹿肉片，以及6個血色飛鏢塊莖，讓隱士製作燉肉。",
    [93773] = "在海加爾山向柯薩拉斯回報。",
    [93786] = "殺死12個草原溪地雇農，然後向克隆羅許回報成功的消息。",
    [93787] = "從草原溪地的聯盟農場竊取6個餵食背袋，然後回去找克隆羅許。",
    [93788] = "為羅格瑪的克瑞莎‧黑棘在透納的伐木場從伐木工身上取回10把木工斧頭。",
    [93791] = "和瓦拉納爾的貝藍‧風木交談。",
    [93797] = "把風能灌注樹枝交給瓦拉納爾的貝藍‧風木。",
    [93825] = "收集12團月幕苔蘚，然後回去找蘇瑪‧苔鬃。",
    [93826] = "擊敗8個死木圖騰師和8個死木護魔者，然後回去找松語長者",
    [93827] = "收集16個附魔鷹身人護符，然後回去找索博‧液爪。",
    [93828] = "從樹皮地穴四周收集10份曬乾的懸掛草藥，然後將它們帶回去給芬納‧苔鬃",
    [93830] = "在死木熊怪巢穴外的池塘，裝滿一個由芬納‧苔鬃提供的水囊。",
    [93831] = "在海加爾山收集30顆熊莓，然後回去找歐西‧霧爪。",
    [93832] = "前往海加爾山上層，在被摧毀的聯盟營地消滅6隻永恆哨兵石像鬼，然後回去找霧爪長者。",
    [93833] = "將5具貓頭鷹屍體帶去給海加爾山樹皮地穴的松語長者",
    [93834] = "為達拉‧正喉收集10個鑽地甲蟲碎塊。",
    [93835] = "使用傳送門到上方的羅哈希尖塔，並與伊拉德林‧和風和阿雅莎‧曦詠面對高階女祭司洛舒娜。",
    [93836] = "在瓦拉納爾和塔拉尼斯‧影歌交談。",
    [93848] = "回去找柯薩拉斯，告訴他永恆山峰發生的事。",
    [93926] = "到西部瞭望塔找保安官梵尼爾。",
    [93927] = "在陣亡的保安官附近收集紙條，並閱讀其中內容來決定下一步該怎麼做。",
    [93948] = "到瓦拉納爾把影歌家族璽戒交給塔拉尼斯‧影歌。",
    [93949] = "在瓦拉納爾殺死空躍者，直到你殲滅8隻附魔空躍者為止。",
    [93951] = "在申德高地收集8根角鷹獸羽絨。",
    [93952] = "擊敗9個死木巢穴守護者，然後回去找布瑞魯法",
    [93958] = "到奧基爾聖殿的聖殿內廳與維菈妮雅‧颶拳交談。",
    [93963] = "在暴風要塞與蘭德爾‧艾默森交談，接收進一步的指示。利用收到的指示尋找麥格尼‧銅鬚國王、大工匠梅卡托克，和泰蘭妲‧語風，並與其交談。",
