    [94369] = "在瓦拉納爾和塔拉尼斯‧影歌交談。",
    [94373] = "把2個霜鬃熊紋墜飾交給安威瑪的提歐‧錘暴。",
    [94374] = "找到靈魂之石並喝下大地靈契。",
    [94375] = "將粗石英帶去給安威瑪的提歐‧錘暴。",
    [94411] = "在申德高地殺死6名高天盟學徒。",
    [94413] = "在申德高地殺死6名塑風者見習先知。",
    [94414] = "與哈剌‧鷹眼交談，並藉著他的能力，從遠方觀看錨塔。",
    [94427] = "到幽暗城與塔尼斯‧奧德伍德交談。",
    [94434] = "把10個亞麻布交給幽暗城的塔尼斯‧奧德伍德。",
    [94435] = "回到班達利昂要塞找丹妮莎‧莫爾。",
    [94436] = "在班達利昂要塞與亡靈衛兵比爾穆交談。 如果你弄丟生命符記的話，就再回去找丹妮莎‧莫爾拿一個。",
    [94438] = "帶著生命符記，然後在毒蛛峽谷讓亡靈衛兵法爾根復生。 如果你弄丟生命符記的話，就再回去找丹妮莎‧莫爾拿一個。",
