    [94441] = "到班達利昂要塞內和丹妮莎‧莫爾交談。",
    [94449] = "到丹莫洛找布魯格斯‧燃裔。",
    [94465] = "把眠炎火炬交給洛克莫丹的布拉迪爾‧塵披。",
    [94466] = "找到1個火焰焦油和1個試劑袋，把它們交給洛克莫丹的布拉迪爾‧塵披。",
    [94467] = "擊敗小型火焰之靈體，將餘燼放在恒焰聖殿屋頂的火盆裡。",
    [94468] = "將恆焰火炬交給丹莫洛的布魯格斯‧燃裔。",
    [94479] = "在污化丘陵四處查訪，尋找對你找到的金屬物體感興趣的人。",
    [94480] = "將遭竊的飼料交給羅格瑪的高格。",
    [94481] = "讓訓練場的8個羅格瑪受訓者飽餐一頓。",
    [94483] = "在南邊河畔殺死8個遠境堡牧師和12個遠境堡斥候。",
    [94484] = "到影風森林東北方找到伊蕾嘉兒‧荊爪，並與她交談。",
    [94485] = "收集8個女士之淚苔蘚。",
    [94486] = "在影風森林從影風始祖鳥身上收集20根羽毛。",
    [94487] = "在影風森林從奧拉凱斯步行兵和奧拉凱斯追風者身上收集10個染血傳家寶。",
