    [94491] = "把信函交給瓦拉納爾的洛瑟倫，然後告訴他發生什麼事。",
    [94493] = "到影風森林東北方與伊蕾嘉兒‧荊爪交談。",
    [94494] = "到洛克莫丹尋找諾里克‧洛克賽恩。",
